=== FORK NOTICE ===
Kode internal masih membawa nama fungsi/tabel dari DonasiYuk (prefix `dja_`, fungsi `donasiaja_*`).
Pembaruan nama akan dilakukan bertahap sesuai roadmap di ../prd.md.
Saat ini plugin ini AMAN di-install berdampingan dengan DonasiYuk original selama prefix tabel WP
berbeda (lihat `dyk_options_install` — tabel otomatis mengikuti `$wpdb->prefix`).
Jika ingin prefix tabel terpisah, set `define('DYK_TABLE_PREFIX', 'dyk_');` di wp-config.php
sebelum plugin aktif (fitur opsional, memerlukan patch pada set_dja_options_install).
=== END FORK NOTICE ===
*/

if ( ! defined( 'ABSPATH' ) ) {
	die;
}

define('ROOTDIR_DYK', plugin_dir_path(__FILE__));

// PSR-4 Autoloader fallback for DonasiYuk namespace
spl_autoload_register(function ($class) {
    $prefix = 'DonasiYuk\\';
    $base_dir = ROOTDIR_DYK . 'src/';
    $len = strlen($prefix);
    if (strncmp($prefix, $class, $len) !== 0) {
        return;
    }
    $relative_class = substr($class, $len);
    $file = $base_dir . str_replace('\\', '/', $relative_class) . '.php';
    if (file_exists($file)) {
        require_once $file;
    }
});

if ( file_exists( ROOTDIR_DYK . 'vendor/autoload.php' ) ) {
    require_once ROOTDIR_DYK . 'vendor/autoload.php';
}

if ( class_exists( 'DonasiYuk\\Core\\Bootstrap' ) ) {
    add_action( 'plugins_loaded', function() {
        \DonasiYuk\Core\Bootstrap::getInstance();
    }, 5 );
}

if ( file_exists( ROOTDIR_DYK . 'includes/module-loader.php' ) ) {
    require_once ROOTDIR_DYK . 'includes/module-loader.php';
    add_action( 'plugins_loaded', 'dyk_load_domain_modules', 10 );
}

function dyk_options_install() {
    // RACE-CONDITION-FIX (M4): Activation can fire concurrently if two admins click
    // "Activate" simultaneously, or if the plugin is auto-activated during a WP
    // upgrade. Hold a 60-second transient lock so the migration runs serially.
    $lock_key = 'dyk_options_install_lock';
    if ( get_transient( $lock_key ) ) {
        return;
    }
    set_transient( $lock_key, 1, 60 );

    // Step 1: Migrate legacy DonasiAja tables (dja_*) to DonasiYuk (dyk_*) if exist.
    require_once ROOTDIR_DYK . 'migrations/2026_08_21_001_rename_tables_dja_to_dyk.php';
    if ( function_exists( 'donasiyuk_migrate_rename_tables_dja_to_dyk' ) ) {
        donasiyuk_migrate_rename_tables_dja_to_dyk();
    }
    // Step 2: Fresh install schema (idempotent via dbDelta).
    set_dja_options_install();

    // Step 2b: Schema version table & normalized campaign fields (M3).
    require_once ROOTDIR_DYK . 'migrations/2026_08_22_000_schema_version.php';
    if ( function_exists( 'donasiyuk_migrate_schema_version_table' ) ) {
        donasiyuk_migrate_schema_version_table();
    }
    require_once ROOTDIR_DYK . 'migrations/2026_08_22_001_normalize_campaign_fields.php';
    if ( function_exists( 'donasiyuk_migrate_normalize_campaign_fields' ) ) {
        donasiyuk_migrate_normalize_campaign_fields();
    }

    // Step 2c: Add campaign multiple media and video cover fields
    require_once ROOTDIR_DYK . 'migrations/2026_08_24_001_add_campaign_multiple_media_and_video.php';
    if ( function_exists( 'donasiyuk_migrate_add_campaign_multiple_media_and_video' ) ) {
        donasiyuk_migrate_add_campaign_multiple_media_and_video();
    }

    // Step 2d: Add Duitku Payment Gateway settings
    require_once ROOTDIR_DYK . 'migrations/2026_08_24_002_add_duitku_payment_gateway_settings.php';
    if ( function_exists( 'donasiyuk_migrate_add_duitku_payment_gateway_settings' ) ) {
        donasiyuk_migrate_add_duitku_payment_gateway_settings();
    }

    // Step 2e: Add cidr column on dyk_blocked_ip + rate-limit settings
    require_once ROOTDIR_DYK . 'migrations/2026_08_25_001_add_cidr_and_rate_limit.php';
    if ( function_exists( 'donasiyuk_migrate_add_cidr_and_rate_limit' ) ) {
        donasiyuk_migrate_add_cidr_and_rate_limit();
    }

    // Step 3: Ensure ULTIMATE license is active in DB.
    require_once ROOTDIR_DYK . 'migrations/2026_08_21_002_activate_ultimate_license_db.php';
    if ( function_exists( 'donasiyuk_migrate_activate_ultimate_license_db' ) ) {
        donasiyuk_migrate_activate_ultimate_license_db();
    }

    delete_transient( $lock_key );
}

// run the install scripts upon plugin activation
register_activation_hook(__FILE__, 'dyk_options_install');

// Self-healing check on init to ensure new columns and gateway settings exist
add_action('init', 'donasiyuk_ensure_campaign_media_columns', 5);
function donasiyuk_ensure_campaign_media_columns() {
    if ( ! get_transient( 'dyk_media_cols_migrated_v1' ) ) {
        require_once ROOTDIR_DYK . 'migrations/2026_08_24_001_add_campaign_multiple_media_and_video.php';
        if ( function_exists( 'donasiyuk_migrate_add_campaign_multiple_media_and_video' ) ) {
            donasiyuk_migrate_add_campaign_multiple_media_and_video();
        }
        set_transient( 'dyk_media_cols_migrated_v1', 1, MONTH_IN_SECONDS );
    }
    if ( ! get_transient( 'dyk_duitku_settings_migrated_v1' ) ) {
        require_once ROOTDIR_DYK . 'migrations/2026_08_24_002_add_duitku_payment_gateway_settings.php';
        if ( function_exists( 'donasiyuk_migrate_add_duitku_payment_gateway_settings' ) ) {
            donasiyuk_migrate_add_duitku_payment_gateway_settings();
        }
        set_transient( 'dyk_duitku_settings_migrated_v1', 1, MONTH_IN_SECONDS );
    }
    if ( ! get_transient( 'dyk_cidr_rate_limit_migrated_v1' ) ) {
        require_once ROOTDIR_DYK . 'migrations/2026_08_25_001_add_cidr_and_rate_limit.php';
        if ( function_exists( 'donasiyuk_migrate_add_cidr_and_rate_limit' ) ) {
            donasiyuk_migrate_add_cidr_and_rate_limit();
        }
        set_transient( 'dyk_cidr_rate_limit_migrated_v1', 1, MONTH_IN_SECONDS );
    }
}
add_action('admin_bar_menu', 'donasiyuk_add_admin_bar_menu', 100);

function donasiyuk_add_admin_bar_menu($admin_bar) {
	donasiyuk_global_vars();
	global $wpdb;
	$table_name = $wpdb->prefix . "dyk_settings";

	$query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="fundraiser_on" ORDER BY id ASC');
    $fundraiser_on 	= $query_settings[0]->data;

    $plugin_license = strtoupper($GLOBALS['donasiyuk_vars']['plugin_license']);

	// role
    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];

    if($role=='administrator'){

    	if (!current_user_can('manage_options')) {
	        return;
	    }

	    $admin_bar->add_menu(array(
	        'id'    => 'donasiyuk-menu',
	        'title' => 'DonasiYuk',
	        'href'  => admin_url('admin.php?page=donasiyuk_dashboard'), // ganti dengan slug page kamu
	        'meta'  => array(
	            'title' => __('DonasiYuk Dashboard'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiyuk-submenu-setting1',
	        'parent' => 'donasiyuk-menu',
	        'title'  => 'Dashboard',
	        'href'   => admin_url('admin.php?page=donasiyuk_dashboard'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Dashboard'),
	        ),
	    ));
		
	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiyuk-submenu-setting2',
	        'parent' => 'donasiyuk-menu',
	        'title'  => 'Campaign',
	        'href'   => admin_url('admin.php?page=donasiyuk_data_campaign'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Campaign'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiyuk-submenu-setting3',
	        'parent' => 'donasiyuk-menu',
	        'title'  => 'Analytics',
	        'href'   => admin_url('admin.php?page=donasiyuk_data_analytics'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Analytics'),
	        ),
	    ));

	    if($fundraiser_on=='1'){
			if($plugin_license=='ULTIMATE') {
				
			    $admin_bar->add_menu(array(
			        'id'     => 'donasiyuk-submenu-setting4',
			        'parent' => 'donasiyuk-menu',
			        'title'  => 'Fundraising',
			        'href'   => admin_url('admin.php?page=donasiyuk_data_fundraising'), // ganti slug sesuai page setting plugin
			        'meta'   => array(
			            'title' => __('Fundraising'),
			        ),
			    ));
			}
		}

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiyuk-submenu-setting5',
	        'parent' => 'donasiyuk-menu',
	        'title'  => 'Shortcode',
	        'href'   => admin_url('admin.php?page=donasiyuk_data_shortcodes'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Shortcode'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiyuk-submenu-setting6',
	        'parent' => 'donasiyuk-menu',
	        'title'  => 'Members',
	        'href'   => admin_url('admin.php?page=donasiyuk_data_members'), // ganti slug sesuai page setting plugin
	        'meta'   => array(
	            'title' => __('Members'),
	        ),
	    ));

	    
	    $admin_bar->add_menu(array(
	        'id'     => 'donasiyuk-submenu-setting7',
	        'parent' => 'donasiyuk-menu',
	        'title'  => 'My Donate',
	        'href'   => admin_url('admin.php?page=donasiyuk_mydonate'), // ganti slug sesuai page setting plugin
