function dyk_options_install_later() {
	global $wpdb;
	$table_name = $wpdb->prefix . "options";
	$table_name2 = $wpdb->prefix . "dyk_settings";

	// GET POST
    $id = $_POST['datanya'][0];

    if($id=='donasiaja'){
		dyk_options_install();
		dyk_options_install_data();
	}

	ob_clean();
	echo 'success';

	wp_die();

}
add_action( 'wp_ajax_dja_options_install_later', 'dyk_options_install_later' );
add_action( 'wp_ajax_dyk_options_install_later', 'dyk_options_install_later' );
add_action( 'wp_ajax_nopriv_dja_options_install_later', 'dyk_options_install_later' );
add_action( 'wp_ajax_nopriv_dyk_options_install_later', 'dyk_options_install_later' );



function deactivate_plugin_dna() {
 	
 	// REMOVE ROLE
    $role = get_role( 'donatur' );
    $role->remove_cap( 'upload_files' );
    $role->remove_cap( 'edit_posts' );
    $role->remove_cap( 'edit_published_posts' );
    $role->remove_cap( 'publish_posts' );
    $role->remove_cap( 'read' );
    $role->remove_cap( 'level_2' );
    $role->remove_cap( 'level_1' );
    $role->remove_cap( 'level_0' );
    $role->remove_cap( 'manage_options' );


 	// REMOVE ROLE
    $role = get_role( 'cs' );
    $role->remove_cap( 'upload_files' );
    $role->remove_cap( 'edit_posts' );
    $role->remove_cap( 'edit_published_posts' );
    $role->remove_cap( 'publish_posts' );
    $role->remove_cap( 'read' );
    $role->remove_cap( 'level_2' );
    $role->remove_cap( 'level_1' );
    $role->remove_cap( 'level_0' );
    $role->remove_cap( 'manage_options' );

}
register_deactivation_hook( __FILE__, 'deactivate_plugin_dna' );


function load_custom_dja_admin_style() {

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_users";
    $id_login = wp_get_current_user()->ID;
	$rows = $wpdb->get_results('SELECT * from '.$table_name.' where user_id="'.$id_login.'"');

	$cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];

	if(isset($rows[0])){
	    if($rows[0]->user_pp_img=='') {
	        $pp_url = plugin_dir_url( __FILE__ ) . "assets/images/pp.svg";
	    }else{
	        $pp_url = $rows[0]->user_pp_img;
	    }
	}else{
		$pp_url = plugin_dir_url( __FILE__ ) . "assets/images/pp.svg";
	}

    donasiyuk_global_vars();
    $style_admin_ver = file_exists( plugin_dir_path( __FILE__ ) . 'admin/css/style-admin.css' ) ? filemtime( plugin_dir_path( __FILE__ ) . 'admin/css/style-admin.css' ) : time();

    wp_register_style( 'dyk_style_admin', plugin_dir_url( __FILE__ ) . 'admin/css/style-admin.css', array(), $style_admin_ver );
    wp_enqueue_style( 'dyk_style_admin' );

    global $_wp_admin_css_colors;
    $color_scheme = get_user_option( 'admin_color' );
    if ( empty( $color_scheme ) || ! isset( $_wp_admin_css_colors[ $color_scheme ] ) ) {
        $color_scheme = 'fresh';
    }
    if ( isset( $_wp_admin_css_colors[ $color_scheme ] ) ) {
        $colors = $_wp_admin_css_colors[ $color_scheme ]->colors;
        $primary_bg = isset( $colors[2] ) ? $colors[2] : '#2271b1';
        $custom_css = "
            /* Primary Solid Buttons (Publish, Update, Add, Save, etc.) */
            .btn-primary, 
            .btn-info, 
            .btn-success, 
            .btn-warning,
            .btn-custom,
            button.publish, 
            button.publish_update, 
            #publish, 
            #publish_update,
            .publish[data-act='publish'],
            .publish_update[data-act='publish'],
            .publish_update[data-act='update'],
            .publish[data-act='update'],
            .btn-gradient-primary {
                background-color: {$primary_bg} !important;
                border-color: {$primary_bg} !important;
                background-image: none !important;
                color: #ffffff !important;
                box-shadow: none !important;
            }
            
            .btn-primary:hover, 
            .btn-info:hover, 
            .btn-success:hover, 
            .btn-warning:hover,
            .btn-custom:hover,
            button.publish:hover, 
            button.publish_update:hover, 
            #publish:hover, 
            #publish_update:hover,
            .btn-gradient-primary:hover {
                background-color: {$primary_bg} !important;
                border-color: {$primary_bg} !important;
                filter: brightness(0.88) !important;
                color: #ffffff !important;
            }

            /* Outline Buttons (Save to Draft, Preview, View) */
            .btn-outline-primary,
            .btn-outline-warning,
            .btn-outline-info,
            .btn-outline-success,
            .publish[data-act='draft'],
            .publish_update[data-act='draft'],
            #preview_campaign {
                color: {$primary_bg} !important;
                border-color: {$primary_bg} !important;
                background-color: transparent !important;
                background-image: none !important;
            }

            .btn-outline-primary:hover,
            .btn-outline-warning:hover,
            .btn-outline-info:hover,
            .btn-outline-success:hover,
            .publish[data-act='draft']:hover,
            .publish_update[data-act='draft']:hover,
            #preview_campaign:hover {
                background-color: {$primary_bg} !important;
                border-color: {$primary_bg} !important;
                color: #ffffff !important;
            }

            /* Toggle Switch (Donation / Zakat toggle) */
            .toggleSwitch a {
                background-color: {$primary_bg} !important;
            }

            /* Radio Buttons & Checkboxes */
            .radio-primary input[type='radio']:checked + label::before,
            .radio-primary input[type='radio']:checked + label::after,
            .radio input[type='radio']:checked + label::before,
            .radio input[type='radio']:checked + label::after,
            .custom-control-input:checked ~ .custom-control-label::before {
                background-color: {$primary_bg} !important;
                border-color: {$primary_bg} !important;
            }

            input[type='radio']:checked,
            input[type='checkbox']:checked {
                accent-color: {$primary_bg} !important;
            }

            /* Camera & Upload Icon Buttons */
            .fro-profile_main-pic-change,
            .fro-profile_main-pic-change2,
            .upload_image_qurban,
            .upload_image_zfitrah,
            .upload_image_package2,
            #upload_cover_image {
                background-color: {$primary_bg} !important;
            }

            .fro-profile_main-pic-change:hover,
            .fro-profile_main-pic-change2:hover {
                background-color: {$primary_bg} !important;
                filter: brightness(0.85) !important;
            }

            /* Active Navigation & Pagination */
            .nav-pills .nav-link.active, 
            .nav-pills .show > .nav-link,
            .page-item.active .page-link {
                background-color: {$primary_bg} !important;
                border-color: {$primary_bg} !important;
            }
        ";
        wp_add_inline_style( 'dyk_style_admin', $custom_css );
    }

    wp_register_style( 'dyk_lucide_fix', plugin_dir_url( __FILE__ ) . 'assets/css/lucide-fix.css', array(), $style_admin_ver );
    wp_enqueue_style( 'dyk_lucide_fix' );

    wp_register_script( 'dyk_lucide_js', plugin_dir_url( __FILE__ ) . 'assets/js/lucide.min.js', array(), $style_admin_ver, true );
    wp_enqueue_script( 'dyk_lucide_js' );

    wp_register_script( 'dyk_lucide_init', plugin_dir_url( __FILE__ ) . 'assets/js/lucide-init.js', array('dyk_lucide_js'), $style_admin_ver, true );
    wp_enqueue_script( 'dyk_lucide_init' );

    wp_register_script( 'donasiyuk_script_admin', plugin_dir_url( __FILE__ ) . 'admin/js/donasiyuk-admin.js', array('jquery'), $style_admin_ver, true );
    wp_enqueue_script('donasiyuk_script_admin');

    $a = array( 'admin_url' => admin_url() );
    wp_localize_script( 'donasiyuk_script_admin', 'donasiyuk_admin', $a );

    $b = array( 'pp_url' => $pp_url );
    wp_localize_script( 'donasiyuk_script_admin', 'donasiyuk_admin2', $b );

    $c = array( 'logout_url' => wp_logout_url() );
    wp_localize_script( 'donasiyuk_script_admin', 'donasiyuk_admin3', $c );

    $d = array( 'role_user' => $role );
    wp_localize_script( 'donasiyuk_script_admin', 'donasiyuk_admin4', $d );
}
add_action( 'admin_enqueue_scripts', 'load_custom_dja_admin_style' );

