add_action('admin_head', 'dyk_print_wp_admin_colors_override', 999);


/**
 * Check if the current request is for a DonasiYuk admin page.
 */
function dyk_is_donasiyuk_admin_page() {
    if ( ! is_admin() ) {
        return false;
    }
    if ( isset( $_GET['page'] ) && strpos( $_GET['page'], 'donasiyuk' ) !== false ) {
        return true;
    }
    if ( function_exists( 'get_current_screen' ) ) {
        $screen = get_current_screen();
        if ( $screen && ( strpos( $screen->id, 'donasiyuk' ) !== false || strpos( $screen->base, 'donasiyuk' ) !== false ) ) {
            return true;
        }
    }
    return false;
}

/**
 * Get unified data for DonasiYuk sidebar and layout.
 */
function dyk_get_fullpage_sidebar_data() {
    global $wpdb;
    
    $current_page = isset( $_GET['page'] ) ? sanitize_text_field( $_GET['page'] ) : '';

    $cap   = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys( (array) $cap );
    $role  = isset( $roles[0] ) ? $roles[0] : 'subscriber';

    donasiyuk_global_vars();
    $plugin_license = strtoupper( $GLOBALS['donasiyuk_vars']['plugin_license'] );

    $table_settings = $wpdb->prefix . 'dyk_settings';
    $table_campaign = $wpdb->prefix . 'dyk_campaign';
    $table_users    = $wpdb->prefix . 'dyk_users';

    $query_settings = $wpdb->get_results(
        "SELECT data FROM {$table_settings} WHERE type='campaign_setting' OR type='main_menu_name' OR type='fundraiser_on' ORDER BY id ASC"
    );
    $campaign_setting = isset( $query_settings[0] ) ? $query_settings[0]->data : '0';
    $main_menu_name   = isset( $query_settings[1] ) ? $query_settings[1]->data : 'DonasiYuk';
    $fundraiser_on    = isset( $query_settings[2] ) ? $query_settings[2]->data : '0';

    $rows_campaign = $wpdb->get_results(
        "SELECT COUNT(id) as jumlah FROM {$table_campaign} WHERE publish_status='2' ORDER BY id DESC"
    );
    $jumlah_pending = isset( $rows_campaign[0] ) ? intval( $rows_campaign[0]->jumlah ) : 0;

    $user_on_review = $wpdb->get_results(
        "SELECT id FROM {$table_users} WHERE user_verification='2'"
    );
    $jumlah_on_review = ( $user_on_review !== null ) ? count( $user_on_review ) : 0;

    $menu_items = array();
    $admin_url  = admin_url( 'admin.php' );

    if ( $role === 'donatur' ) {
        if ( $campaign_setting === '1' ) {
            $menu_items[] = array( 'slug' => 'donasiyuk_dashboard',       'label' => 'Dasbor',          'icon' => 'dashboard',   'url' => $admin_url . '?page=donasiyuk_dashboard' );
            $menu_items[] = array( 'slug' => 'donasiyuk_data_analytics',  'label' => 'Analisis',        'icon' => 'analytics',   'url' => $admin_url . '?page=donasiyuk_data_analytics' );
            $menu_items[] = array( 'slug' => 'donasiyuk_data_campaign',   'label' => 'Program',         'icon' => 'campaign',    'url' => $admin_url . '?page=donasiyuk_data_campaign' );
            if ( $fundraiser_on === '1' && $plugin_license === 'ULTIMATE' ) {
                $menu_items[] = array( 'slug' => 'donasiyuk_data_fundraising', 'label' => 'Fundraising', 'icon' => 'fundraising', 'url' => $admin_url . '?page=donasiyuk_data_fundraising' );
            }
            $menu_items[] = array( 'slug' => 'donasiyuk_mydonate',   'label' => 'Donasi Saya',   'icon' => 'wallet',  'url' => $admin_url . '?page=donasiyuk_mydonate' );
            $menu_items[] = array( 'slug' => 'donasiyuk_myprofile',  'label' => 'Profil Saya',   'icon' => 'profile', 'url' => $admin_url . '?page=donasiyuk_myprofile' );
        } else {
            $menu_items[] = array( 'slug' => 'donasiyuk_mydonate',   'label' => 'Donasi Saya',   'icon' => 'wallet',  'url' => $admin_url . '?page=donasiyuk_mydonate' );
            if ( $fundraiser_on === '1' && $plugin_license === 'ULTIMATE' ) {
                $menu_items[] = array( 'slug' => 'donasiyuk_data_fundraising', 'label' => 'Fundraising', 'icon' => 'fundraising', 'url' => $admin_url . '?page=donasiyuk_data_fundraising' );
            }
            $menu_items[] = array( 'slug' => 'donasiyuk_myprofile',  'label' => 'Profil Saya',   'icon' => 'profile', 'url' => $admin_url . '?page=donasiyuk_myprofile' );
        }
    } else {
        $menu_items[] = array( 'slug' => 'donasiyuk_dashboard',       'label' => 'Dasbor',         'icon' => 'dashboard', 'url' => $admin_url . '?page=donasiyuk_dashboard' );

        if ( $role !== 'cs' ) {
            $badge = $jumlah_pending >= 1 ? strval( $jumlah_pending ) : '';
            $menu_items[] = array( 'slug' => 'donasiyuk_data_campaign', 'label' => 'Program', 'icon' => 'campaign', 'url' => $admin_url . '?page=donasiyuk_data_campaign', 'badge' => $badge );
        }

        $menu_items[] = array( 'slug' => 'donasiyuk_data_analytics', 'label' => 'Analisis', 'icon' => 'analytics', 'url' => $admin_url . '?page=donasiyuk_data_analytics' );

        if ( ( $role === 'administrator' || $role === 'cs' ) && $fundraiser_on === '1' && $plugin_license === 'ULTIMATE' ) {
            $menu_items[] = array( 'slug' => 'donasiyuk_data_fundraising', 'label' => 'Fundraising', 'icon' => 'fundraising', 'url' => $admin_url . '?page=donasiyuk_data_fundraising' );
        }

        if ( $role !== 'cs' ) {
            $menu_items[] = array( 'slug' => 'donasiyuk_data_shortcodes', 'label' => 'Shortcode', 'icon' => 'shortcode', 'url' => $admin_url . '?page=donasiyuk_data_shortcodes' );
        }

        if ( $role === 'administrator' ) {
            $members_badge = $jumlah_on_review >= 1 ? strval( $jumlah_on_review ) : '';
            $menu_items[] = array( 'slug' => 'donasiyuk_data_members', 'label' => 'Anggota', 'icon' => 'members', 'url' => $admin_url . '?page=donasiyuk_data_members', 'badge' => $members_badge, 'dividerAfter' => true );
        }

        $menu_items[] = array( 'slug' => 'donasiyuk_mydonate',  'label' => 'Donasi Saya', 'icon' => 'wallet',  'url' => $admin_url . '?page=donasiyuk_mydonate' );
        $menu_items[] = array( 'slug' => 'donasiyuk_myprofile', 'label' => 'Profil Saya', 'icon' => 'profile', 'url' => $admin_url . '?page=donasiyuk_myprofile' );

        if ( $role === 'administrator' ) {
            $menu_items[] = array( 'slug' => 'donasiyuk_settings', 'label' => 'Pengaturan', 'icon' => 'settings', 'url' => $admin_url . '?page=donasiyuk_settings' );
        }
    }

    $current_user = wp_get_current_user();
    $user_name    = trim( $current_user->first_name . ' ' . $current_user->last_name );
    if ( empty( $user_name ) ) {
        $user_name = $current_user->display_name;
    }

    $user_pp = $wpdb->get_results( $wpdb->prepare(
        "SELECT user_pp_img FROM {$table_users} WHERE user_id = %d", $current_user->ID
    ) );
    $user_avatar = ( isset( $user_pp[0] ) && ! empty( $user_pp[0]->user_pp_img ) )
        ? $user_pp[0]->user_pp_img
        : plugin_dir_url( __FILE__ ) . 'assets/images/pp.svg';

    return array(
        'currentPage' => $current_page,
        'wpAdminUrl'  => admin_url(),
        'brandName'   => $main_menu_name,
        'version'     => $GLOBALS['donasiyuk_vars']['plugin_version'],
        'menuItems'   => $menu_items,
        'userName'    => $user_name,
        'userRole'    => ucfirst( $role ),
        'userAvatar'  => $user_avatar,
    );
}

/**
 * Add dyk-fullpage body class server-side to eliminate FOUC and layout shift.
 */
function dyk_admin_body_class( $classes ) {
    if ( dyk_is_donasiyuk_admin_page() ) {
        $classes = ( is_string( $classes ) ? $classes : '' ) . ' dyk-fullpage';
    }
    return $classes;
}
add_filter( 'admin_body_class', 'dyk_admin_body_class', 10 );

/**
 * Output early critical CSS in <head> to prevent any shifting/flickering.
 */
function dyk_critical_fullpage_head_css() {
    if ( ! dyk_is_donasiyuk_admin_page() ) return;
    ?>
    <script id="dyk-critical-sidebar-state">
        (function() {
            try {
                if (localStorage.getItem('dyk_sidebar_collapsed') === 'true') {
                    document.documentElement.classList.add('dyk-sidebar-collapsed');
                    if (document.body) { document.body.classList.add('dyk-sidebar-collapsed'); }
                }
            } catch(e) {}
        })();
    </script>
    <style id="dyk-critical-fullpage-css">
        html.wp-toolbar, html {
            padding-top: 0 !important;
            margin-top: 0 !important;
        }
        body.dyk-fullpage,
        body[class*="donasiyuk"] {
            padding-top: 0 !important;
            margin-top: 0 !important;
            background-color: #f0f2f5 !important;
        }
        body.dyk-fullpage #wpadminbar,
        body[class*="donasiyuk"] #wpadminbar,
        body.dyk-fullpage #adminmenuwrap,
        body.dyk-fullpage #adminmenuback,
        body.dyk-fullpage #adminmenumain,
        body.dyk-fullpage #adminmenu {
            display: none !important;
        }
        body.dyk-fullpage #wpcontent,
        body[class*="donasiyuk"] #wpcontent {
            margin-left: 160px !important;
            padding-left: 0 !important;
            transition: margin-left 0.25s ease !important;
            animation: none !important;
            opacity: 1 !important;
        }
        body.dyk-fullpage.dyk-sidebar-collapsed #wpcontent,
        body.dyk-sidebar-collapsed[class*="donasiyuk"] #wpcontent,
        html.dyk-sidebar-collapsed body #wpcontent {
            margin-left: 68px !important;
        }
        body.dyk-fullpage #wpfooter,
        body[class*="donasiyuk"] #wpfooter {
            margin-left: 160px !important;
            transition: margin-left 0.25s ease !important;
        }
        body.dyk-fullpage.dyk-sidebar-collapsed #wpfooter,
        body.dyk-sidebar-collapsed[class*="donasiyuk"] #wpfooter,
        html.dyk-sidebar-collapsed body #wpfooter {
            margin-left: 68px !important;
        }
        @media screen and (max-width: 960px) {
            body.dyk-fullpage #wpcontent,
            body[class*="donasiyuk"] #wpcontent,
            body.dyk-fullpage #wpfooter,
            body[class*="donasiyuk"] #wpfooter {
                margin-left: 0 !important;
            }
        }
    </style>
    <?php
}
add_action( 'admin_head', 'dyk_critical_fullpage_head_css', 0 );

