/**
 * DonasiYuk Full-Page Admin Mode
 * ──────────────────────────────
 * When the current admin page belongs to DonasiYuk, enqueue the
 * custom sidebar CSS/JS and pass all menu-item data to the script.
 */
function dyk_enqueue_fullpage_mode( $hook ) {
    if ( ! dyk_is_donasiyuk_admin_page() ) return;

    $sidebar_data = dyk_get_fullpage_sidebar_data();

    // Enqueue CSS
    $ver = file_exists( plugin_dir_path( __FILE__ ) . 'admin/css/dyk-fullpage.css' )
        ? filemtime( plugin_dir_path( __FILE__ ) . 'admin/css/dyk-fullpage.css' )
        : time();

    wp_register_style( 'dyk_fullpage_css', plugin_dir_url( __FILE__ ) . 'admin/css/dyk-fullpage.css', array(), $ver );
    wp_enqueue_style( 'dyk_fullpage_css' );

    // Enqueue JS
    $ver_js = file_exists( plugin_dir_path( __FILE__ ) . 'admin/js/dyk-fullpage.js' )
        ? filemtime( plugin_dir_path( __FILE__ ) . 'admin/js/dyk-fullpage.js' )
        : time();

    wp_register_script( 'dyk_fullpage_js', plugin_dir_url( __FILE__ ) . 'admin/js/dyk-fullpage.js', array( 'jquery' ), $ver_js, true );
    wp_enqueue_script( 'dyk_fullpage_js' );

    // Pass data to JS
