// register jquery and style on initialization
function register_donasiaja_script() {
    global $wpdb;
    donasiyuk_global_vars();
    $table_name = $wpdb->prefix . "dyk_settings";
    $plugin_version = $GLOBALS['donasiyuk_vars']['plugin_version'];
    $query_settings=$wpdb->get_results('SELECT data from '.$table_name.' where type="main_menu_name" or type="apikey_local" or type="apikey_server" or type="currency" or type="donasiaja" ORDER BY id ASC');
    $x=$query_settings[0]->data;
    $a=$query_settings[1]->data;
    $b=json_decode($a,true);
    $c=$b['donasiaja'][0];
    $e=json_decode($query_settings[2]->data, true);
    if($e['donasiaja'][2]!=''){
    	$f=date("dMY",$e['donasiaja'][2]);
    }else{
    	$f=null;
    }
    $currency = $query_settings[3]->data;
    if($currency=='MYR'){$delimiter = ',';}else{$delimiter = '.';}
    $show_currency = donasiyuk_currency($currency);
    $show_currency2 = donasiyuk_currency2($currency);
    if(empty($query_settings[4]->data)){$d = '';}else{$d=$query_settings[4]->data;}

	// Register the script
	// wp_register_script( 'dyk_script_1', plugin_dir_url( __FILE__ ) . 'assets/js/jquery.min.js', array(), $plugin_version, true );
	wp_register_script( 'dyk_script_1', plugin_dir_url( __FILE__ ) . 'assets/js/hello.donasiyuk.js', array( 'jquery' ), $plugin_version, true );

	// Localize the script with new data
	$translation_array = array(
	    'varSiteUrl' => get_site_url(),
		'varPluginUrl' => plugin_dir_url( __FILE__ ),
		'apiKey' => substr($c, 0, 11),
	    'm' => $x,
	    'n' => '.id',
	    'r' => 'https://',
	    'd' => $d,
	    'dt'=> $f,
	    'delimiter'=> $delimiter,
	    'show_currency'=> $show_currency,
	    'show_currency2'=> $show_currency2
	);
	wp_localize_script( 'dyk_script_1', 'donasiyukObjName', $translation_array );
	 
	// Enqueued script with localized data.
	wp_enqueue_script( 'dyk_script_1' );
	
}
add_action('init', 'register_donasiaja_script');


