function custom_donasiaja_js() {
    global $wpdb;
    donasiyuk_global_vars();
    $plugin_version = $GLOBALS['donasiyuk_vars']['plugin_version'];
    $table_name = $wpdb->prefix . "dyk_settings";

    // Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="jquery_on" or type="jquery_custom" ORDER BY id ASC');
    $jquery_on = $query_settings[0]->data;
    $jquery_custom = $query_settings[1]->data;

    if($jquery_on=='0' || $jquery_on==null){
    	// no JQuery
    }elseif($jquery_on=='2'){
    	if($jquery_custom=='0' || $jquery_custom==null){
    		// no JQuery
    	}else{
    		echo '<script src="https://code.jquery.com/jquery-'.$jquery_custom.'.min.js"></script>';
    	}
    }else{
    	echo '<script src="'.plugin_dir_url( __FILE__ ) . 'assets/js/jquery.min.js?ver='.$plugin_version.'"></script>';
    }

	// Lucide icons (replaces FontAwesome/MDI/Dripicons/Glyphicon).
	echo '<script src="'.plugin_dir_url( __FILE__ ) . 'assets/js/lucide.min.js?ver='.$plugin_version.'"></script>';
	echo '<script src="'.plugin_dir_url( __FILE__ ) . 'assets/js/lucide-init.js?ver='.$plugin_version.'"></script>';
	echo '<link rel="stylesheet" href="'.plugin_dir_url( __FILE__ ) . 'assets/css/lucide-fix.css?ver='.$plugin_version.'">';

    $query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="theme_color" ORDER BY id ASC');
    $general_theme_color    = json_decode($query_settings[0]->data, true);
    $theme_color 			= !empty($general_theme_color['color'][0]) ? $general_theme_color['color'][0] : '#10a8e5';
	$progressbar_color  	= !empty($general_theme_color['color'][1]) ? $general_theme_color['color'][1] : '#10a8e5';
	$button_color 			= !empty($general_theme_color['color'][2]) ? $general_theme_color['color'][2] : '#10a8e5';
	$button_color2 			= !empty($general_theme_color['color'][3]) ? $general_theme_color['color'][3] : '#10a8e5';

	if(empty($button_color) || $button_color=='#7680FF' || $button_color=='#7680ff'){ $button_color = '#10a8e5'; }
	if(empty($button_color2) || $button_color2=='#7680FF' || $button_color2=='#7680ff'){ $button_color2 = '#10a8e5'; }
	if(empty($progressbar_color) || $progressbar_color=='#009F61' || $progressbar_color=='#24CC63'){ $progressbar_color = '#10a8e5'; }

    if($theme_color!=''){
    	echo '<style>.donasiyuk_search_box .control .btn-material{background: '.$theme_color.';}</style>';
    }
}
