			if($loadmore>=1){
				echo '<div id="box_button_'.$id.'" class="btn_loadmore_list"><div class="donasiyuk_loadmore_info"></div><button class="load_campaign" data-id="'.$id.'" data-count="2" '.$button_date.' data-filter="" style="color:'.$button_color2.';border:1px solid '.$button_color2.';">Load more</button></div>';
			}
			
		}
		if($style=='grid'){

			echo '<ul id="section_'.$id.'" class="cards__campaign'.$style_cardnya.$show_grid.'">'.$hasil_grid.'</ul>';
