// shortcode per campaign
function donasiyuk_campaign_shortcode_func( $atts, $content = "" ) {
	
	global $wpdb;
	$table_name = $wpdb->prefix . "dyk_campaign";
	$table_name2 = $wpdb->prefix . "dyk_donate";
	$table_name3 = $wpdb->prefix . "dyk_users";
	$table_name4 = $wpdb->prefix . "dyk_shortcode";
	$table_name5 = $wpdb->prefix . "dyk_campaign_update";
	$table_name6 = $wpdb->prefix . "dyk_settings";

	$atts = shortcode_atts( array(
		'id' => null,
		'show' => null,
		'icon_donatur' => null,
		'float' => null,
		'title_image' => null
	), $atts, 'donasiyuk_campaign' );


	$id = '';
	if($atts['id']!==null){
  		$id = $atts['id'];
  	}

	$show = '';
	if($atts['show']!==null){
  		$show = $atts['show'];
  	}

	$icon_donatur = '';
	if($atts['icon_donatur']!==null){
  		$icon_donatur = $atts['icon_donatur'];
  	}

	$float = '';
	if($atts['float']!==null){
  		$float = 'float:'.$atts['float'].';';
  	}

	$title_image = '';
	if($atts['title_image']!==null){
  		$title_image = $atts['title_image'];
  	}

  	$check_campaign = $wpdb->get_results('SELECT id from '.$table_name.' where campaign_id="'.$id.'"');
	if($check_campaign==null){
		return false;
	}

	// Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name6.' where type="opt_nominal" or type="max_package" or type="anonim_text" or type="page_donate" or type="theme_color" or type="form_text" or type="icon_list_setting" or type="icon_list_data" or type="emas_per_gram" ORDER BY id ASC');
    $opt_nominal 			= $query_settings[0]->data;
    $max_package 			= $query_settings[1]->data;
	$nominals 				= json_decode($opt_nominal, true);
    $anonim_text 			= $query_settings[2]->data;
    $page_donate 			= $query_settings[3]->data;

    $icon_list_setting      = $query_settings[6]->data;
    $icon_list_data         = $query_settings[7]->data;
    $emas_per_gram          = $query_settings[8]->data;

    $general_theme_color    = json_decode($query_settings[4]->data, true);
    $theme_color 			= !empty($general_theme_color['color'][0]) ? $general_theme_color['color'][0] : '#10a8e5';
	$progressbar_color  	= !empty($general_theme_color['color'][1]) ? $general_theme_color['color'][1] : '#10a8e5';
	$button_color 			= !empty($general_theme_color['color'][2]) ? $general_theme_color['color'][2] : '#10a8e5';

	$form_text 	 			= json_decode($query_settings[5]->data, true);
	$button_text2 			= $form_text['text'][1];


	if($icon_list_setting=='1'){
        $icon_list_data    = json_decode($icon_list_data, true);
    }


    if(empty($theme_color) || $theme_color=='#009F61'){
    	$theme_color = '#10a8e5';
    }
    if(empty($progressbar_color) || $progressbar_color=='#009F61' || $progressbar_color=='#24CC63'){
    	$progressbar_color = '#10a8e5';
    }

    if(empty($button_color) || $button_color=='#7680FF' || $button_color=='#7680ff'){
		$button_color = '#10a8e5';
	}

    // Currency
    $query_currency = $wpdb->get_results('SELECT data from '.$table_name6.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;
    $lang = get_data_lang($currency);
    $langArray = require_once(ROOTDIR_DYK . 'library/locale/'.$lang.'.php');

    $show_currency = donasiyuk_currency($currency);

    // **************
    // GET DATA FROM CAMPAIGN
    // **************
	$value = $wpdb->get_results("SELECT * FROM $table_name where campaign_id='$id' ")[0];

	// GET BUTTON TEXT AND NOMINAL
	if($value->form_status=='1'){
        $form_textnya   = json_decode($value->form_text, true);
        $button_text2 = $form_textnya['text'][1];

        // option donate custom
        if($value->opt_nominal!=''){
            $nominals = json_decode($value->opt_nominal, true);
        }
        if($value->form_type=='5'){
            $nominals = json_decode($value->opt_qurban, true);
        }
        if($value->form_type=='6'){
            $nominals = json_decode($value->opt_package2, true);
        }
        if($value->form_type=='7'){
            $nominals = json_decode($value->opt_zfitrah, true);
        }
    }

	$date_now = date('Y-m-d');
    $datetime1 = new DateTime($date_now);
    // $datetime2 = new DateTime($value->end_date);
    if (!empty($value->end_date)) {
        $datetime2 = new DateTime($value->end_date);
    } else {
        // Handle null end_date: set $datetime2 to $datetime1 or a default future date
        $datetime2 = new DateTime('9999-12-31'); // You can use any default future date
    }
    $hasil = $datetime1->diff($datetime2);
    
    $year = $hasil->y;
    $month = $hasil->m;
    $day = $hasil->d;

    // Date
    $date_end = false;
    if($year!=0){
        if($day>7){
    		$sisa_waktu = $year.'&nbsp;tahun,&nbsp;' .($month+1).'&nbsp;bulan&nbsp;lagi';
    	}else{
    		$sisa_waktu = $year.'&nbsp;tahun,&nbsp;' .$month.'&nbsp;bulan&nbsp;lagi';
    	}
    }else{
        if($month!=0){
            $sisa_waktu = $month.'&nbsp;bulan,&nbsp;' .$day.'&nbsp;hari&nbsp;lagi';
        }else{
            if($day==0 && $hasil->days==0){
                $sisa_waktu = 'hari&nbsp;ini';
            }else{
                if($hasil->invert==true){
                    $sisa_waktu = '<span style="color:#ff6b24;font-style:italic;">sudah&nbsp;berakhir</span>';
                    $date_end = true;
                }else{
                    $sisa_waktu = $day.'&nbsp;hari&nbsp;lagi';
                }
                
            }
        }
    }

    if($value->end_date==null){
    	$sisa_waktu = '∞';
    }
    if($hasil->invert==true){
    	$sisa_waktu = '<span style="color:#ff6b24;font-style:italic;">sudah&nbsp;berakhir</span>';
    }

    // general setting on campaign
    $general_status = $value->general_status;
    $allocation_title = $value->allocation_title;
    $allocation_others_title = $value->allocation_others_title;
    if($general_status=='1'){
        if($allocation_title=='1' || $allocation_title=='0'){
            $allocation_title = 'Donasi';
        }elseif($allocation_title=='2'){
            $allocation_title = 'Zakat';
        }elseif($allocation_title=='3'){
            $allocation_title = 'Qurban';
        }elseif($allocation_title=='4'){
            $allocation_title = 'Infaq';
        }elseif($allocation_title=='5'){
            $allocation_title = 'Wakaf';
        }else{
            $allocation_title = $allocation_others_title;
        }
    }else{
        $allocation_title = 'Donasi';
    }

    // button zakat
    if($value->form_type=='4' || $value->form_type=='7'){
        $button_text2 = 'Zakat';
    }else{
        $button_text2 = $allocation_title;
    }
    if (strpos(strtolower($allocation_title), 'wakaf') !== false ) {
        $button_text2 = 'Wakaf';
    }


	$total_donasi = $wpdb->get_results("SELECT SUM(nominal) as total, COUNT(id) as jumlah FROM $table_name2 where campaign_id='$value->campaign_id' and status='1' ")[0];

	if($value->target==0){
		// $persen = 100;
		$persen_width = 100;
	}else{
		// $persen = ($total_donasi->total/$row->target)*100;
		$persen_width = ($total_donasi->total/$value->target)*100;
		if($persen_width>100){
			$persen_width = 100;
		}
	}

	$data_donasinya = '';
    if($total_donasi==null){
        $total_terkumpul = 0;
        $jumlah_donasi = 0;
        $data_donasi = 0;
    }else{
        $total_terkumpul = $total_donasi->total;
        $jumlah_donasi = $total_donasi->jumlah;

        $data_donasi = $wpdb->get_results("SELECT user_id, name FROM $table_name2 where campaign_id='$value->campaign_id' and status='1' ORDER BY id ASC LIMIT 0,3 ");

        // GET INISAL DONATUR / PP URL
        foreach ($data_donasi as $data) {
        	if($data->user_id==null || $data->user_id==0){
        		$first_char = strtoupper(mb_substr($data->name, 0, 1));
        		$data_donasinya .= '<span class="u_image u_inisial" style="background:'.$theme_color.'"> '.$first_char.' </span>';
        	}else{
        		$first_char = strtoupper(mb_substr($data->name, 0, 1));
        		$user_profile = $wpdb->get_results('SELECT user_pp_img as photo from '.$table_name3.' where user_id="'.$data->user_id.'"');
				if(isset($user_profile[0])){
					if($user_profile==null){
						$first_char = strtoupper(mb_substr($data->name, 0, 1));
                		$data_donasinya .= '<span class="u_image u_inisial" style="background:'.$theme_color.'"> '.$first_char.' </span>';
					}else{
						$url_photo = $user_profile[0]->photo;
						if($url_photo==''){
							$first_char = strtoupper(mb_substr($data->name, 0, 1));
	                		$data_donasinya .= '<span class="u_image u_inisial" style="background:'.$theme_color.'"> '.$first_char.' </span>';
						}else{
							$data_donasinya .= '<img src="'.$url_photo.'" alt="User Image" class="u_image">';
						}
					}
				}else{
					$first_char = strtoupper(mb_substr($data->name, 0, 1));
            		$data_donasinya .= '<span class="u_image u_inisial" style="background:'.$theme_color.'"> '.$first_char.' </span>';
				}
        	}
        }
    }

	if($value->image_url==null){
        $image_url = plugin_dir_url( __FILE__ ).'assets/images/cover_donasiyuk.jpg';
    }else{
        $image_url = $value->image_url;
        // $image_url = str_replace('localhost', '192.168.0.102', $image_url);
    }

    if($jumlah_donasi==0){
    	$icon_donasi = '
    	<div class="u_campaign u_icon">
		  <div class="campaign_days no_donation" style="padding-top:5px;">'.$sisa_waktu.'</div>
		</div>
		';
    }else{
    	$donasi_plusmore = '';
    	if($jumlah_donasi>=4){
        	
    		$total_min_three = $jumlah_donasi-3;
    		$donasi_totalnya = shortDisplayNumber($total_min_three).'+';

        	if(strlen($donasi_totalnya)>=4){
        		$donasi_totalnya = '<span style="font-size:7px;">'.$donasi_totalnya.'</span>';
        	}elseif(strlen($donasi_totalnya)==3){
        		$donasi_totalnya = '<span style="font-size:8px;">'.$donasi_totalnya.'</span>';
        	}else{
        		$donasi_totalnya = $donasi_totalnya;
        	}

        	// >= 4 char = 7px
        	// 3 char = 8px
        	// 2 char = 9px

        	$donasi_plusmore = '<span class="u_image u_inisial" style="background:'.$theme_color.'">'.$donasi_totalnya.'</span>';
    	}

    	if($icon_donatur=='hide'){
    		$icon_donasi = '
        	<div class="u_campaign u_donasi">
			  <div class="campaign_days" style="margin-top:5px;font-size:11px;">'.$sisa_waktu.'</div>
			</div>
			';
    	}else{
    		$icon_donasi = '
        	<div class="u_campaign u_donasi">
			  <div class="u_photo">
			  	'.$data_donasinya.'
			  	'.$donasi_plusmore.'
			  </div>
			  <div class="campaign_days" style="margin-top:5px;font-size:11px;">'.$sisa_waktu.'</div>
			</div>
			';
    	}

		
    }

    if($value->publish_status=='1'){
        $campaign_url = get_site_url().'/campaign/'.$value->slug;
    }else{
        $campaign_url = get_site_url().'/preview/'.$value->slug;
    }


    // GET PROFILE PICTURE CAMPAIGNER
	$profile = $wpdb->get_results('SELECT user_pp_img as photo from '.$table_name3.' where user_id="'.$value->user_id.'"');
	if(isset($profile[0])){
		if($profile==null){
			$profile_photo = plugin_dir_url( __FILE__ ) . "assets/images/pp.svg";
		}else{
			$profile_photo = $profile[0]->photo;
		}
	}else{
		$profile_photo = plugin_dir_url( __FILE__ ) . "assets/images/pp.svg";
	}

	// GET USER NAME
	$args2 = array( 'blog_id' => 0, 'search' => $value->user_id, 'search_columns' => array( 'ID' ) );
    $get_name = get_users( $args2 );

    if($get_name==null){
        $campaigner_name = '-';
    }else{
        $nama_user = str_replace("'", "&#39;", $get_name[0]->user_firstname.' '.$get_name[0]->user_lastname);
        $campaigner_name = str_replace('\\', '', $nama_user); // nama asli
    }
	

	


	ob_start();

	if($show=='info'){
		echo html_entity_decode($value->information);
	}

	if($show=='info_update'){
		
		$campaign_update = $wpdb->get_results("SELECT * FROM $table_name5 where campaign_id='$id' ORDER BY id DESC");

		$dt = new DateTime($value->created_at);
	    $m = $dt->format('F');

	    if (strpos($m, 'January') !== false ) { $m = 'Januari'; }
	    elseif(strpos($m, 'February') !== false ) { $m = 'Februari'; }
	    elseif(strpos($m, 'March') !== false ) { $m = 'Maret'; }
	    elseif(strpos($m, 'April') !== false ) { $m = 'April'; }
	    elseif(strpos($m, 'May') !== false ) { $m = 'Mei'; }
	    elseif(strpos($m, 'June') !== false ) { $m = 'Juni'; }
	    elseif(strpos($m, 'July') !== false ) { $m = 'Juli'; }
	    elseif(strpos($m, 'August') !== false ) { $m = 'Agustus'; }
	    elseif(strpos($m, 'September') !== false ) { $m = 'September'; }
	    elseif(strpos($m, 'October') !== false ) { $m = 'Oktober'; }
	    elseif(strpos($m, 'November') !== false ) { $m = 'Nopember'; }
	    elseif(strpos($m, 'December') !== false ) { $m = 'Desember'; }

	    $dt = $m.', '.$dt->format('j Y');
	    

		if($campaign_update==null){ 
			echo '
	    	<div id="kabar-terbaru-donasi">
