// shortcode per campaign
function donasiyuk_socialproof_shortcode_func( $atts, $content = "" ) {
	
	global $wpdb;
	$table_name   = $wpdb->prefix . "dyk_settings";
	$table_name2  = $wpdb->prefix . "dyk_donate";
	$table_name3  = $wpdb->prefix . "dyk_campaign";
	$table_name4  = $wpdb->prefix . "dyk_users";

	$atts = shortcode_atts( array(
		'campaign' => null,
		'close' => null,
	), $atts, 'donasiyuk_socialproof' );


	$campaign = '';
	if($atts['campaign']!==null){
  		$campaign = $atts['campaign'];
  	}

  	$close = 'hide';
	if($atts['close']!==null){
  		$close = $atts['close'];
  	}
  	if($close=='show'){
  		$close = 'true';
  	}else{
  		$close = 'false';
  	}


	// Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="anonim_text" or type="currency" or type="socialproof_text" or type="socialproof_settings" ORDER BY id ASC');
    $anonim_text    	  = $query_settings[0]->data;
    $currency 			  = $query_settings[1]->data;
    $socialproof_text     = $query_settings[2]->data;
    $socialproof_settings = isset($query_settings[3]) ? $query_settings[3]->data : '';

    $socialproof_setting  = json_decode((string) $socialproof_settings, true);
    $sp_settings = (isset($socialproof_setting['settings']) && is_array($socialproof_setting['settings'])) ? $socialproof_setting['settings'] : array();
    $popup_style    = isset($sp_settings[0]) ? $sp_settings[0] : '';
    $position       = isset($sp_settings[1]) ? $sp_settings[1] : '';
    $time_set       = isset($sp_settings[2]) ? $sp_settings[2] : '';
    $delay          = isset($sp_settings[3]) ? $sp_settings[3] : '';
    $data_load      = isset($sp_settings[4]) ? $sp_settings[4] : '';

    // Currency
    $lang = get_data_lang($currency);
    $langArray = require_once(ROOTDIR_DYK . 'library/locale/'.$lang.'.php');
    
    $show_currency = donasiyuk_currency($currency);
    $show_currency2 = donasiyuk_currency2($currency);

    // popup_style
    if($popup_style=='rounded'){
        $set_style = ' s-rounded';
    }elseif($popup_style=='flying_boxed'){
        $set_style = ' s-flying';
    }elseif($popup_style=='flying_rounded'){
        $set_style = ' s-rounded s-flying';
    }else{
        $set_style = '';
    }

    // delay
    $delay = $delay*1000;

    // data_load
    $total = $data_load;

    // time
    $time = $time_set;

    // title
    $title = $socialproof_text;

    // position
    $position_data = explode('_', $position);
	$p_gravity  = $position_data[0];
	$p_position = $position_data[1];

	// campaign
	if($campaign!=''){
    	$data_donasi = $wpdb->get_results("SELECT a.id, a.campaign_id, a.user_id, a.invoice_id, a.name, a.anonim, a.created_at, a.nominal as total, b.title, c.user_pp_img FROM $table_name2 a
		left JOIN $table_name3 b ON b.campaign_id = a.campaign_id
		left JOIN $table_name4 c ON c.user_id = a.user_id
		where a.status='1' and a.campaign_id='$campaign' ORDER BY id DESC LIMIT 0,$total ");
