function donasiyuk_readtime($time) { 

	$timestamp = strtotime($time);	
   
    $strTime = array("detik", "menit", "jam", "hari", "bulan", "tahun");
    $length = array("60","60","24","30","12","10");

    $currentTime = time();
    if($currentTime >= $timestamp) {
    	
    	$diff     = time()- $timestamp + (60*60);
		
		for($i = 0; $diff >= $length[$i] && $i < count($length)-1; $i++) {
		$diff = $diff / $length[$i];
		}

		$diff = round($diff);
		return $diff . " " . $strTime[$i] . " yang lalu";
    }

}

function donasiyuk_load_campaign() {
	
    global $wpdb;
	$table_name = $wpdb->prefix . "dyk_campaign";
	$table_name2 = $wpdb->prefix . "dyk_donate";
	$table_name3 = $wpdb->prefix . "dyk_users";
	$table_name4 = $wpdb->prefix . "dyk_shortcode";
	$table_name5 = $wpdb->prefix . "dyk_settings";
	$table_name6 = $wpdb->prefix . "dyk_aff_code";
    
    $id = $_POST['datanya'][0];
    $load_count = $_POST['datanya'][1];
    $uid = $_POST['datanya'][2];
    $datenya = $_POST['datanya'][3] ?? '';
    $type = $_POST['datanya'][4] ?? '';

    $firstTwoCharacters = substr($id, 0, 2);

  	$check_campaign = $wpdb->get_results('SELECT * from '.$table_name4.' where s_id="'.$id.'"');

	if($firstTwoCharacters=='u_'){
		$style = 'list';
		$show  = 3;
		$category_id  = 0;
		$loadmore  = 3;
	}elseif($check_campaign==null){
		wp_die();
	}else{
		$style = $check_campaign[0]->s_style;
		$show  = $check_campaign[0]->s_show;
		$category_id  = $check_campaign[0]->s_category;
		$loadmore  = $check_campaign[0]->s_loadmore;
		$button_on  = $check_campaign[0]->s_button_on;
		$button_text  = $check_campaign[0]->s_button_text;
	}

	$start = ($load_count*$show)-$show;
    $limit = $loadmore;

	if($category_id==null || $category_id=='0'){

		if($type=='referral'){

			$campaign = $wpdb->get_results("SELECT a.aff_code, b.* FROM $table_name6 a 
	            left JOIN $table_name b ON a.campaign_id = b.campaign_id
	            where a.user_id=$uid and b.publish_status='1' 
	            ORDER BY id DESC LIMIT $start,$limit ");
			
			// foreach($campaign as $v){
			// 	echo $v->aff_code;
			// 	echo '<br>';
			// }

		}else{
			if($uid!=''){
				$campaign = $wpdb->get_results("SELECT * FROM $table_name where publish_status='1' and user_id='$uid' ORDER BY id DESC LIMIT $start,$limit ");
			}else{

				if($datenya=='expired'){
			  		// echo 'tampilkan yang expired saja';	
			  		// $campaign = $wpdb->get_results("SELECT * FROM $table_name WHERE publish_status='1' AND end_date IS NOT NULL AND end_date < NOW() ORDER BY id DESC LIMIT 0,$show");
			  		$campaign = $wpdb->get_results("SELECT * FROM $table_name where publish_status='1' AND end_date IS NOT NULL AND end_date < NOW() ORDER BY id DESC LIMIT $start,$limit ");
			  	}else{
			  		$campaign = $wpdb->get_results("SELECT * FROM $table_name where publish_status='1' ORDER BY id DESC LIMIT $start,$limit ");
			  	}
			}
		}
		

	}else{
		// example OR : WHERE (category_id='1' and publish_status='1') or (category_id='4' and publish_status='1')
		if( strpos($category_id, ',') !== false ) {

            // ada koma, maka loop. berarti banyak category
            $variable = $category_id;
            $var=explode(',',$variable);
            $count_categoty = count($var);
            $no_category = 1;
            $wherenya = '';
            foreach($var as $value_idnya)
            {
                $wherenya .= "(category_id='$value_idnya' and publish_status='1')";
                if($no_category<$count_categoty){
                    $wherenya .= ' or ';
                }
                $no_category++;
            }

            $campaign = $wpdb->get_results("SELECT * FROM $table_name where $wherenya ORDER BY id DESC LIMIT $start,$limit ");

        }else{

            // gak ada koma, berarti single
            $campaign = $wpdb->get_results("SELECT * FROM $table_name where publish_status='1' and category_id='$category_id' ORDER BY id DESC LIMIT $start,$limit ");
        }
	}

	// Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name5.' where type="theme_color" ORDER BY id ASC');
    $general_theme_color    = json_decode($query_settings[0]->data, true);
    $theme_color 			= !empty($general_theme_color['color'][0]) ? $general_theme_color['color'][0] : '#10a8e5';
	$progressbar_color  	= !empty($general_theme_color['color'][1]) ? $general_theme_color['color'][1] : '#10a8e5';
	$button_color 			= !empty($general_theme_color['color'][2]) ? $general_theme_color['color'][2] : '#10a8e5';
	$button_color2 			= !empty($general_theme_color['color'][3]) ? $general_theme_color['color'][3] : '#10a8e5';

    if(empty($theme_color) || $theme_color=='#009F61'){
    	$theme_color = '#10a8e5';
    }
    if(empty($progressbar_color) || $progressbar_color=='#009F61' || $progressbar_color=='#24CC63'){
    	$progressbar_color = '#10a8e5';
    }
    if(empty($button_color) || $button_color=='#7680FF' || $button_color=='#7680ff'){
    	$button_color = '#10a8e5';
    }
    if(empty($button_color2) || $button_color2=='#7680FF' || $button_color2=='#7680ff'){
    	$button_color2 = '#10a8e5';
    }

    // Currency
    $query_currency = $wpdb->get_results('SELECT data from '.$table_name5.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;
    $lang = get_data_lang($currency);
    $langArray = require_once(ROOTDIR_DYK . 'library/locale/'.$lang.'.php');
