function action_get_the_user_attachments( $query ) {

    // If we are not seeing the backend we quit.
    if ( !is_admin() ) {
        return;
    }

    /**
     * If it's not a main query type we quit.
     *
     * @link    https://codex.wordpress.org/Function_Reference/is_main_query
     */
    if ( !$query->is_main_query() ) {
        return;
    }

    $current_screen = get_current_screen();

    $current_screen_id = $current_screen->id;

    // If it's not the upload page we quit.
    if ( $current_screen_id != 'upload' ) {
        return;
    }

    $current_user = wp_get_current_user();

    $current_user_id = $current_user->ID;

    $author__in = array(
        $current_user_id
    );

    $query->set( 'author__in', $author__in );

}

add_action( 'pre_get_posts', 'action_get_the_user_attachments', 10 );



// ajax media file
function filter_get_the_user_attachments( $query ) {

    $current_user = wp_get_current_user();

    if ( !$current_user ) {
        return;
    }

    $current_user_id = $current_user->ID;

    $query['author__in'] = array(
        $current_user_id
    );

    return $query;

};

add_filter( 'ajax_query_attachments_args', 'filter_get_the_user_attachments', 10 );


function strip_script_tags( $content ) {
    return preg_replace( '#<script(.*?)>(.*?)</script>#is', '', $content );
}

function dykfunction_publish_campaign() {
	
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_campaign";

    // role
    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];
    
    // FROM INPUT
    $title 			= wp_strip_all_tags($_POST['datanya'][0]);
    $image_url 		= wp_strip_all_tags($_POST['datanya'][1]);
    $information 	= strip_script_tags($_POST['datanya'][2]);
    $target 		= wp_strip_all_tags($_POST['datanya'][3]);
    $end_date 		= wp_strip_all_tags($_POST['datanya'][4]);
    $location_name 	= wp_strip_all_tags($_POST['datanya'][5]);
    $location_gmaps = wp_strip_all_tags($_POST['datanya'][6]);
    $category_id	= wp_strip_all_tags($_POST['datanya'][7]);
    $form_base		= wp_strip_all_tags($_POST['datanya'][8]);
    $form_type		= wp_strip_all_tags($_POST['datanya'][9]);
    $packaged		= wp_strip_all_tags($_POST['datanya'][10]);
    $packaged_title	= wp_strip_all_tags($_POST['datanya'][11]);
    $act			= wp_strip_all_tags($_POST['datanya'][12]);
    $pengeluaran_setting = $_POST['datanya'][13];
    $pengeluaran_title	 = $_POST['datanya'][14];
    $zakat_setting	 = $_POST['datanya'][15];
    $zakat_percent	 = $_POST['datanya'][16];
    $packaged_unit	 = $_POST['datanya'][17];
    $packaged_custom = $_POST['datanya'][18];
    $pendapatan1_title				= $_POST['datanya'][19];
    $pendapatan2_title				= $_POST['datanya'][20];
    $zakat_penghasilan_type			= $_POST['datanya'][21];
    $zakat_penghasilan_custom_title	= $_POST['datanya'][22];
    $zakat_hasil_pertanian			= $_POST['datanya'][23];
    $zakat_harga_per_kg				= $_POST['datanya'][24];
    $zakat_pengairan				= $_POST['datanya'][25];
    $zakat_nisab_kg					= $_POST['datanya'][26];
    $zakat_harga_emas				= $_POST['datanya'][27];
    $media_type						= !empty($_POST['datanya'][28]) ? wp_strip_all_tags($_POST['datanya'][28]) : 'image';
    $gallery_urls					= !empty($_POST['datanya'][29]) ? str_replace('\\', '', $_POST['datanya'][29]) : null;
    $video_url						= !empty($_POST['datanya'][30]) ? esc_url_raw($_POST['datanya'][30]) : null;

    $title = str_replace("'", "&#39;", $title); // petik 1
    $title = str_replace('"', "&#34;", $title); // petik 2
    $title = str_replace('\\', '', $title); // backslash

    // $information = str_replace("'", "&#39;", $information); // petik 1
    // $information = str_replace('"', "&#34;", $information); // petik 2
    $information = str_replace('\\', '', $information); // backslash

    // DEFAULT
    $campaign_id = 'dja'.d_randomString(8);
    $slug = d_formatUri($title);
    $publish_status = 1;
    $reached_status = 0;
    $currency = 'IDR';
    $user_id = wp_get_current_user()->ID;
    $fundraiser_id = null;
    $method_status = '{"instant":"0","va":"0","transfer":"0"}';


    if($end_date==''){
    	$end_date = null;
    }else{
    	$end_date = date($_POST['datanya'][4].' 23:59:00');
    }

    // cek slug
    $slug = str_replace('?', '', $slug); // delete ? on slug
    $jumlah_slug = count($wpdb->get_results('SELECT id from '.$table_name.' where slug="'.$slug.'"'));
    if($jumlah_slug>1){
    	$count = $jumlah_slug+1;
    	$slug = $slug.'-'.d_randomString(3);
    }

    // publish status
    if($role=='donatur'){
    	$publish_status = 2; // pending review
    	$form_type = 1; // form type : card
    	$form_base = 0;
    	$pengeluaran_setting = 0;
    	$pengeluaran_title = null;
    }

    if($act=='draft'){
    	$publish_status = 0;
    }

    if(strpos($image_url, 'donasiyuk-cover.jpg') !== false) {
	    $image_url = null;
	}

	if($zakat_setting=='0'){
		$zakat_percent = null;
	}

    // ACTION INSERT TO DB
    $wpdb->insert(
            $table_name, //table
            array(
	            'campaign_id' 	=> $campaign_id,
	            'title' 		=> $title,
	            'slug' 			=> $slug,
	            'target' 		=> $target,
	            'image_url' 	=> $image_url,
	            'media_type' 	=> $media_type,
	            'gallery_urls' 	=> $gallery_urls,
	            'video_url' 	=> $video_url,
	            'information' 	=> $information,
	            'location_name' => $location_name,
	            'location_gmaps'=> $location_gmaps,
	            'publish_status'=> $publish_status,
	            'reached_status'=> $reached_status,
	            'end_date' 		=> $end_date,
	            'form_base'		=> $form_base,
	            'form_type'		=> $form_type,
	            'packaged'		=> $packaged,
	            'packaged_title'=> $packaged_title,
	            'packaged_unit'  => $packaged_unit,
	            'packaged_custom'=> $packaged_custom,
	            'currency' 		=> $currency,
	            'category_id'	=> $category_id,
	            'user_id' 		=> $user_id,
	            'fundraiser_id' => $fundraiser_id,
	            'payment_status'=> 0,
	            'method_status' => $method_status,
	            'bank_account'  => null,
	            'form_status'	=> 0,
	            'form_text'  	=> null,
	            'pengeluaran_setting' 	=> $pengeluaran_setting,
	            'pengeluaran_title'   	=> $pengeluaran_title,
	            'pendapatan1_title'		=> $pendapatan1_title,
	            'pendapatan2_title'		=> $pendapatan2_title,
	            'zakat_penghasilan_type'=> $zakat_penghasilan_type,
	            'zakat_penghasilan_custom_title'=> $zakat_penghasilan_custom_title,
	            'zakat_hasil_pertanian'	=> $zakat_hasil_pertanian,
	            'zakat_harga_per_kg'	=> $zakat_harga_per_kg,
	            'zakat_pengairan'		=> $zakat_pengairan,
	            'zakat_nisab_kg'		=> $zakat_nisab_kg,
	            'zakat_harga_emas'		=> $zakat_harga_emas,
	            'zakat_setting'   => $zakat_setting,
	            'zakat_percent'   => $zakat_percent,
	            'created_at' 	=> date("Y-m-d H:i:s")),
            array('%s', '%s') //data format         
        );
	
	echo $campaign_id;

    wp_die();

} 
