add_action( 'wp_ajax_nopriv_dykfunction_publish_campaign', 'dykfunction_publish_campaign' );



function dykfunction_blocked_ip(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_blocked_ip";
    $table_name2 = $wpdb->prefix . "dyk_donate";
    $table_name3 = $wpdb->prefix . "dyk_campaign";

    // FROM INPUT
    $ip_user = isset($_POST['datanya'][0]) ? sanitize_text_field(wp_unslash($_POST['datanya'][0])) : '';
    $id = isset($_POST['datanya'][1]) ? absint($_POST['datanya'][1]) : 0;

    $id_login = wp_get_current_user()->ID;

    $row = $wpdb->get_row($wpdb->prepare('SELECT a.name, a.whatsapp, b.title FROM '.$table_name2.' a LEFT JOIN '.$table_name3.' b ON b.campaign_id = a.campaign_id WHERE a.id = %d', $id));

    $name = '';
    $title = '';
    $wa = '';
    if($row!=null){
    	$name = $row[0]->name;
    	$title = $row[0]->title;
    	$title = str_replace("&#39;", "'", $title);
    	$wa = $row[0]->whatsapp;
    }

	// Gunakan prepare agar aman
	$ip_whitelists = $wpdb->get_var(
	    $wpdb->prepare("SELECT ip FROM $table_name WHERE ip = %s and status = 0 LIMIT 1", $ip_user)
	);

	$ip_exists = $wpdb->get_var(
	    $wpdb->prepare("SELECT ip FROM $table_name WHERE ip = %s and status = 1 LIMIT 1", $ip_user)
	);

	// Debug (jika perlu)

	if ( $ip_whitelists ) {
	    // data sudah ada
	    ob_clean();
	    echo 'whitelist';
	    wp_die();
	}else{

		if ( $ip_exists ) {
		    // data sudah ada
		    ob_clean();
		    echo 'exist';
		    wp_die();
		}else{
			// Detect CIDR range input (e.g. "192.168.1.0/24") and store in cidr column.
			$ip_field = $ip_user;
			$cidr_field = null;
			if ( strpos( $ip_user, '/' ) !== false ) {
				list( $subnet, $bits ) = explode( '/', $ip_user, 2 );
				$bits = (int) trim( $bits );
				if ( filter_var( trim( $subnet ), FILTER_VALIDATE_IP ) && $bits >= 0 && $bits <= 128 ) {
					// For CIDR rows we keep the canonical network address in `ip`,
					// and the cidr string in `cidr` for matching.
					$ip_field   = trim( $subnet );
					$cidr_field = trim( $subnet ) . '/' . $bits;
				}
			}
			// insert
			$wpdb->insert(
	            $table_name, //table
	            array(
		            'ip' 	=> $ip_field,
		            'cidr' => $cidr_field,
		            'note' 	=> $name.' dengan WA: '.$wa.' di Campaign: '.$title,
		            'status' 		=> 1,
		            'created_by' 	=> $id_login,
		            'created_at' 	=> date("Y-m-d H:i:s")),
	            array('%s', '%s', '%s') //data format         
	        );
	        ob_clean();
	        echo '<span style="color:#e1345e;font-weight:bold;">'.$ip_user.'</span> <span style="color:#e1345e;">(Blocked)</span>';
	        wp_die();
		}

	}

}
