function dykfunction_open_whatsapp(){
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_blocked_whatsapp";

    // FROM INPUT
    $whatsapp_in = isset($_POST['datanya'][0]) ? wp_unslash($_POST['datanya'][0]) : '';
    $variants    = wa_variants_08_628($whatsapp_in);

    if (empty($variants)) {
        echo 'not exist';
        wp_die();
    }

    // Cek apakah salah satu varian ada
    $placeholders = implode(',', array_fill(0, count($variants), '%s'));
    $sql_check = $wpdb->prepare(
        "SELECT COUNT(*) FROM {$table_name} WHERE whatsapp IN ($placeholders) and status = 1",
        $variants
    );
    $exists_count = (int) $wpdb->get_var($sql_check);

    if ($exists_count > 0) {
        // Hapus semua varian yang cocok (sekalian bersihkan)
        $sql_del = $wpdb->prepare(
            "DELETE FROM {$table_name} WHERE whatsapp IN ($placeholders) and status = 1",
            $variants
        );
        $wpdb->query($sql_del);

        ob_clean();
        echo $whatsapp_in; // pertahankan perilaku lama: kirim balik input
    } else {
        ob_clean();
        echo 'not exist';
    }

    wp_die();
}
