function check_blocked_ip(){

	global $wpdb;
	$table_settings = $wpdb->prefix . "dyk_settings";
	$ip_user = donasiyuk_getIP();

	// 1) Rate-limit guard (silent, no new dep — uses WP transients).
	//    Disabled if all 4 settings are 0.
	$rate_settings = $wpdb->get_results(
		"SELECT data FROM $table_settings
		 WHERE type IN ('rate_limit_front_max','rate_limit_front_window','rate_limit_form_max','rate_limit_form_window')"
	);
	$rl_front_max   = isset($rate_settings[0]) ? (int)$rate_settings[0]->data : 0;
	$rl_front_window= isset($rate_settings[1]) ? (int)$rate_settings[1]->data : 0;
	$rl_form_max    = isset($rate_settings[2]) ? (int)$rate_settings[2]->data : 0;
	$rl_form_window = isset($rate_settings[3]) ? (int)$rate_settings[3]->data : 0;
	// Backtrace to know if this is a form submit or front page.
	$is_form_submit = dyk_is_form_submit_context();
	if ( $is_form_submit && $rl_form_max > 0 && $rl_form_window > 0 ) {
		$rl = dyk_rate_limit_check( 'form_submit', $ip_user, $rl_form_max, $rl_form_window );
	} elseif ( ! $is_form_submit && $rl_front_max > 0 && $rl_front_window > 0 ) {
		$rl = dyk_rate_limit_check( 'front_pages', $ip_user, $rl_front_max, $rl_front_window );
	} else {
		$rl = array( 'allowed' => true );
	}
	if ( empty( $rl['allowed'] ) ) {
		require_once( ROOTDIR_DYK . 'donasiyuk-403.php' );
		exit;
	}

	// 2) Hard block IP check (exact OR CIDR range).
	if ( dyk_ip_is_blocked( $ip_user ) ) {
		require_once( ROOTDIR_DYK . 'donasiyuk-403.php' );
		exit;
	}
}

// Returns true when current request is a donation form submission context
// (admin-ajax action dykfunction_submit_donasi, or POST to admin-post.php).
function dyk_is_form_submit_context(){
	if ( empty( $_SERVER['REQUEST_METHOD'] ) || strtoupper( $_SERVER['REQUEST_METHOD'] ) !== 'POST' ) {
		return false;
	}
	if ( isset( $_POST['action'] ) && is_string( $_POST['action'] )
		&& in_array( $_POST['action'], array( 'dykfunction_submit_donasi' ), true ) ) {
		return true;
	}
	return false;
}

// Transient-based per-IP rate limiter. No external dependency.
// Returns array('allowed'=>bool,'count'=>int,'limit'=>int,'window'=>int).
function dyk_rate_limit_check( $bucket, $ip, $max, $window_seconds ){
	$ip = (string) $ip;
	if ( $ip === '' || $ip === '0.0.0.0' ) {
		return array( 'allowed' => true, 'count' => 0, 'limit' => (int)$max, 'window' => (int)$window_seconds );
	}
	$key = 'dyk_rl_' . substr( md5( $bucket . '|' . $ip ), 0, 32 );
	$count = (int) get_transient( $key );
	$count++;
	if ( $count === 1 ) {
		set_transient( $key, $count, max( 1, (int)$window_seconds ) );
	} elseif ( $count > (int)$max ) {
		// Refresh window so a flood keeps blocking for the full window.
		set_transient( $key, $count, max( 1, (int)$window_seconds ) );
		return array( 'allowed' => false, 'count' => $count, 'limit' => (int)$max, 'window' => (int)$window_seconds );
	} else {
		// Keep the original expiry; transient_set would reset it.
		// Cheap reset only when value changes by >=10 to avoid write churn.
		if ( $count % 10 === 0 ) {
			set_transient( $key, $count, max( 1, (int)$window_seconds ) );
		}
	}
	return array( 'allowed' => true, 'count' => $count, 'limit' => (int)$max, 'window' => (int)$window_seconds );
}

// True if $ip is in dyk_blocked_ip (status=1) by exact match OR CIDR range.
// CIDR rows are detected by presence of non-empty `cidr` column value.
function dyk_ip_is_blocked( $ip ){
	global $wpdb;
	$table_name = $wpdb->prefix . "dyk_blocked_ip";

	if ( ! filter_var( $ip, FILTER_VALIDATE_IP ) ) {
		return false;
	}

	// Exact match fast path (and whitelist short-circuit).
	$row = $wpdb->get_row(
		$wpdb->prepare(
			"SELECT status FROM $table_name WHERE ip = %s LIMIT 1",
			$ip
		)
	);
	if ( $row && (int) $row->status === 1 ) {
		return true;
	}
	if ( $row && (int) $row->status === 0 ) {
		return false;
	}

	// CIDR range scan (only rows with non-empty cidr column).
	static $has_cidr_col = null;
	if ( $has_cidr_col === null ) {
		$col_check = $wpdb->get_results( "SHOW COLUMNS FROM `{$table_name}` LIKE 'cidr'" );
		$has_cidr_col = ! empty( $col_check );
	}
	if ( ! $has_cidr_col ) {
		return false;
	}

	// Use a small CIDR list — cap to 500 to keep page-load bounded.
	$cidrs = $wpdb->get_col(
		"SELECT cidr FROM $table_name
		 WHERE status = 1 AND cidr IS NOT NULL AND cidr <> ''
		 ORDER BY id DESC LIMIT 500"
	);
	if ( empty( $cidrs ) ) {
		return false;
	}
	foreach ( $cidrs as $cidr ) {
		if ( dyk_ip_in_cidr( $ip, $cidr ) ) {
			return true;
		}
	}
	return false;
}

// IPv4/IPv6 CIDR match. Pure PHP, no extension required.
function dyk_ip_in_cidr( $ip, $cidr ){
	$cidr = trim( (string) $cidr );
	if ( $cidr === '' || strpos( $cidr, '/' ) === false ) {
		return false;
	}
	list( $subnet, $bits ) = explode( '/', $cidr, 2 );
	$subnet = trim( $subnet );
	$bits   = (int) trim( $bits );
	if ( ! filter_var( $subnet, FILTER_VALIDATE_IP ) || ! filter_var( $ip, FILTER_VALIDATE_IP ) ) {
		return false;
	}
	// IPv4 must use 0-32, IPv6 0-128.
	$is_v4_subnet = ( strpos( $subnet, ':' ) === false );
	$is_v4_ip     = ( strpos( $ip, ':' ) === false );
	if ( $is_v4_subnet !== $is_v4_ip ) {
		return false;
	}
	if ( $is_v4_subnet ) {
		if ( $bits < 0 || $bits > 32 ) return false;
		$ip_long     = ip2long( $ip );
		$subnet_long = ip2long( $subnet );
		if ( $ip_long === false || $subnet_long === false ) return false;
		$mask = ( $bits === 0 ) ? 0 : ( -1 << ( 32 - $bits ) ) & 0xFFFFFFFF;
		return ( ( $ip_long & $mask ) === ( $subnet_long & $mask ) );
	}
	// IPv6 path via binary string compare.
	if ( $bits < 0 || $bits > 128 ) return false;
	$ip_bin     = inet_pton( $ip );
	$subnet_bin = inet_pton( $subnet );
	if ( $ip_bin === false || $subnet_bin === false ) return false;
	$full_bytes = intdiv( $bits, 8 );
	$rem_bits   = $bits % 8;
	if ( $full_bytes > 0 && substr( $ip_bin, 0, $full_bytes ) !== substr( $subnet_bin, 0, $full_bytes ) ) {
		return false;
	}
	if ( $rem_bits === 0 ) {
		return true;
	}
	$mask = chr( ( 0xFF << ( 8 - $rem_bits ) ) & 0xFF );
	return ( ( $ip_bin[$full_bytes] & $mask ) === ( $subnet_bin[$full_bytes] & $mask ) );
}

