function wa_variants_08_628($wa){

    // hanya digit
    $digits = preg_replace('/\D/', '', trim($wa));
    if ($digits === '') return [];

    if (strpos($digits, '08') === 0) {
        // 0813… -> [0813…, 62813…]
        return [$digits, '62' . substr($digits, 1)];
    } elseif (strpos($digits, '628') === 0) {
        // 62813… -> [0813…, 62813…]
        return ['0' . substr($digits, 2), $digits];
    } else {
        // format lain (biarkan satu saja)
        return [$digits];
    }

}



function wa_variants_08_628_2($wa){

    // // Hapus semua karakter non-digit
    $digits = preg_replace('/\D/', '', trim($wa));
    if ($digits === '') return '';

    // Jika diawali 08 → ubah ke 628...
    if (strpos($digits, '08') === 0) {
        return '62' . substr($digits, 1);
    }
    // Jika sudah 628... → biarkan
    elseif (strpos($digits, '628') === 0) {
        return $digits;
    }
    // Jika diawali 8... → tambahkan 62
    elseif (strpos($digits, '8') === 0) {
        return '62' . $digits;
    }
    // Jika diawali 0... (tapi bukan 08)
    elseif (strpos($digits, '0') === 0) {
        return '62' . substr($digits, 1);
    }
    // Selain itu kembalikan apa adanya
    else {
        return $digits;
    }

}



function check_blocked_wa_status($wa_number){
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_blocked_whatsapp";

    // buat varian berdasarkan input
    $variants = wa_variants_08_628($wa_number);

    if (empty($variants)) {
        return '<span>'.esc_html($wa_number).'</span>';
    }

    // siapkan placeholder dinamis sesuai jumlah varian
    $placeholders = implode(',', array_fill(0, count($variants), '%s'));

    // cek apakah ada salah satu yang match
    $sql = $wpdb->prepare(
        "SELECT COUNT(*) FROM $table_name WHERE whatsapp IN ($placeholders) and status = '1' LIMIT 1",
        $variants
    );
    $count = (int) $wpdb->get_var($sql);

    if ($count > 0) {
        return '<span style="color:#e1345e;font-weight:bold;">'.esc_html($wa_number).'</span> <span style="color:#e1345e;">(Blocked)</span>';
    }
    return '<span>'.esc_html($wa_number).'</span>';
}



function check_spammer($whatsapp, $ip_user){
    global $wpdb;
    $table_name  = $wpdb->prefix . "dyk_blocked_whatsapp";
    $table_name2  = $wpdb->prefix . "dyk_blocked_ip";
    $table_donate = $wpdb->prefix . "dyk_donate";
    $table_settings = $wpdb->prefix . "dyk_settings";


    // GET SETTINGS
	$query_settings = $wpdb->get_results('SELECT data from '.$table_settings.' where type="form_spammer_setting" or type="max_input_ip" or type="max_input_whatsapp" or type="blokir_mode" ORDER BY id ASC');
    $form_spammer_setting = $query_settings[0]->data;
    $max_input_ip 		  = $query_settings[1]->data;
    $max_input_whatsapp   = $query_settings[2]->data;
    $blokir_mode   		  = $query_settings[3]->data;


    if($max_input_ip=='' || $max_input_ip=='0'){
    	$max_input_ip = 2;
    }
    if($max_input_whatsapp=='' || $max_input_whatsapp=='0'){
    	$max_input_whatsapp = 2;
    }

    // buat varian berdasarkan input (misal: 08123, 628123, +628123)
    $variants = wa_variants_08_628($whatsapp); // array number : 085xx and 6285xx
    $variants2 = wa_variants_08_628_2($whatsapp); // single number

    // placeholder dinamis
    $placeholders = implode(',', array_fill(0, count($variants), '%s'));


    // =======================================================
    // --- 0 CEK APAKAH NOMOR masuk WHITELIST ---
    // =======================================================
    $wa_whitelist = $wpdb->prepare(
        "SELECT COUNT(*) FROM $table_name WHERE whatsapp IN ($placeholders) and status = '0' LIMIT 1",
        $variants
    );
    $wa_whitelist_count = (int) $wpdb->get_var($wa_whitelist);
    if ($wa_whitelist_count > 0) {
        return 'normal';
    }


    // =======================================================
    // --- 0 CEK APAKAH IP masuk WHITELIST ---
    // =======================================================
    $ip_whitelist_exists = $wpdb->get_var(
	    $wpdb->prepare("SELECT ip FROM $table_name2 WHERE ip = %s and status = 0 LIMIT 1", $ip_user)
	);
	if ( $ip_whitelist_exists ) {
		return 'normal';
	}


	// =======================================================
    // --- 1 CEK APAKAH NOMOR WHATSAPP DIBLOKIR ---
    // =======================================================
    $wa_block = $wpdb->prepare(
        "SELECT COUNT(*) FROM $table_name WHERE whatsapp IN ($placeholders) and status = '1' LIMIT 1",
        $variants
    );
    $wa_blocked_count = (int) $wpdb->get_var($wa_block);
    if ($wa_blocked_count > 0) {
        return 'blocked_wa';
    }

	// =======================================================
    // --- 1 CEK APAKAH IP DIBLOKIR ---
    // =======================================================
    $ip_exists = $wpdb->get_var(
	    $wpdb->prepare("SELECT ip FROM $table_name2 WHERE ip = %s and status = '1' LIMIT 1", $ip_user)
	);
    if ($ip_exists) {
        return 'blocked_ip';
    }

    // =======================================================
    // --- 2 CEK APAKAH SUDAH SUBMIT DENGAN IP >= 2x (SPAM) ---
    // =======================================================
   	$sql_donate_ip = $wpdb->prepare("
   		SELECT COUNT(*) FROM $table_donate 
   		WHERE ip = %s 
   		AND created_at >= NOW() - INTERVAL 1 DAY", $ip_user
   	);

	$donate_count_ip = (int) $wpdb->get_var($sql_donate_ip);
    if ($donate_count_ip >= $max_input_ip) {

    	if($blokir_mode=='0'){
    		return 'blocked';
    	}else{
    		$note = 'IP diblocked setelah submit donasi dengan data IP yang sama lebih dari 2 kali dalam kurun waktu 1x24 jam';
	    	set_blocked_ip($ip_user, $note); // langsung set spam ip nya
	        return 'spam';
    	}
    	
    }

    // =======================================================
    // --- 2 CEK APAKAH SUDAH SUBMIT WHATSAPP >= 2x (SPAM) ---
    // =======================================================
    $sql_donate_wa = $wpdb->prepare("
    	SELECT COUNT(*) FROM $table_donate 
    	WHERE whatsapp = %s
    	AND created_at >= NOW() - INTERVAL 1 DAY",
        $variants2
    );
    
    $donate_count_wa = (int) $wpdb->get_var($sql_donate_wa);
    if ($donate_count_wa >= $max_input_whatsapp) {
    	if($blokir_mode=='0'){
    		return 'blocked';
    	}else{
	    	$note = 'IP diblocked setelah submit donasi dengan data whatsapp yang sama lebih dari 2 kali dalam kurun waktu 1x24 jam';
	    	set_blocked_ip($ip_user, $note); // langsung set spam IP nya
	        return 'spam';
    	}
    }

    // --- 3 DEFAULT NORMAL ---
    return 'normal';
}



function dykfunction_check_wa_exist($whatsapp){
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";

    $whatsapp 	= $_POST['datanya'][0];
    $whatsapp   = wa_variants_08_628_2($whatsapp);

    // GET SETTINGS
	$query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="wanotif_url" or type="wanotif_apikey" or type="wanotif_on" ORDER BY id ASC');
    $wanotif_url 	= $query_settings[0]->data;
    $wanotif_apikey = $query_settings[1]->data;
    $wanotif_on 	= $query_settings[2]->data;

    if($wanotif_apikey!='' && $wanotif_on=='1'){

    	$url = $wanotif_url.'/checknumber';

		$curl = curl_init();
		curl_setopt($curl, CURLOPT_URL, $url);
		curl_setopt($curl, CURLOPT_HEADER, 0);
		curl_setopt($curl, CURLOPT_RETURNTRANSFER, 1);
		curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 2);
		curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
		curl_setopt($curl, CURLOPT_TIMEOUT,30);
		curl_setopt($curl, CURLOPT_POST, 1);
		curl_setopt($curl, CURLOPT_POSTFIELDS, array(
		  'Apikey'    => $wanotif_apikey,
		  'Number'    => $whatsapp,
		));

		$response = curl_exec($curl);
		$err = curl_error($curl);

	    curl_close($curl);

	    ob_clean();

	    if ($err) {
	      echo "cURL Error #:" . $err;
	    }else{
	    	$array = json_decode( $response, true );
			$data_wanotif_status = $array['wanotif']['status'];

			if($data_wanotif_status=='exist'){
			    echo 'exist';
			}elseif($data_wanotif_status=='not_exist'){
			     echo 'not_exist';
			}else{
				echo 'error';
			}
		
	    }
    }else{
    	echo 'wanotif_off';
    }

    wp_die();
}
