function donasiyuk_getIP(){
	$ip = '0.0.0.0';

	$remote_ip = isset( $_SERVER['REMOTE_ADDR'] ) ? wp_unslash( $_SERVER['REMOTE_ADDR'] ) : '';
	if ( is_string( $remote_ip ) && filter_var( $remote_ip, FILTER_VALIDATE_IP ) ) {
		$ip = $remote_ip;
	}

	if ( ! empty( $_SERVER['HTTP_CF_CONNECTING_IP'] ) ) {
		$cf_ip = trim( (string) wp_unslash( $_SERVER['HTTP_CF_CONNECTING_IP'] ) );
		if ( filter_var( $cf_ip, FILTER_VALIDATE_IP ) ) {
			$ip = $cf_ip;
		}
	}

	return $ip;
}


function donasiyuk_getOS() {
	$user_agent = isset( $_SERVER['HTTP_USER_AGENT'] ) ? strtolower( (string) wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) : '';
	$os_platform = 'Unknown OS Platform';
	$os_array = array(
		'/windows nt 10/i'      => 'Windows 10',
		'/windows nt 6.3/i'     => 'Windows 8.1',
		'/windows nt 6.2/i'     => 'Windows 8',
		'/windows nt 6.1/i'     => 'Windows 7',
		'/windows nt 6.0/i'     => 'Windows Vista',
		'/windows nt 5.2/i'     => 'Windows Server 2003/XP x64',
		'/windows nt 5.1/i'     => 'Windows XP',
		'/windows xp/i'         => 'Windows XP',
		'/windows nt 5.0/i'     => 'Windows 2000',
		'/windows me/i'         => 'Windows ME',
		'/win98/i'              => 'Windows 98',
		'/win95/i'              => 'Windows 95',
		'/win16/i'              => 'Windows 3.11',
		'/macintosh|mac os x/i' => 'Mac OS X',
		'/mac_powerpc/i'        => 'Mac OS 9',
		'/linux/i'              => 'Linux',
		'/ubuntu/i'             => 'Ubuntu',
		'/iphone/i'             => 'iPhone',
		'/ipod/i'               => 'iPod',
		'/ipad/i'               => 'iPad',
		'/android/i'            => 'Android',
		'/blackberry/i'         => 'BlackBerry',
		'/webos/i'              => 'Mobile'
	);

	foreach ( $os_array as $regex => $value ) {
		if ( preg_match( $regex, $user_agent ) ) {
			$os_platform = $value;
		}
	}

	return $os_platform;
}

function donasiyuk_getBrowser() {
	$user_agent = isset( $_SERVER['HTTP_USER_AGENT'] ) ? strtolower( (string) wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) : '';
	$browser = 'Unknown Browser';
	$browser_array = array(
		'/msie/i'      => 'Internet Explorer',
		'/firefox/i'   => 'Firefox',
		'/safari/i'    => 'Safari',
		'/chrome/i'    => 'Chrome',
		'/edge/i'      => 'Edge',
		'/opera/i'     => 'Opera',
		'/netscape/i'  => 'Netscape',
		'/maxthon/i'   => 'Maxthon',
		'/konqueror/i' => 'Konqueror',
		'/mobile/i'    => 'Handheld Browser'
	);

	foreach ( $browser_array as $regex => $value ) {
		if ( preg_match( $regex, $user_agent ) ) {
			$browser = $value;
		}
	}

	return $browser;
}



function donasiyuk_getMobDesktop() {
	$useragent = isset( $_SERVER['HTTP_USER_AGENT'] ) ? strtolower( (string) wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) : '';

	if ( preg_match('/(android|bb\d+|meego).+mobile|avantgo|bada\/|blackberry|blazer|compal|elaine|fennec|hiptop|iemobile|ip(hone|od)|iris|kindle|lge |maemo|midp|mmp|mobile.+firefox|netfront|opera m(ob|in)i|palm( os)?|phone|p(ixi|re)\/|plucker|pocket|psp|series(4|6)0|symbian|treo|up\.(browser|link)|vodafone|wap|windows ce|xda|xiino/i', $useragent) || preg_match('/1207|6310|6590|3gso|4thp|50[1-6]i|770s|802s|a wa|abac|ac(er|oo|s\-)|ai(ko|rn)|al(av|ca|co)|amoi|an(ex|ny|yw)|aptu|ar(ch|go)|as(te|us)|attw|au(di|\-m|r |s )|avan|be(ck|ll|nq)|bi(lb|rd)|bl(ac|az)|br(e|v)w|bumb|bw\-(n|u)|c55\/|capi|ccwa|cdm\-|cell|chtm|cldc|cmd\-|co(mp|nd)|craw|da(it|ll|ng)|dbte|dc\-s|devi|dica|dmob|do(c|p)o|ds(12|\-d)|el(49|ai)|em(l2|ul)|er(ic|k0)|esl8|ez([4-7]0|os|wa|ze)|fetc|fly(\-|_)|g1 u|g560|gene|gf\-5|g\-mo|go(\.w|od)|gr(ad|un)|haie|hcit|hd\-(m|p|t)|hei\-|hi(pt|ta)|hp( i|ip)|hs\-c|ht(c(\-| |_|a|g|p|s|t)|tp)|hu(aw|tc)|i\-(20|go|ma)|i230|iac( |\-|\/)|ibro|idea|ig01|ikom|im1k|inno|ipaq|iris|ja(t|v)a|jbro|jemu|jigs|kddi|keji|kgt( |\/)|klon|kpt |kwc\-|kyo(c|k)|le(no|xi)|lg( g|\/(k|l|u)|50|54|\-[a-w])|libw|lynx|m1\-w|m3ga|m50\/|ma(te|ui|xo)|mc(01|21|ca)|m\-cr|me(rc|ri)|mi(o8|oa|ts)|mmef|mo(01|02|bi|de|do|t(\-| |o|v)|zz)|mt(50|p1|v )|mwbp|mywa|n10[0-2]|n20[2-3]|n30(0|2)|n50(0|2|5)|n7(0(0|1)|10)|ne((c|m)\-|on|tf|wf|wg|wt)|nok(6|i)|nzph|o2im|op(ti|wv)|oran|owg1|p800|pan(a|d|t)|pdxg|pg(13|\-([1-8]|c))|phil|pire|pl(ay|uc)|pn\-2|po(ck|rt|se)|prox|psio|pt\-g|qa\-a|qc(07|12|21|32|60|\-[2-7]|i\-)|qtek|r380|r600|raks|rim9|ro(ve|zo)|s55\/|sa(ge|ma|mm|ms|ny|va)|sc(01|h\-|oo|p\-)|sdk\/|se(c(\-|0|1)|47|mc|nd|ri)|sgh\-|shar|sie(\-|m)|sk\-0|sl(45|id)|sm(al|ar|b3|it|t5)|so(ft|ny)|sp(01|h\-|v\-|v )|sy(01|mb)|t2(18|50)|t6(00|10|18)|ta(gt|lk)|tcl\-|tdg\-|tel(i|m)|tim\-|t\-mo|to(pl|sh)|ts(70|m\-|m3|m5)|tx\-9|up(\.b|g1|si)|utst|v400|v750|veri|vi(rg|te)|vk(40|5[0-3]|\-v)|vm40|voda|vulc|vx(52|53|60|61|70|80|81|83|85|98)|w3c(\-| )|webc|whit|wi(g |nc|nw)|wmlb|wonu|x700|yas\-|your|zeto|zte\-/i', substr( $useragent, 0, 4 ) ) ) {
		return 'mobile';
	}

	return 'desktop';
}

function shortDisplayNumber($num) 
{
    $units = ['', 'K', 'M', 'B', 'T'];
    for ($i = 0; $num >= 1000; $i++) {
        $num /= 1000;
    }
    return round($num, 1) . $units[$i];
}



function dykfunction_set_love(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_love";
    $table_name2 = $wpdb->prefix . "dyk_settings";

    // FROM INPUT
    $campaign_id 	= $_POST['datanya'][0];
    $donate_id 		= $_POST['datanya'][1];

    $a = donasiyuk_getIP();
    $b = donasiyuk_getOS();
    $c = donasiyuk_getBrowser();
    $d = donasiyuk_getMobDesktop();

    $id_login = wp_get_current_user()->ID;

    // Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name2.' where type="max_love" ORDER BY id ASC');
    $max_love = $query_settings[0]->data;

    $row = $wpdb->get_results('SELECT * from '.$table_name.' where ip="'.$a.'" and os="'.$b.'" and browser="'.$c.'" and mobdesktop="'.$d.'" and donate_id="'.$donate_id.'"');
    if($row==null){
    	// create
    	$wpdb->insert(
            $table_name, //table
            array(
	            'campaign_id' 	=> $campaign_id,
	            'donate_id' 	=> $donate_id,
	            'user_id' 		=> $id_login,
	            'love' 			=> 1,
	            'ip' 			=> $a,
	            'os' 			=> $b,
	            'browser' 		=> $c,
	            'mobdesktop' 	=> $d,
	            'created_at' 	=> date("Y-m-d H:i:s")),
            array('%s', '%s') //data format         
        );

    	echo '+1';

    }else{

    	$total_love = $wpdb->get_results('SELECT love from '.$table_name.' where ip="'.$a.'" and os="'.$b.'" and browser="'.$c.'" and mobdesktop="'.$d.'" and donate_id="'.$donate_id.'"')[0];
		$love = $total_love->love;

		if($max_love=='0'){
			// update
			$love = $love+1;
	    	$wpdb->update(
		            $table_name, //table
		            array(
			            'love' 	=> $love
			        ),
		            array('campaign_id' => $campaign_id, 'donate_id' => $donate_id, 'ip' => $a, 'os' => $b, 'browser' => $c, 'mobdesktop' => $d), //where
		            array('%s'), //data format
		            array('%s') //where format    
		        );

	    	ob_clean();
	    	echo "+$love";

		}else{
			if($love<=$max_love){

				$love = $love+1;
		    	$wpdb->update(
			            $table_name, //table
			            array(
				            'love' 	=> $love
				        ),
			            array('campaign_id' => $campaign_id, 'donate_id' => $donate_id, 'ip' => $a, 'os' => $b, 'browser' => $c, 'mobdesktop' => $d), //where
			            array('%s'), //data format
			            array('%s') //where format    
			        );
		    	ob_clean();
		    	echo "+$love";

			}else{
				ob_clean();
				echo "cukup";
			}
		}
    	

    }

    wp_die();
}
add_action( 'wp_ajax_dykfunction_set_love', 'dykfunction_set_love' );
add_action( 'wp_ajax_nopriv_dykfunction_set_love', 'dykfunction_set_love' );


function getBaseUrl() 
{
    // output: /myproject/index.php
    $currentPath = $_SERVER['PHP_SELF']; 

    // output: Array ( [dirname] => /myproject [basename] => index.php [extension] => php [filename] => index ) 
    $pathInfo = pathinfo($currentPath); 

    // output: localhost
    $hostName = $_SERVER['HTTP_HOST']; 

    // output: http://
    $protocol = strtolower(substr($_SERVER["SERVER_PROTOCOL"],0,5))=='https'?'https':'http';

    // return: http://localhost/myproject/
    return $protocol.'://'.$hostName.$pathInfo['dirname']."/";
}


function paymentCode($code) 
{
    global $wpdb;
