    }
}



function get_aff_user_id($affcode_id){

	global $wpdb;
    $table_name 	= $wpdb->prefix . "dyk_aff_code";

	if(!empty($affcode_id)){

    	// get aff_code
		$check_affcode = $wpdb->get_results('SELECT * from '.$table_name.' where id="'.$affcode_id.'" ');
		if(!empty($check_affcode) && isset($check_affcode[0]->user_id)){
			$aff_user_id = $check_affcode[0]->user_id;
			return $aff_user_id;
		}else{
			return null;
		}

	}else{
		return null;
	}

}


