    // Campaign Settings
    $campaign_setting = $wpdb->get_results('SELECT notification_status, wanotif_message, wanotif_message2, fundraiser_setting, fundraiser_on,  fundraiser_commission_on, fundraiser_commission_type, fundraiser_commission_percent, fundraiser_commission_fixed, general_status, allocation_title, allocation_others_title, cs_rotator, wanotif_device, form_status, minimum_donate from '.$table_name3.' where campaign_id="'.$campaign_id.'" ')[0];
