function dykfunction_regaff_fundraiser(){

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_aff_code";
    $table_name2 = $wpdb->prefix . "dyk_campaign";

    $id_login = wp_get_current_user()->ID;
    
    // FROM INPUT
    $campaign_id 	= $_POST['datanya'][0];
    $aff_code = d_randomString(5);


    if($id_login==null){
    	ob_clean();
    	echo 'loginfirst_0';
    	wp_die();
    }

    $check = $wpdb->get_results('SELECT * from '.$table_name.' where campaign_id="'.$campaign_id.'" and user_id="'.$id_login.'" ');
	if($check==null){
		// create aff_code
		// check dl aff_code sudah ada belum
		$check2 = $wpdb->get_results('SELECT * from '.$table_name.' where aff_code="'.$aff_code.'" ');
		if($check2==null){
			$wpdb->insert(
	            $table_name, //table
	            array(
		            'campaign_id' 	=> $campaign_id,
		            'user_id' 		=> $id_login,
		            'aff_code' 		=> $aff_code,
		            'created_at' 	=> date("Y-m-d H:i:s")
		        ),
	            array('%s', '%s') //data format         
	        );
	        $the_code = 'success_'.$aff_code;
		}else{
			$aff_code2 = d_randomString(6);
			$check3 = $wpdb->get_results('SELECT * from '.$table_name.' where aff_code="'.$aff_code2.'" ');
			if($check3==null){
				$wpdb->insert(
		            $table_name, //table
		            array(
			            'campaign_id' 	=> $campaign_id,
			            'user_id' 		=> $id_login,
			            'aff_code' 		=> $aff_code2,
			            'created_at' 	=> date("Y-m-d H:i:s")
			        ),
		            array('%s', '%s') //data format         
		        );
		        $the_code = 'success_'.$aff_code2;
			}else{
				$aff_code3 = d_randomString(7);
				$check4 = $wpdb->get_results('SELECT * from '.$table_name.' where aff_code="'.$aff_code3.'" ');
				if($check4==null){
					$wpdb->insert(
			            $table_name, //table
			            array(
				            'campaign_id' 	=> $campaign_id,
				            'user_id' 		=> $id_login,
				            'aff_code' 		=> $aff_code3,
				            'created_at' 	=> date("Y-m-d H:i:s")
				        ),
			            array('%s', '%s') //data format         
			        );
			        $the_code = 'success_'.$aff_code3;
				}
			}
		}
		
	}else{
		// tampilkan saja
		$the_code = 'show_'.$check[0]->aff_code;
	}

	echo $the_code;

    wp_die();

}
add_action( 'wp_ajax_dykfunction_regaff_fundraiser', 'dykfunction_regaff_fundraiser' );
add_action( 'wp_ajax_nopriv_dykfunction_regaff_fundraiser', 'dykfunction_regaff_fundraiser' );



function donasiyuk_send2tg($token, $chatID, $message_tele) {
	
	$urlweb = 'https://api.telegram.org/bot'.$token.'/sendMessage?text='.rawurlencode($message_tele).'&chat_id='.$chatID.'&parse_mode=Markdown';

	$ch = curl_init();
	curl_setopt($ch, CURLOPT_URL, $urlweb);
	curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1);
	curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
	curl_setopt($ch, CURLOPT_HEADER, 0);
	curl_setopt($ch, CURLOPT_USERAGENT, $_SERVER['HTTP_USER_AGENT']);
	curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, 0);
	curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, 0);
	curl_setopt($ch, CURLOPT_TIMEOUT, 30);

	$siteData = curl_exec($ch);
	curl_close($ch);

	return $siteData;

} 



function dykfunction_send_test_telegram(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";

    // FROM INPUT
    $channel_tele 	= isset($_POST['datanya'][0]) ? sanitize_text_field($_POST['datanya'][0]) : '';
    $message_tele 	= isset($_POST['datanya'][1]) ? sanitize_textarea_field($_POST['datanya'][1]) : '';

    // General Settings
    $settings_map = array();
    $query_settings = $wpdb->get_results('SELECT type, data from '.$table_name.' where type="telegram_bot_token" or type="telegram_send_to"');
    if ($query_settings) {
        foreach ($query_settings as $qs) {
            $settings_map[$qs->type] = $qs->data;
        }
    }
    $telegram_bot_token	= isset($settings_map['telegram_bot_token']) ? dyk_decrypt_secret($settings_map['telegram_bot_token']) : '';
    $telegram_send_to	= $settings_map['telegram_send_to'] ?? '';

	$token = $telegram_bot_token;
	$send = donasiyuk_send2tg($token, $channel_tele, $message_tele);

	$array = json_decode( $send, true );
    $data = isset($array['ok']) ? $array['ok'] : false;

	if($data==true){
		ob_clean();
		echo 'success';
	}else{
		ob_clean();
		echo 'failed';
	}

    wp_die();

} 
