function dykfunction_send_test_wanotif(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";

    // FROM INPUT
    $apikey 		= isset($_POST['datanya'][0]) ? sanitize_text_field($_POST['datanya'][0]) : '';
    $no_wa 			= isset($_POST['datanya'][1]) ? sanitize_text_field($_POST['datanya'][1]) : '';
    $message_wa 	= isset($_POST['datanya'][2]) ? sanitize_textarea_field($_POST['datanya'][2]) : '';

    // General Settings
    // GET SETTINGS
    $settings_map = array();
	$query_settings = $wpdb->get_results('SELECT type, data from '.$table_name.' where type="currency" or type="wanotif_url" or type="wanotif_apikey"');
    if ($query_settings) {
        foreach ($query_settings as $qs) {
            $settings_map[$qs->type] = $qs->data;
        }
    }
    $currency 		  = $settings_map['currency'] ?? 'IDR';
    $wanotif_url 	  = $settings_map['wanotif_url'] ?? '';
    $wanotif_apikey   = isset($settings_map['wanotif_apikey']) ? dyk_decrypt_secret($settings_map['wanotif_apikey']) : '';   
    if (!empty($wanotif_apikey)) {
        $apikey       = $wanotif_apikey;
    }

	$phone = djaPhoneFormat($no_wa,$currency);
	$url = rtrim($wanotif_url, '/') . '/send';

	$messagenya = $message_wa;

	$curl = curl_init();
	curl_setopt($curl, CURLOPT_URL, $url);
	curl_setopt($curl, CURLOPT_HEADER, 0);
	curl_setopt($curl, CURLOPT_RETURNTRANSFER, 1);
	curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 2);
	curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
	curl_setopt($curl, CURLOPT_TIMEOUT,30);
	curl_setopt($curl, CURLOPT_POST, 1);
	curl_setopt($curl, CURLOPT_POSTFIELDS, array(
	    'Apikey'    => $apikey,
	    'Phone'     => $phone,
	    'Message'   => $messagenya,
	));
	$response = curl_exec($curl);
	$err = curl_error($curl);
	curl_close($curl);

	$array = json_decode( $response, true );
	$data = isset($array['wanotif']['status']) ? $array['wanotif']['status'] : '';


    if ($err) {
      echo "cURL Error #:" . $err;
    }else{
    	if($data=='sent'){
    		ob_clean();
			echo 'success';
		}else{
			ob_clean();
			echo 'failed';
		}
    }

    wp_die();

} 
add_action( 'wp_ajax_dykfunction_send_test_wanotif', 'dykfunction_send_test_wanotif' );
add_action( 'wp_ajax_nopriv_dykfunction_send_test_wanotif', 'dykfunction_send_test_wanotif' );


function dykfunction_status_wanotif(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";

    $check_status = (isset($_POST['datanya']) && is_array($_POST['datanya']) && isset($_POST['datanya'][0])) ? $_POST['datanya'][0] : false;

    if($check_status==true){
    	// GET SETTINGS
        $settings_map = array();
		$query_settings = $wpdb->get_results('SELECT type, data from '.$table_name.' where type="wanotif_url" or type="wanotif_apikey"');
        if ($query_settings) {
            foreach ($query_settings as $qs) {
                $settings_map[$qs->type] = $qs->data;
            }
        }
	    $wanotif_url 		  = $settings_map['wanotif_url'] ?? '';
	    $wanotif_apikey 	  = isset($settings_map['wanotif_apikey']) ? dyk_decrypt_secret($settings_map['wanotif_apikey']) : '';   

		$url = rtrim($wanotif_url, '/') . '/auth';
		
		$curl = curl_init();
		curl_setopt_array($curl, [
		    CURLOPT_URL => $url,
		    CURLOPT_RETURNTRANSFER => true,
		    CURLOPT_ENCODING => "",
		    CURLOPT_MAXREDIRS => 10,
		    CURLOPT_TIMEOUT => 30,
		    CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
		    CURLOPT_CUSTOMREQUEST => "GET",
		    CURLOPT_SSL_VERIFYHOST => 0,
		    CURLOPT_SSL_VERIFYPEER => 0,
		    CURLOPT_HTTPHEADER => [
		      "Accept: application/json",
		      "Apikey: $wanotif_apikey",
		    ],
		]);

		$response = curl_exec($curl);
		$err = curl_error($curl);

	    curl_close($curl);

	    if ($err) {
	      echo "cURL Error #:" . $err;
	    }else{
	    	$array = json_decode( $response, true );
			$data_wanotif_status = isset($array['wanotif']['status']) ? $array['wanotif']['status'] : '';

			if($data_wanotif_status=='connected'){
			    $status_wanotif = '<span style="color:#36BD47;">Connected</span>';
			}elseif($data_wanotif_status=='scan'){
			    $status_wanotif =  '<a href="https://app.wanotif.id/device" class="link_href" target="_blank">Sqan QR-Code</a>';
			}else{
				if($wanotif_apikey==''){
					$status_wanotif = '-';
				}else{
					$status_wanotif = '<a href="https://app.wanotif.id/device" class="link_href" target="_blank">Check your connection on Wanotif</a>';
				}
			}
			ob_clean();
			echo $status_wanotif;
	    }

		wp_die();
    }

} 
add_action( 'wp_ajax_dykfunction_status_wanotif', 'dykfunction_status_wanotif' );
add_action( 'wp_ajax_nopriv_dykfunction_status_wanotif', 'dykfunction_status_wanotif' );



