function dykfunction_get_status() {
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";

    // FROM INPUT
    $d_status = isset($_POST['datanya'][0]) ? sanitize_text_field(wp_unslash($_POST['datanya'][0])) : '';
    $d_id = isset($_POST['datanya'][1]) ? absint($_POST['datanya'][1]) : 0;

    ob_clean();
    // GET DATA DONATE
    if($d_status === '0'){
    	$row = $wpdb->get_row($wpdb->prepare('SELECT * FROM '.$table_name.' WHERE id = %d', $d_id));
	    if($row && $row->status == '1'){
	    	ob_clean();
	    	echo 'success';
	    }else{
	    	ob_clean();
	    	echo 'waiting';
	    }
    }else{
    	ob_clean();
    	echo 'waiting';
    }
    
	wp_die();
}
add_action( 'wp_ajax_dykfunction_get_status', 'dykfunction_get_status' );
add_action( 'wp_ajax_nopriv_dykfunction_get_status', 'dykfunction_get_status' );


function dykfunction_update_confirmation(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";
    $table_name2 = $wpdb->prefix . "dyk_settings";
    $table_name3 = $wpdb->prefix . "dyk_campaign";
    $table_name5 	= $wpdb->prefix . "dyk_aff_submit";
    $table_name6 	= $wpdb->prefix . "dyk_aff_code";

    // FROM INPUT
    $link_image 	= $_POST['datanya'][0];
    $invoice_id 	= $_POST['datanya'][1];

    // General Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name2.' where type="currency" or type="telegram_bot_token" or type="telegram_send_to" or type="telegram_on" or type="telegram_manual_confirmation" ORDER BY id ASC');
    $currency 				= $query_settings[0]->data;
    $telegram_bot_token 	= dyk_decrypt_secret($query_settings[1]->data);
    $telegram_send_to 		= $query_settings[2]->data;
    $telegram_on 			= $query_settings[3]->data;
    $telegram_manual_confirmation 	= $query_settings[4]->data;


    // GET DATA DONATE
    $row = $wpdb->get_results('SELECT a.*, b.title, b.slug from '.$table_name.' a 
    left JOIN '.$table_name3.' b ON b.campaign_id = a.campaign_id where a.invoice_id="'.$invoice_id.'" ')[0];

    $row2 = $wpdb->get_results("SELECT * FROM $table_name5 where donate_id='$row->id' ")[0];

	// Data FORMAT
    $date_created = date("Y-m-d H:i:s");

	$data_field = array();
    $data_field[ '{name}' ] 	= $row->name;
    $data_field[ '{sapaan}' ] 	= $row->sapaan;
    $data_field[ '{salam}' ] 	= $row->sapaan;
    $data_field[ '{whatsapp}' ] = $row->whatsapp;
    $data_field[ '{email}' ] 	= $row->email;
    $data_field[ '{comment}' ] 	= $row->comment;
    $data_field[ '{payment_number}' ] 	= $row->payment_number;
    $data_field[ '{payment_code}' ] 	= paymentCode($row->payment_code);
    $data_field[ '{payment_account}' ] 	= $row->payment_account;
    $data_field[ '{campaign_title}' ] 	= $row->title;
    $data_field[ '{campaign_url}' ] 	= get_site_url().'/campaign/'.$row->slug;
    $data_field[ '{invoice_id}' ] 		= $row->invoice_id;
    $data_field[ '{date}' ] 			= date("j F Y - H:i",strtotime($row->date_created));
    $data_field[ '{link_ekuitansi}' ] 	= get_site_url().'/ekuitansi/'.$row->invoice_id;
    $data_field[ '{link_sertifikat}' ] 	= get_site_url().'/sertifikat/'.$row->invoice_id;

    if($currency=='IDR'){
    	$data_field[ '{total}' ] 	= 'Rp '.number_format_currency($row->nominal);
    }elseif($currency=='MYR'){
    	$data_field[ '{total}' ] 	= 'RM '.number_format_currency($row->nominal);
    }else{
    	$data_field[ '{total}' ] 	= $row->nominal;
    }

    $fundraiser_name = '-';
    if($row2!=null){
		$query_donation = $wpdb->get_results("SELECT b.user_id as fundraiser_id FROM $table_name5 a
	    LEFT JOIN $table_name6 b ON b.id = a.affcode_id 
	    where a.affcode_id='$row->affcode_id' ORDER BY a.id DESC ")[0];

	    if($query_donation->fundraiser_id!=''){
	        $user_info = get_userdata($query_donation->fundraiser_id);
	        $fundraiser_name = $user_info->first_name.' '.$user_info->last_name;
	    }
	    $data_field[ '{fundraiser}' ] = $fundraiser_name;
	}else{
		$data_field[ '{fundraiser}' ] = '-';
	}

	// GET DATA CAMPAIGN
	$campaign_id = $row->campaign_id;
	$query_campaign = $wpdb->get_results('SELECT user_id from '.$table_name3.' 
	where campaign_id="'.$campaign_id.'" ');

	if (isset($query_campaign[0]->user_id)) {
	    $user_info = get_userdata($query_campaign[0]->user_id);
	    $campaigner_name = trim($user_info->first_name . ' ' . $user_info->last_name);
	    $data_field[ '{campaigner}' ] = !empty($campaigner_name) ? $campaigner_name : '-';
	} else {
	    $data_field[ '{campaigner}' ] = '-';
	}

	
	// TELEGRAM
	if($telegram_on=='1'){
		$token = $telegram_bot_token;
		$telegram_manual_confirmation = json_decode($telegram_manual_confirmation);

		foreach($telegram_manual_confirmation as $key => $value) {

            $message_tele = $value->message;
            $message_tele = strtr($message_tele, $data_field);
            $channel = $value->channel;
			
			if (strpos($channel, ',') !== false ) {
				$array_channel  = (explode(",", $channel));
				foreach ($array_channel as $values){
					$channel_id = $values;
					$send = donasiyuk_send2tg($token, $channel_id, $message_tele);
				}
			}else{
				$channel_id = $channel;
				$send = donasiyuk_send2tg($token, $channel_id, $message_tele);
			}

		}
	}

	// ACTION Update TO DB tanpa form_type dan packaged
 	$a = $wpdb->update(
        $table_name, //table
        array(
            'img_confirmation_url' 	=> $link_image,
            'img_confirmation_date' => date("Y-m-d H:i:s"),
        ),
        array('invoice_id' => $invoice_id), //where
        array('%s'), //data format
        array('%s') //where format
    );

 	ob_clean();
	echo 'success';

    wp_die();
}
add_action( 'wp_ajax_dykfunction_update_confirmation', 'dykfunction_update_confirmation' );



function dykfunction_get_data_users(){
	global $wpdb;
    $table_name2 = $wpdb->prefix . "dyk_campaign";
    $table_name3 = $wpdb->prefix . "users";
    $table_name4 = $wpdb->prefix . "dyk_users";

    // FROM INPUT
    $campaign_id = (isset($_POST['datanya']) && is_array($_POST['datanya']) && isset($_POST['datanya'][0])) ? sanitize_text_field($_POST['datanya'][0]) : '';

    $row2 = null;
    if(!empty($campaign_id)){
        $res = $wpdb->get_results($wpdb->prepare("SELECT title, user_id FROM $table_name2 where campaign_id=%s", $campaign_id));
        if(!empty($res)){
            $row2 = $res[0];
        }
    }
    	
    $data_userwp = $wpdb->get_results('SELECT a.ID, a.display_name, a.user_email, b.user_wa, b.user_pp_img, b.user_randid from '.$table_name3.' a 
    left JOIN '.$table_name4.' b ON b.user_id = a.ID
    where b.user_verification="1" ');

	$data_user = '';
	if(!empty($data_userwp) && is_array($data_userwp)){
		foreach ( $data_userwp as $user ) {
			$selected = '';
			if(!empty($row2) && isset($row2->user_id) && (int)$row2->user_id === (int)$user->ID){
				$selected = 'selected';
			}

		    $data_user .= '<option value="'.esc_attr($user->display_name).'" data-userid="'.esc_attr($user->ID).'" data-name="'.esc_attr($user->display_name).'" '.$selected.'><span>'.esc_html($user->display_name).' - ('.esc_html($user->user_email).')</span></option>';
		}
	}

	$user_data_select = '<select class="select2 form-control mb-3 custom-select usernya_select" style="width: 80%; height:42px;"><option value="">Select User</option>'.$data_user.'</select><script>console.log(1);</script>';

    echo $user_data_select;

    wp_die();
}
add_action( 'wp_ajax_dykfunction_get_data_users', 'dykfunction_get_data_users' );
add_action( 'wp_ajax_nopriv_dykfunction_get_data_users', 'dykfunction_get_data_users' );



