function dykfunction_update_wa(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_blocked_whatsapp";

    // FROM INPUT
    $id       = (isset($_POST['datanya']) && is_array($_POST['datanya']) && isset($_POST['datanya'][0])) ? sanitize_text_field($_POST['datanya'][0]) : '';
    $whatsapp = (isset($_POST['datanya']) && is_array($_POST['datanya']) && isset($_POST['datanya'][1])) ? sanitize_text_field($_POST['datanya'][1]) : '';
    $note     = (isset($_POST['datanya']) && is_array($_POST['datanya']) && isset($_POST['datanya'][2])) ? sanitize_textarea_field(str_replace('\\', '', $_POST['datanya'][2])) : '';

    $a = $wpdb->update(
        $table_name, //table
        array(
            'whatsapp' 	=> $whatsapp,
            'note' 	=> $note
        ),
        array('id' => $id), //where
        array('%s', '%s'), //data format
        array('%s') //where format
    );
	
	if ($a === false) {
	    // Jika terjadi error
	    $info = 'error';
	} elseif ($a === 0) {
	    // Jika tidak ada baris yang terupdate (misalnya nilai sudah 1 sebelumnya)
	    $info = 'success';
	} else {
	    // Jika berhasil update (1 atau lebih baris diperbarui)
	    $info = 'success';
	}

	ob_clean();
    echo $info;

    wp_die();
}
add_action( 'wp_ajax_dykfunction_update_wa', 'dykfunction_update_wa' );
add_action( 'wp_ajax_nopriv_dykfunction_update_wa', 'dykfunction_update_wa' );




