function dykfunction_add_wa(){

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_blocked_whatsapp";

    // FROM INPUT
    $whatsapp 	= $_POST['datanya'][0];
    $note 	= str_replace('\\', '', $_POST['datanya'][1]);
    $status 	= $_POST['datanya'][2];

    // $whatsapp = wa_variants_08_628($whatsapp);

    if($status=='blocked'){
    	$status = 1;
    }else{
    	$status = 0;
    }

    $id_login = wp_get_current_user()->ID;

	if($status==1){

		// check apakah ada wa whitelist, klo ada gagal insert
		$wa_whitelist_exists = $wpdb->get_var(
		    $wpdb->prepare("SELECT whatsapp FROM $table_name WHERE whatsapp = %s and status = 0 LIMIT 1", $whatsapp)
		);
		// Debug (jika perlu)
		if ( $wa_whitelist_exists ) {
		    // data sudah ada
		    ob_clean();
		    echo 'whitelistexist';
		}else{

			// insert
			$wpdb->insert(
	            $table_name, //table
	            array(
		            'whatsapp' 	=> $whatsapp,
		            'note' 		=> $note,
		            'status' 	=> $status,
		            'created_by' 	=> $id_login,
		            'created_at' 	=> date("Y-m-d H:i:s")),
	            array('%s', '%s') //data format         
	        );

	        $whatsapp_id = $wpdb->insert_id;

	        ob_clean();
	        echo 'success_'.$whatsapp_id;
		}


	}else{


		$wa_exists = $wpdb->get_var(
		    $wpdb->prepare("SELECT whatsapp FROM $table_name WHERE whatsapp = %s and status = $status LIMIT 1", $whatsapp)
		);

		// Debug (jika perlu)
		if ( $wa_exists ) {
		    // data sudah ada
		    ob_clean();
		    echo 'exist';
		}else{

			// wa_blocked_exists
			$wa_blocked_exists = $wpdb->get_var(
			    $wpdb->prepare("SELECT whatsapp FROM $table_name WHERE whatsapp = %s AND status = 1 LIMIT 1", $whatsapp)
			);

			if ( $wa_blocked_exists ) {
			    if ( $wpdb->get_var( $wpdb->prepare(
			        "SELECT whatsapp FROM $table_name WHERE whatsapp = %s AND status = %d LIMIT 1",
			        $whatsapp, 1
			    ) ) ) {
			        $wpdb->query( $wpdb->prepare(
			            "DELETE FROM $table_name WHERE whatsapp = %d AND status = %d",
			            $whatsapp, 1
			        ) );
			    }
			}

			// insert wa dengan status 0 atau whitelist
			$wpdb->insert(
	            $table_name, //table
	            array(
		            'whatsapp' 	=> $whatsapp,
		            'note' 		=> $note,
		            'status' 	=> $status,
		            'created_by' 	=> $id_login,
		            'created_at' 	=> date("Y-m-d H:i:s")),
	            array('%s', '%s') //data format         
	        );

	        $whatsapp_id = $wpdb->insert_id;

	        ob_clean();
	        echo 'success_'.$whatsapp_id;
		}

	}

	
    wp_die();
    
}
add_action( 'wp_ajax_dykfunction_add_wa', 'dykfunction_add_wa' );
add_action( 'wp_ajax_nopriv_dykfunction_add_wa', 'dykfunction_add_wa' );




