	';
	$user_option_input = '<span class="input-group-append icon_user '.$input_active.'" title="Edit From Data User">
                            <button type="button" class="btn btn-sm btn-primary" style="height:45px;"><i data-lucide="user" style="margin-left:4px;margin-right:4px;"></i></button>
                        </span>';
    
    if($row->payment_account=='QRIS - Remitcepat'){
    	$image_qr = generateQrisBase64($row->payment_qrcode);
    	$payment_numbernya = '<img style="width:80px;" src="'.$image_qr.'">';
    }else{
