    // FROM INPUT
    $id 		 = $_POST['datanya'][0];
    $user_id 	 = $_POST['datanya'][1];
    $name 		 = $_POST['datanya'][2];
    $whatsapp 	 = $_POST['datanya'][3];
    $email 		 = $_POST['datanya'][4];
    $comment 	 = $_POST['datanya'][5];
    $nominal 	 = $_POST['datanya'][6];
    $anonim 	 = $_POST['datanya'][7];
    $user_randid = $_POST['datanya'][8];
    $cs_id 		 = $_POST['datanya'][9];
    $sapaan 	 = $_POST['datanya'][10];

    if($anonim==''){
    	$anonim = 0;
    }else{
    	$anonim = 1;
    }

    if($cs_id==''){
    	$cs_id = null;
    }

	// ACTION Update TO DB tanpa form_type dan packaged
 	$a = $wpdb->update(
        $table_name, //table
        array(
            'user_id' 	=> $user_id,
            'name' 		=> $name,
            'whatsapp' 	=> $whatsapp,
            'email' 	=> $email,
            'comment' 	=> $comment,
            'nominal' 	=> $nominal,
            'anonim' 	=> $anonim,
            'cs_id' 	=> $cs_id,
            'sapaan' 	=> $sapaan,
        ),
        array('id' => $id), //where
        array('%s'), //data format
        array('%s') //where format
    );
 	ob_clean();
	echo 'success';

    wp_die();
}
