function dykfunction_download_donasi(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";

    $id_campaign = isset($_POST['datanya'][0]) ? sanitize_text_field($_POST['datanya'][0]) : '';
	$filename = "donasi_export_" . date('Ymd_His');
	$file_ending = "xls";

	header("Content-Type: application/vnd.ms-excel");    
	header("Content-Disposition: attachment; filename={$filename}.{$file_ending}");  
	header("Pragma: no-cache"); 
	header("Expires: 0");

	$sep = "\t";

	$where = "";
	if (!empty($id_campaign) && $id_campaign !== 'all') {
		$where = $wpdb->prepare(" WHERE campaign_id = %s", $id_campaign);
	}

	$rows = $wpdb->get_results('SELECT * from '.$table_name . $where . ' ORDER BY id ASC', ARRAY_A);
	if (!empty($rows)) {
		$headers = array_keys($rows[0]);
		echo implode($sep, $headers) . "\n";

		foreach ($rows as $row) {
			$schema_insert = "";
			foreach ($row as $value) {
				if (!isset($value) || is_null($value)) {
					$schema_insert .= "NULL" . $sep;
				} elseif ($value !== "") {
					$v = preg_replace("/\r\n|\n\r|\n|\r/", " ", (string)$value);
					$schema_insert .= $v . $sep;
				} else {
					$schema_insert .= "" . $sep;
				}
			}
			$schema_insert = rtrim($schema_insert, $sep);
			echo $schema_insert . "\n";
		}
	}

    wp_die();
}
add_action( 'wp_ajax_dykfunction_download_donasi', 'dykfunction_download_donasi' );



function download_donasi()
{
    if ( ! current_user_can( 'manage_options' ) )
        return;

    global $wpdb;
   
    $table_name = $wpdb->prefix . "dyk_donate";
    $table_name2 = $wpdb->prefix . "dyk_settings";

    // post data
    $c_id = $_GET['c_id'];
    $date_filter = $_GET['c_date'];
    $date_range = $_GET['c_range'];
    $status = $_GET['status'];

    // settings
    $query_currency = $wpdb->get_results('SELECT data from '.$table_name2.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;
    $show_currency = donasiyuk_currency($currency);
    $lang = get_data_lang($currency);
    $langArray = require_once(ROOTDIR_DYK . 'library/locale/'.$lang.'.php');

    $filternya = "";
    if($date_filter=='today' || $date_filter=='yesterday' || $date_filter=='7lastdays' || $date_filter=='30lastdays' || $date_filter=='thismonth' || $date_filter=='lastmonth' || $date_filter=='thisyear' || $date_filter=='lastyear' || $date_filter=='last2years' || $date_filter=='last3years' || $date_filter=='daterange' || $date_filter=='all'){
    
        // Date
        $today = date('Y-m-d');
        $yesterday = date("Y-m-d", strtotime("-1 day"));
        $one_week_ago = date("Y-m-d", strtotime("-7 day"));
        $one_month_ago = date("Y-m-d", strtotime("-30 day"));
        $three_months_ago = date("Y-m-d", strtotime("-90 day"));
        $thismonth = date("Y-m-01");
        $thisyear = date("Y-01-01");
        
        $month = date('m');
        $year = date('Y');
        if($month==1){
        	$monthnya = 12;
        	$yearnya = $year-1;
        }else{
        	$monthnya = $month-1;
        	$yearnya = $year;
        }
		$lastmonth_firstrange = date($yearnya."-".$monthnya."-01");
		$lastmonth_lastrange = date($yearnya."-".$monthnya."-31");

		if($date_range!=''){
			$date_range = explode('_',$date_range);
			$date_range_first = date($date_range[0]);
			$date_range_last = date($date_range[1]);
		}else{
			$date_range_first = $today;
			$date_range_last = $today;
		}

		// last year
		$lastyear_yearnya = $year-1;
		$lastyear_firstrange = date($lastyear_yearnya."-01-01");
		$lastyear_lastrange = date($lastyear_yearnya."-12-31");

		// 2 last year
		$twolastyear_yearnya = $year-2;
		$twolastyear_firstrange = date($twolastyear_yearnya."-01-01");
		$twolastyear_lastrange = date(($twolastyear_yearnya+1)."-12-31");

		// 3 last year
		$threelastyear_yearnya = $year-3;
		$threelastyear_firstrange = date($threelastyear_yearnya."-01-01");
		$threelastyear_lastrange = date(($threelastyear_yearnya+2)."-12-31");
		

        if($date_filter=='today'){
            $filternya = "and a.created_at BETWEEN '$today 00:00' AND '$today 23:59'";
        }elseif($date_filter=='yesterday'){
            $filternya = "and a.created_at BETWEEN '$yesterday 00:00' AND '$yesterday 23:59'";
        }elseif($date_filter=='7lastdays'){
            $filternya = "and a.created_at BETWEEN '$one_week_ago 00:00' AND '$today 23:59'";
        }elseif($date_filter=='30lastdays'){
            $filternya = "and a.created_at BETWEEN '$one_month_ago 00:00' AND '$today 23:59'";
        }elseif($date_filter=='3months'){
            $filternya = "and a.created_at BETWEEN '$three_months_ago 00:00' AND '$today 23:59'";
        }elseif($date_filter=='thismonth'){
            $filternya = "and a.created_at BETWEEN '$thismonth 00:00' AND '$today 23:59'";
        }elseif($date_filter=='lastmonth'){
            $filternya = "and a.created_at BETWEEN '$lastmonth_firstrange 00:00' AND '$lastmonth_lastrange 23:59'";
        }elseif($date_filter=='thisyear'){
            $filternya = "and a.created_at BETWEEN '$thisyear 00:00' AND '$today 23:59'";
        }elseif($date_filter=='lastyear'){
            $filternya = "and a.created_at BETWEEN '$lastyear_firstrange 00:00' AND '$lastyear_lastrange 23:59'";
        }elseif($date_filter=='last2years'){
            $filternya = "and a.created_at BETWEEN '$twolastyear_firstrange 00:00' AND '$twolastyear_lastrange 23:59'";
        }elseif($date_filter=='last3years'){
            $filternya = "and a.created_at BETWEEN '$threelastyear_firstrange 00:00' AND '$threelastyear_lastrange 23:59'";
        }elseif($date_filter=='daterange'){
            $filternya = "and a.created_at BETWEEN '$date_range_first 00:00' AND '$date_range_last 23:59'";
        }else{
            $filternya = "";
        }

        if($status=='waiting'){
        	$filter_status = "and status='0'";
        }elseif($status=='success'){
        	$filter_status = "and status='1'";
        }else{
        	$filter_status = "";
        }

        // and a.created_at BETWEEN '2022-03-28 00:00' AND '2022-04-27 23:59'
    }

    require_once(ROOTDIR_DYK . 'admin/f_download_excel.php');

	wp_die();
	
}
