    $row = $wpdb->get_row($wpdb->prepare('SELECT * FROM '.$table_name3.' WHERE id = %d', $donasi_id));

	// on table donasi del => deleted
    if ( $wpdb->get_var( $wpdb->prepare( 'SELECT id FROM '.$table_name3.' WHERE id = %d', $donasi_id ) ) ) {
