function dykfunction_del_donasi_trash_all(){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";
    $table_name2 = $wpdb->prefix . "dyk_love";
    $table_name3 = $wpdb->prefix . "dyk_donate_trash";

    // FROM INPUT
    $key_action = isset($_POST['datanya'][0]) ? sanitize_text_field(wp_unslash($_POST['datanya'][0])) : '';

    if($key_action === 'delete_all_trash'){

    	$rows = $wpdb->get_results('SELECT * FROM '.$table_name3.' ');

	    foreach ($rows as $row) {

	    	// on table donasi del => deleted
		    if ( $wpdb->get_var( $wpdb->prepare( 'SELECT id FROM '.$table_name3.' WHERE id = %d', $row->id ) ) ) {
		        $wpdb->query( $wpdb->prepare( 'DELETE FROM '.$table_name3.' WHERE id = %d', $row->id ) );
		    }

		    // on table love deleted too
		    if ( $wpdb->get_var( $wpdb->prepare( 'SELECT id FROM '.$table_name2.' WHERE donate_id = %d', $row->donate_id ) ) ) {
		        $wpdb->query( $wpdb->prepare( 'DELETE FROM '.$table_name2.' WHERE donate_id = %d', $row->donate_id ) );
		    }
	    }
	    ob_clean();
		echo 'success';

    }else{
    	ob_clean();
    	echo 'failed';
    }
    

    wp_die();
}
