add_action( 'wp_ajax_nopriv_dykfunction_update_text_followup', 'dykfunction_update_text_followup' );


function dykfunction_get_followup_time() {
	
    global $wpdb;

    // FROM INPUT
    $code_id 		= $_POST['datanya'][0];
    $time 			= $_POST['datanya'][1];
    $target 		= $_POST['datanya'][2];
    $campaign_id 	= $_POST['datanya'][3];
    $group_id 		= $_POST['datanya'][4];
    $donatur_status = $_POST['datanya'][5];
    $shedule 		= $_POST['datanya'][6];

    $time 		= $time;

    if($code_id=='1' || $code_id=='2' || $code_id=='3' || $code_id=='4' || $code_id=='5'){
    	ob_clean();
    	echo 'Schedule : '.check_followup_time($time).'__Data : '.get_data_followup($code_id.'_'.$time).' Donatur';
    }else{
    	// Dari code_id table: dyk_custom_followup_scheduler
    	ob_clean();
    	echo 'Schedule : '.check_followup_time($time.'|customscheduler2|'.$shedule).'__Data : '.get_data_followup($code_id.'_customscheduler_'.$time.'_'.$target.'_'.$campaign_id.'_'.$group_id.'_'.$donatur_status).' Donatur';
    }

    
    wp_die();

} 
