function check_followup_time($followup_time_schedule){

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";
    $table_name2 = $wpdb->prefix . "dyk_donate";
    $table_name3 = $wpdb->prefix . "dyk_custom_followup_scheduler";


    $followup_type = 'default';

	if ( strpos($followup_time_schedule, '_') !== false ) {
		$datanya = explode('_',$followup_time_schedule);
	     
	    $followup_type = $datanya[1];

    	if($followup_type=='customscheduler'){
    		
    		$query_custom_followup = $wpdb->get_results('SELECT * from '.$table_name3.' where code_id="'.$datanya[0].'"');

			if($query_custom_followup!=null){
				$followup_time_schedule = $query_custom_followup[0]->date_time; // datetime
				$schedule 				= $query_custom_followup[0]->schedule;
			}
		}

	}

	if ( strpos($followup_time_schedule, '|') !== false ) {
		$datanya = explode('|',$followup_time_schedule);
	    $followup_time_schedule = $datanya[0]; // datetime
	    $followup_type 			= $datanya[1]; // followup_type: customscheduler2
	    $schedule 				= $datanya[2]; // once, daily, weekly
	}



	// *************************
	// FUNCTION FROM HERE
	// *************************
	$date_local_format = get_option( 'date_format' ) . ' ' . get_option( 'time_format' );
    $offset_site = get_date_from_gmt( 'now', 'P' );
    $offset_event = get_date_from_gmt( gmdate( 'Y-m-d H:i:s', strtotime($followup_time_schedule) ), 'P' );

    // If the timezone of the date of the event is different from the site timezone, add a marker.
    if ( $offset_site !== $offset_event ) {
        $date_local_format .= ' (P)';
    }

    $date_utc   = gmdate( 'c', strtotime($followup_time_schedule) );
    $date_local = get_date_from_gmt( gmdate( 'Y-m-d H:i:s', strtotime($followup_time_schedule) ), $date_local_format );

    $time = sprintf(
        '<time datetime="%1$s">%2$s</time>',
        esc_attr( $date_utc ),
        esc_html( $date_local )
    );

    $default_time = $time;
    $remaining_timenya = '';
    $remaining_seconds = strtotime($followup_time_schedule) - time();
    $remaining_seconds2 = $remaining_seconds;


    $diff_days = '';
    if($remaining_seconds<0){

    	// $date = $followup_time_schedule;
		$next_schedule = strtotime($followup_time_schedule);
		$now = current_time('timestamp'); // Gunakan waktu WordPress

		$diff_seconds = $now - $next_schedule;
		$diff_days = ceil($diff_seconds / (60 * 60 * 24)); // floor(), ceil(), dan round()

		// Fungsi Pembulatan  	ke?				Contoh Input	Hasil Output
		// floor()				Bawah			4.9 → 4			4.1 → 4
		// ceil()				Atas			4.1 → 5			4.9 → 5
		// round()				Terdekat		4.4 → 4			4.6 → 5

		if ($diff_days == 1) {
		    // echo "Sudah telat $diff_days days";
		    $diff_days = 'tomorrow';
		}else if ($diff_days >= 1) {
			if($schedule=='weekly'){

				// Hitung jumlah minggu yang dibutuhkan
				$week_count = 0;
				while ($next_schedule < $now) {
				    $next_schedule = strtotime("+1 week", $next_schedule);
				    $week_count++;
				}

				if($week_count<=1){
					$diff_days = $week_count.' week';
				}else{
					$diff_days = $week_count.' weeks';
				}
				
			}else{
				$diff_days = $diff_days.' days';
			}
		    
		} else {
		    $diff_days = 'today';
		}



        $date_local_format = get_option( 'date_format' ) . ' ' . get_option( 'time_format' );
        $offset_site = get_date_from_gmt( 'now', 'P' );
        $offset_event = get_date_from_gmt( gmdate( 'Y-m-d H:i:s', strtotime("$diff_days $followup_time_schedule") ), 'P' );

        // If the timezone of the date of the event is different from the site timezone, add a marker.
        if ( $offset_site !== $offset_event ) {
            $date_local_format .= ' (P)';
        }

        $date_utc   = gmdate( 'c', strtotime("$diff_days $followup_time_schedule") );
        $date_local = get_date_from_gmt( gmdate( 'Y-m-d H:i:s', strtotime("$diff_days $followup_time_schedule") ), $date_local_format );

        $time = sprintf(
            '<time datetime="%1$s">%2$s</time>',
            esc_attr( $date_utc ),
            esc_html( $date_local )
        );

        $remaining_seconds = strtotime("$diff_days $followup_time_schedule") - time();
    	
    	// ***********************
    	// ADDITIONAL CONDITION
    	// Settingan ini khusus get time dari : Custom Follow-Up Scheduler, dimana dia terdapat expired
    	// Klo Daily, ketika dia expired > disetnya langsung ke Tomorrow
    	// ***********************
    	if($followup_type=='customscheduler' || $followup_type=='customscheduler2'){
    		if($schedule=='once'){
    			$remaining_timenya = 'expired'; // klo once, jadi expired
    		}elseif($schedule=='weekly'){
    			$remaining_seconds = strtotime("$diff_days $followup_time_schedule") - time(); // lanjut, jadi 7 hari dikurangi waktu skrg
    		}else{
    			// $schedule=='daily'
    			$remaining_timenya = 'lanjut'; // lanjut, karena dia daily, gak jadi expired
    			$remaining_seconds = strtotime("$diff_days $followup_time_schedule") - time();
    		}
    	}

    	// if($followup_type=='customscheduler2'){
    	// 	$remaining_timenya = 'expired';
    	// 	$remaining_seconds = $emaining_seconds2;
    	// }
    }

    $months = floor($remaining_seconds / (30 * 24 * 3600)); // Anggap 1 bulan = 30 hari
	$remaining_days = floor(($remaining_seconds % (30 * 24 * 3600)) / (24 * 3600));

	$weeks = floor($remaining_days / 7); // Hitung minggu dari sisa hari
	$days = $remaining_days % 7; // Sisa hari setelah dikurangi minggu

	$hours = floor(($remaining_seconds % (24 * 3600)) / 3600);
	$minutes = floor(($remaining_seconds % 3600) / 60);
	$seconds = $remaining_seconds % 60;

	// Singular/Plural Format
	$month_format  = ($months >= 2) ? 'months'  : 'month';
	$week_format   = ($weeks >= 2)  ? 'weeks'   : 'week';
	$day_format    = ($days >= 2)   ? 'days'    : 'day';
	$hour_format   = ($hours >= 2)  ? 'hours'   : 'hour';
	$minute_format = ($minutes >= 2)? 'minutes' : 'minute';
	$second_format = ($seconds >= 2)? 'seconds' : 'second';

    // Menampilkan hasil dengan format yang sesuai
    if ($months > 0) {
        $remaining_time = "( {$months} {$month_format} {$days} {$day_format} )";
    } elseif ($weeks > 0) {
        $remaining_time = "( {$weeks} {$week_format} {$days} {$day_format} )";
    } elseif ($days > 0) {
        $remaining_time = "( {$days} {$day_format} {$hours} {$hour_format} )";
    } elseif ($hours > 0) {
        $remaining_time = "( {$hours} {$hour_format} {$minutes} {$minute_format} )";
    } elseif ($minutes > 0) {
        $remaining_time = "( {$minutes} {$minute_format} {$seconds} {$second_format} )";
    } else {
        $remaining_time = "( {$seconds} {$second_format} )";
    }

    if($remaining_timenya=='expired'){
    	$remaining_time = "(<span style='color:#ef4d56;'> Expired </span>)";
    	return $default_time.' - '.$remaining_time;
    }else{
    	return $time.' - '.$remaining_time;
    }
    

}

// Menghapus semua event dengan nama yang mirip (Pattern Matching)
function delete_all_hooks_by_pattern($pattern) {
    $crons = _get_cron_array();

    if (empty($crons)) {
        error_log("Tidak ada cron event yang terjadwal.");
        return;
    }

    foreach ($crons as $timestamp => $cron_events) {
        foreach ($cron_events as $event_name => $events) {
            if (preg_match($pattern, $event_name)) {
                foreach ($events as $key => $details) {
                    wp_unschedule_event($timestamp, $event_name, $details['args']);
                    error_log("Event dengan pattern dihapus: $event_name pada timestamp $timestamp.");
                }
            }
        }
    }
}


