function run_add_action(){

	for ($i = 1; $i <= 100; $i++) {
        $event_name = 'donasiyuk_f' . $i . '_event_custom';
        // Mendaftarkan function yang sama untuk setiap event_name secara dinamis
        add_action($event_name, 'donasiyuk_custom_followup_function');
        add_action('donasiaja_f' . $i . '_event_custom', 'donasiyuk_custom_followup_function');
    }

    for ($i = 1; $i <= 5; $i++) {
        $event_name = 'donasiyuk_f' . $i . '_event';
        // Mendaftarkan function yang sama untuk setiap event_name secara dinamis
        add_action($event_name, 'donasiyuk_followup_function');
        add_action('donasiaja_f' . $i . '_event', 'donasiyuk_followup_function');
    }

}


function dykfunction_update_automatic_followup() {

    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";
    $table_name2 = $wpdb->prefix . "dyk_custom_followup_scheduler";

    $datanya = json_decode(stripslashes($_POST['datanya']), true); 

    // FROM INPUT
    $automatic_followup_settings 	= $datanya[0]; // $_POST['datanya'][0];
    $daily_followup 				= $datanya[1];
    $custom_followup_scheduler  	= $datanya[2];

    if($automatic_followup_settings==''){
    	$automatic_followup_settings = 0;
    }else{
    	$automatic_followup_settings = 1;
    }

    $daily_followup = str_replace('\\', '', $daily_followup);
    $custom_followup_scheduler  = str_replace('\\', '', $custom_followup_scheduler );

    // ACTION Update TO DB
    $wpdb->update( $table_name, array('data' => $automatic_followup_settings), array('type' => 'automatic_followup_settings'), array('%s'), array('%s') );
    $wpdb->update( $table_name, array('data' => $daily_followup), array('type' => 'daily_followup'), array('%s'), array('%s') );


    // ***************************
    // clear scheduler event custom
    // ***************************
	delete_all_hooks_by_pattern('/^donasiyuk_f\d+_event_custom$/');
	delete_all_hooks_by_pattern('/^donasiyuk_f\d+_event$/');

    // custom scheduler
    $is_empty = (json_decode($custom_followup_scheduler, true) === []); // true jika kosong

	if ($is_empty) {
	    // echo "Data kosong.";
		$wpdb->query("TRUNCATE TABLE $table_name2");
	} else {
	    // echo "Data ada isinya.";

    	$wpdb->query("TRUNCATE TABLE $table_name2"); // clear database
	    $data_json  = json_decode($custom_followup_scheduler , true);
	    $no = 1;
	    foreach ($data_json as $key => $value) {

	    	$current_date = current_time("Y-m-d H:i:s");
            if (strtotime($value[5]) < strtotime($current_date)) {
                $is_first_run = 0;
            }else{
            	$is_first_run = 1;
            }

	    	$wpdb->insert(
	            $table_name2, //table
	            array(
		            'status' 		=> $value[0],
		            'is_first_run' 	=> $is_first_run,
		            'code_id' 		=> $value[1],
		            'name' 			=> $value[2],
		            'schedule' 		=> $value[3],
		            'format' 		=> $value[4],
		            'date_time' 	=> $value[5],
		            'custom_format' => $value[6],
		            'target' 		=> $value[7],
		            'group_id' 		=> $value[8],
		            'campaign_id' 	=> $value[9],
		            'donatur_status'=> $value[10],
		            'broadcast_mode'=> $value[11],
		            'batch_size'	=> $value[12],
		            'send_delay'	=> $value[13],
		            'created_at' 	=> date("Y-m-d H:i:s")
		        ),
	            array('%s', '%s') //data format         
	        );

            $event_name = 'donasiyuk_f'.$no.'_event_custom';

            $time = strtotime($value[5]);
            $current_time = time();

            if ($value[0] === 'on') {

            	// if ($time <= $current_time) {
	            //     $time = strtotime('tomorrow', $current_time) + date('H', $time) * 3600 + date('i', $time) * 60;
	            // }

                // Jadwalkan cron event harian jika belum terjadwal
                if (!wp_next_scheduled($event_name)) {
                	if($value[3]=='once'){
						wp_schedule_single_event( $time, $event_name, array($value[1]) );
                	}else{
                		wp_schedule_event($time, $value[3], $event_name, array($value[1])); //
                	}
                }

            } else {
                // Hapus jadwal cron event jika statusnya off
                $timestamp = wp_next_scheduled($event_name);
                if ($timestamp) {
                    wp_unschedule_event($timestamp, $event_name);
                    error_log("Event dibatalkan: $event_name");
                }
            }
	        

	        $no++;

	    }

	}

    // Jadwalkan cron event
    donasiyuk_schedule_cron_events();
    ob_clean();
	echo 'success';

    wp_die();

} 
