function donasiyuk_schedule_cron_events() {

    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";

    // RACE-CONDITION-FIX (H3): This function runs on every WP request via the 'wp' hook.
    // Two near-simultaneous requests can both pass the wp_next_scheduled() check and
    // double-schedule events. Hold a 30-second transient lock; release on shutdown.
    $lock_key = 'dyk_cron_schedule_lock';
    if ( get_transient( $lock_key ) ) {
        return;
    }
    set_transient( $lock_key, 1, 30 );
    register_shutdown_function( function() use ( $lock_key ) {
        delete_transient( $lock_key );
    } );

    // Ambil pengaturan otomatis dan pengaturan follow-up harian dari database
    $query_settings = $wpdb->get_results(
        "SELECT data FROM $table_name WHERE type IN ('automatic_followup_settings', 'daily_followup') ORDER BY id ASC"
    );

    $automatic_followup_settings = $query_settings[0]->data;
    $daily_followup = json_decode($query_settings[1]->data, true);

    // Cek apakah automatic follow-up diaktifkan
    if ($automatic_followup_settings === '1' && !empty($daily_followup)) {

    	$no = 1;
        foreach ($daily_followup as $key => $value) {

            $event_name = 'donasiyuk_' . $key . '_event'; // Event name seperti donasiyuk_f1_event
            // $time = strtotime('19:57:15');
            $time = strtotime($value[2]);
            $current_time = time();//current_time('timestamp');

            if ($value[0] === 'on') {

            	if ($time <= $current_time) {
	                $time = strtotime('tomorrow', $current_time) + date('H', $time) * 3600 + date('i', $time) * 60;
	            }

                // Jadwalkan cron event harian jika belum terjadwal
                if (!wp_next_scheduled($event_name)) {
                    wp_schedule_event($time, 'daily', $event_name, array($no));
                    error_log("Event terjadwal: $event_name pada " . date('H:i', $time));
                }

            } else {
                // Hapus jadwal cron event jika statusnya off
                $timestamp = wp_next_scheduled($event_name);
                if ($timestamp) {
                    wp_unschedule_event($timestamp, $event_name);
                    error_log("Event dibatalkan: $event_name");
                }
            }
            $no++;
        }
    }
}


// Hook into the 'init' action to schedule our cron event
add_action('wp', 'donasiyuk_schedule_cron_events');



function donasiyuk_custom_followup_function($data) {

	// RACE-CONDITION-FIX (C3+H4): Prevent two concurrent cron runs from double-sending
	// the same followup. Acquire a transient lock; bail if another run is in progress.
	if ( ! empty( $data ) ) {
		$lock_key = 'dyk_custom_followup_lock_' . md5( $data );
		if ( get_transient( $lock_key ) ) {
			return false;
		}
		set_transient( $lock_key, 1, 5 * MINUTE_IN_SECONDS );

		register_shutdown_function( function() use ( $lock_key ) {
			delete_transient( $lock_key );
		} );
	}

	if (!empty($data)) {
		global $wpdb;
        $table_name = $wpdb->prefix . "dyk_custom_followup_scheduler";
        $table_name2 = $wpdb->prefix . "dyk_campaign";
 		$table_name3 = $wpdb->prefix . "dyk_donate";
 		$table_name4 = $wpdb->prefix . "dyk_group_data";
 		$table_name5 = $wpdb->prefix . "dyk_settings";

		// check data settingan scheduler
		$query = $wpdb->get_results('SELECT * from '.$table_name.' where code_id="'.$data.'"');

		if($query!=null){
			
			$time 		 	= $query[0]->date_time;
			$followup_number= $query[0]->format; // followup 1 s.d 5, dan 6 = custom
			$message 	 	= $query[0]->custom_format; // custom format message
			$target 	 	= $query[0]->target; // campaign, group, manual
			$group_id 	 	= $query[0]->group_id;
			$campaign_id 	= $query[0]->campaign_id;
			$donatur_status = $query[0]->donatur_status; // all, waiting, success
			$is_first_run 	= $query[0]->is_first_run; // Ambil status eksekusi pertama

			$broadcast_mode = $query[0]->broadcast_mode;
			$batch_size 	= $query[0]->batch_size;
			$send_delay 	= $query[0]->send_delay;

            // Ambil tanggal hari ini
            $current_date = current_time("Y-m-d H:i:s");

            // $info = '';
            // Jika ini pertama kali dijalankan dan start_date sudah lewat, jangan eksekusi WA
            if ($is_first_run == 0 && strtotime($time) < strtotime($current_date)) {

                // Update agar is_first_run menjadi 0 supaya bisa dieksekusi di masa depan
                $a = $wpdb->update(
			        $table_name,
			        array(
			            'is_first_run' 	 => 1
			        ), array('code_id' => $query[0]->code_id), array('%s'), array('%s')
			    );

			    if ($a === false) {
				    // Jika terjadi error
				    // $info = "Gagal update is_first_run untuk code_id: " . $query[0]->code_id;
				} elseif ($a === 0) {
				    // Jika tidak ada baris yang terupdate (misalnya nilai sudah 1 sebelumnya)
				    // $info = "Tidak ada perubahan pada is_first_run untuk code_id: " . $query[0]->code_id;
				} else {
				    // Jika berhasil update (1 atau lebih baris diperbarui)
				    // $info = "Berhasil update is_first_run untuk code_id: " . $query[0]->code_id;
