						    $text_f4 = $query_settings[3]->data;
						    $text_f5 = $query_settings[4]->data;

						    if($followup_number=='1'){
						    	$message = $text_f1;
						    }elseif($followup_number=='2'){
						    	$message = $text_f2;
						    }elseif($followup_number=='3'){
						    	$message = $text_f3;
						    }elseif($followup_number=='4'){
						    	$message = $text_f4;
						    }else{
						    	$message = $text_f5;
						    }

						    $data_field = array();
						    $data_field[ '{name}' ] 	= $row->name;
