	}

    // $followup_number = $data;

    if($target=='campaign'){ // yang target: di "campaign". gak pakai filter date

    	$query_donate = $wpdb->get_results("SELECT id from $table_name2 where $campaignnya ");

    }elseif($target=='group'){ // yang target: di "group". gak pakai filter date

    	$query_donate = $wpdb->get_results("SELECT id from $table_name4 where $groupnya ");

    }else{

    	// $filter_datestart_now = date("Y-m-d $time");
	    // $filter_datestart_before = date("Y-m-d $time", strtotime($filter_datestart_now. ' - '.$followup_number.' days'));

    	// if($followup_number=='1'){
	    // 	$query_donate = $wpdb->get_results("SELECT id from $table_name2 where (f1 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
		// }elseif($followup_number=='2'){
	    // 	$query_donate = $wpdb->get_results("SELECT id from $table_name2 where (f1 IS NOT NULL AND f2 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
		// }elseif($followup_number=='3'){
	    // 	$query_donate = $wpdb->get_results("SELECT id from $table_name2 where (f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
		// }elseif($followup_number=='4'){
	    // 	$query_donate = $wpdb->get_results("SELECT id from $table_name2 where (f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NOT NULL AND f4 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
		// }else{
	    // 	$query_donate = $wpdb->get_results("SELECT id from $table_name2 where (f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NOT NULL AND f4 IS NOT NULL AND f5 IS NULL) and status='0' and created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now' ");
		// }

		$now = strtotime(date("Y-m-d $time"));
		$filter_datestart_before = date("Y-m-d H:i:s", strtotime("-$followup_number days", $now));
		$filter_datestart_now    = date("Y-m-d H:i:s", strtotime("-" . ($followup_number - 1) . " days", $now));

		if ($followup_number == '1') {
		    $query_donate = $wpdb->get_results("SELECT id FROM $table_name2 WHERE f1 IS NULL AND status='0' AND created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now'");
		} elseif ($followup_number == '2') {
		    $query_donate = $wpdb->get_results("SELECT id FROM $table_name2 WHERE f1 IS NOT NULL AND f2 IS NULL AND status='0' AND created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now'");
		} elseif ($followup_number == '3') {
		    $query_donate = $wpdb->get_results("SELECT id FROM $table_name2 WHERE f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NULL AND status='0' AND created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now'");
		} elseif ($followup_number == '4') {
