		} else {
		    $query_donate = $wpdb->get_results("SELECT id FROM $table_name2 WHERE f1 IS NOT NULL AND f2 IS NOT NULL AND f3 IS NOT NULL AND f4 IS NOT NULL AND f5 IS NULL AND status='0' AND created_at BETWEEN '$filter_datestart_before' AND '$filter_datestart_now'");
		}


    }
    
    return count($query_donate);
	
}



function donate_expired_time($donasi_id,$payment_gateway){

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_payment_log";

	if($payment_gateway=='tripay'){
    	$payment_log = $wpdb->get_results('SELECT * from '.$table_name.' where id_donate="'.$donasi_id.'"');
	    if($payment_log!=null){
	        $hasil = $payment_log[0]->log;
	        $data_log = json_decode($hasil);
	        
	        if(isset($data_log->data->expired_time)){
	        	$expired_time = $data_log->data->expired_time;
		        $expired_time = date('d M Y - H:i', $expired_time);
		        return $expired_time;
	        }else{
	        	return '';
	        }
	    }else{
	    	return '';
	    }
    }elseif($payment_gateway=='midtrans'){
    	$payment_log = $wpdb->get_results('SELECT * from '.$table_name.' where id_donate="'.$donasi_id.'"');
	    if($payment_log!=null){
	        $hasil = $payment_log[0]->log;
	        $data_log = json_decode($hasil);
	        if(isset($data_log->expiry_time)){
                $expired_time = $data_log->expiry_time;
                $expired_time = strtotime($expired_time);
                $expired_time = date('d M Y - H:i', $expired_time);
                return $expired_time;
            }else{
            	return '';
            }
	    }else{
	    	return '';
	    }
    }elseif($payment_gateway=='ipaymu'){
    	$payment_log = $wpdb->get_results('SELECT * from '.$table_name.' where id_donate="'.$donasi_id.'"');
	    if($payment_log!=null){
	        $hasil = $payment_log[0]->log;
	        $data_log = json_decode($hasil);
	        if(isset($data_log->Data->Expired)){
	            $expired_time = $data_log->Data->Expired;
	            $expired_time = strtotime($expired_time);
	            $expired_time = date('d M Y - H:i', $expired_time);
	            return $expired_time;
	        }else{
	        	return '';
	        }
	    }else{
	    	return '';
	    }
    }else{
    	// nothing
    	return '';
    }
}

function dykfunction_send_wa($datanya){
	global $wpdb;
    $table_name  = $wpdb->prefix . "dyk_settings";
    $table_name2 = $wpdb->prefix . "dyk_donate";
    $table_name3 = $wpdb->prefix . "dyk_campaign";
    $table_name4 = $wpdb->prefix . "dyk_aff_submit";
    $table_name5 = $wpdb->prefix . "dyk_aff_code";
    $table_name6 = $wpdb->prefix . "dyk_payment_log";

    
    $followup_message = '';
    $action = 'ajax';

    if (!empty($datanya)) {

    	$donasi_id = $datanya[0];
    	$followup_number = $datanya[1]; // 6
    	$followup_message = $datanya[2]; // followup_onetofive || null
    	$action = 'bg_service';

    }else{
    	// FROM INPUT
	    $donasi_id 			= $_POST['datanya'][0];
	    $followup_number 	= $_POST['datanya'][1];
    }
    

    // GET SETTINGS
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="text_f1" or type="text_f2" or type="text_f3" or type="text_f4" or type="text_f5" or type="currency" or type="wanotif_url" or type="wanotif_apikey" or type="wanotif_on_dashboard" or type="wanotif_on" or type="midtrans_serverkey" or type="midtrans_serverkey_sandbox" or type="wanotif_apikey_cs" ORDER BY id ASC');
    $text_f1 = $query_settings[0]->data;
    $text_f2 = $query_settings[1]->data;
    $text_f3 = $query_settings[2]->data;
    $text_f4 = $query_settings[3]->data;
    $text_f5 = $query_settings[4]->data;
    $currency = $query_settings[5]->data;
    $wanotif_url 		  = $query_settings[6]->data;
    $wanotif_apikey 	  = dyk_decrypt_secret($query_settings[7]->data);
    $wanotif_on_dashboard = $query_settings[8]->data;
    $wanotif_on 		  = $query_settings[9]->data;
    $midtrans_serverkey   = dyk_decrypt_secret($query_settings[10]->data);
    $midtrans_serverkey_sandbox = dyk_decrypt_secret($query_settings[11]->data);
    $wanotif_apikey_cs 	  = $query_settings[12]->data;


    if($followup_number=='1'){
    	$text_wa = $text_f1;
    }elseif($followup_number=='2'){
    	$text_wa = $text_f2;
    }elseif($followup_number=='3'){
    	$text_wa = $text_f3;
    }elseif($followup_number=='4'){
    	$text_wa = $text_f4;
    }else{
    	$text_wa = $text_f5;
    }

    // set text message berdasarkan settingan custom message
    if($followup_number=='6'){
    	$text_wa = $followup_message;
    }
	
	// GET DATA DONASI
    $row = $wpdb->get_results('SELECT a.*, b.title, b.slug from '.$table_name2.' a 
    left JOIN '.$table_name3.' b ON b.campaign_id = a.campaign_id where a.id="'.$donasi_id.'" ')[0];


    // GET DATA CAMPAIGN
    $campaign_id = $row->campaign_id;
    $query_campaign = $wpdb->get_results('SELECT followup_status, followup_text, user_id from '.$table_name3.' 
    where campaign_id="'.$campaign_id.'" ');

    // SET TEXT FOLLOWUP BERDASARKAN CUSTOM MULTIPLE FOLLOWUP CAMPAIGN FORMAT
    if (!empty($query_campaign) && isset($query_campaign[0]->followup_status, $query_campaign[0]->followup_text)) {

	    $followup_status = $query_campaign[0]->followup_status;
	    $followup_text = $query_campaign[0]->followup_text;

	    $data_json_followup = json_decode($followup_text, true);
	    $followup_text1 = '';
	    $followup_text2 = '';
	    $followup_text3 = '';
	    $followup_text4 = '';
	    $followup_text5 = '';
	    if (isset($data_json_followup['data'][0])) {
		    $followup_text1 = $data_json_followup['data'][0]['message'];
		}
		if (isset($data_json_followup['data'][1])) {
		    $followup_text2 = $data_json_followup['data'][1]['message'];
		}
		if (isset($data_json_followup['data'][2])) {
		    $followup_text3 = $data_json_followup['data'][2]['message'];
		}
		if (isset($data_json_followup['data'][3])) {
		    $followup_text4 = $data_json_followup['data'][3]['message'];
		}
		if (isset($data_json_followup['data'][4])) {
		    $followup_text5 = $data_json_followup['data'][4]['message'];
		}

		if($followup_status=='1'){
			if($followup_number=='1'){
		    	$text_wa = urldecode($followup_text1);
		    }elseif($followup_number=='2'){
		    	$text_wa = urldecode($followup_text2);
		    }elseif($followup_number=='3'){
		    	$text_wa = urldecode($followup_text3);
		    }elseif($followup_number=='4'){
		    	$text_wa = urldecode($followup_text4);
		    }else{
		    	$text_wa = urldecode($followup_text5);
		    }
		}
	}

    // set cs_name
    $cs_name = '';
    if($row->cs_id>=1){
    	$user_info_cs = get_userdata($row->cs_id);
	    if($user_info_cs!=null){
	    	if($user_info_cs->last_name==''){
		    	$cs_name = $user_info_cs->first_name;
		    }else{
