			$response = curl_exec($curl);
			curl_close($curl); 

			$array = json_decode( $response, true );
			$data = $array['wanotif']['status'];

			if($data=='sent'){
				ob_clean();
				echo 'success';
			}else{
				ob_clean();
				echo 'failed';
			}

		}else{

			// send with wanotif
			$url = $wanotif_url.'/send';
			$messagenya = $message;
			$messagenya = str_replace("&#39;", "'", $messagenya);
			$messagenya = str_replace("{hide_qr}", "", $messagenya);

