function generateQrisBase64($data) {
    // Gunakan API lokal (phpqrcode logic via QR Code generator)
    // Jika tidak ada phpqrcode, gunakan ekstensi GD bawaan PHP
    if (!extension_loaded('gd')) {
        die("GD extension belum aktif di server PHP kamu.");
    }

    $size = 300;
    $margin = 2;

    // gunakan API publik untuk QR builder agar ringan
    $url = "https://api.qrserver.com/v1/create-qr-code/?size={$size}x{$size}&margin={$margin}&data=" . urlencode($data);

    // Ambil data QR dalam bentuk biner
    $imgData = file_get_contents($url);
    if (!$imgData) {
        die("Gagal membuat QR image dari API ".$url);
    }

    // Encode ke base64
    return 'data:image/png;base64,' . base64_encode($imgData);
}


function dykfunction_send_wa2($datanya){
	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";
    $table_name2 = $wpdb->prefix . "dyk_donate";
    $table_name3 = $wpdb->prefix . "dyk_campaign";
    $table_name4 = $wpdb->prefix . "users";
    $table_name7 = $wpdb->prefix . "dyk_users";

    $action = 'ajax';
    if (!empty($datanya)) {
    	// FROM function
    	$message = $datanya[0];
    	$whatsapp_number = $datanya[1];
    	$action = 'bg_service';
    }else{
	    // FROM INPUT
	    $message 			= $_POST['datanya'][0];
	    $whatsapp_number 	= $_POST['datanya'][1];
    }


    // GET SETTINGS
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="text_f1" or type="text_f2" or type="text_f3" or type="text_f4" or type="text_f5" or type="currency" or type="wanotif_url" or type="wanotif_apikey" or type="wanotif_on_dashboard" or type="wanotif_on" or type="wanotif_apikey_cs" ORDER BY id ASC');
    $text_f1 = $query_settings[0]->data;
    $text_f2 = $query_settings[1]->data;
    $text_f3 = $query_settings[2]->data;
    $text_f4 = $query_settings[3]->data;
    $text_f5 = $query_settings[4]->data;
    $currency = $query_settings[5]->data;
    $wanotif_url 		  = $query_settings[6]->data;
    $wanotif_apikey 	  = dyk_decrypt_secret($query_settings[7]->data);
    $wanotif_on_dashboard = $query_settings[8]->data;
    $wanotif_on 		  = $query_settings[9]->data;
    $wanotif_apikey_cs 	  = $query_settings[10]->data;

	// GET DATA DONASI
    $row = $wpdb->get_results('SELECT count(id) as jumlah_donasi, sum(nominal) as total from '.$table_name2.' where whatsapp = "'.$whatsapp_number.'" and status="1" ')[0];

	$formatted_wa = djaPhoneFormat($whatsapp_number, $currency);
	$check_user_bywa2 = $wpdb->get_results("SELECT user_id FROM $table_name7 where user_wa='$formatted_wa' ");
	if($check_user_bywa2!=null){
		$id_login = $check_user_bywa2[0]->user_id;
	}else{
		$id_login = wp_get_current_user()->ID;
	}

	$id_login = wp_get_current_user()->ID;
    $user = get_user_by( 'ID', $id_login );
    $display_name = $user->display_name;

    $data_field = array();
    $data_field[ '{name}' ] 	= $display_name;
    $data_field[ '{jumlah}' ] 	= $row->jumlah_donasi;

    if($currency=='IDR'){
    	$data_field[ '{total}' ] 	= 'Rp '.number_format_currency($row->total);
    }elseif($currency=='MYR'){
    	$data_field[ '{total}' ] 	= 'RM '.number_format_currency($row->total);
    }else{
    	$data_field[ '{total}' ] 	= $row->total;
    }

    if($message==''){
    	$message = "Terimakasih {name}, anda sudah berdonasi sebanyak {jumlah} kali dengan total donasi {total}";
    }

    $message = strtr($message, $data_field);
	$messagenya = dyk_whatsapp_format($message);
	$messagenya = str_replace("\\", '', $messagenya);
	$messagenya = str_replace("&#39;", "'", $messagenya);
	$messagenya = strip_tags($messagenya ?? '');

    $phone = djaPhoneFormat($whatsapp_number,$currency);

	if($wanotif_apikey!='' && $wanotif_on=='1'){

		// send with wanotif
		$url = $wanotif_url.'/send';
		$messagenya = $message;
		$messagenya = str_replace("&#39;", "'", $messagenya);

		$curl = curl_init();
		curl_setopt($curl, CURLOPT_URL, $url);
		curl_setopt($curl, CURLOPT_HEADER, 0);
		curl_setopt($curl, CURLOPT_RETURNTRANSFER, 1);
		curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 2);
		curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
		curl_setopt($curl, CURLOPT_TIMEOUT,30);
		curl_setopt($curl, CURLOPT_POST, 1);
		curl_setopt($curl, CURLOPT_POSTFIELDS, array(
		    'Apikey'    => $wanotif_apikey,
		    'Phone'     => $phone,
		    'Message'   => $messagenya,
		));
		$response = curl_exec($curl);
		curl_close($curl);

		$array = json_decode( $response, true );
		$data = $array['wanotif']['status'];

		if($data=='sent'){
			ob_clean();
			echo 'success';
		}else{
			ob_clean();
			echo 'failed';
		}


    }

    if($action=='ajax'){
    	wp_die();
    }

} 
