function dykfunction_update_name_whatsapp() {
	
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_users";
    $table_name2 = $wpdb->prefix . "usermeta";
    $table_name3 = $wpdb->prefix . "dyk_verification_details";  
    $table_name4 = $wpdb->prefix . "users";
    // $table_name5 = $wpdb->prefix . "dyk_settings";    
    
    // FROM INPUT
    $user_id 	    = wp_get_current_user()->ID;
    $user_fullname  = wp_strip_all_tags($_POST['datanya'][0]);
    $user_wa 		= wp_strip_all_tags($_POST['datanya'][1]);

    $fullname = trim($user_fullname);
	$parts    = preg_split('/\s+/', $fullname);

	$user_firstname = array_shift($parts);          // ambil & buang elemen pertama
	$user_lastname  = implode(' ', $parts); 

    $check = $wpdb->get_results('SELECT id from '.$table_name.' where user_id="'.$user_id.'"');
	if($check!=null){

	    // ACTION Update TO DB
	    $wpdb->update(
            $table_name, //table
            array(
	            'user_wa' => $user_wa
	        ),
            array('user_id' => $user_id), //where
            array('%s'), //data format
            array('%s') //where format    
        );

	    $user_firstname_update = str_replace('\\', '', $user_firstname);
	    $user_lastname_update = str_replace('\\', '', $user_lastname);

        // ACTION Update TO DB
	    $wpdb->update(
            $table_name2, //table
            array(
	            'meta_value' => $user_firstname_update,
	        ),
            array('user_id' => $user_id, 'meta_key' => 'first_name' ), //where
            array('%s'), //data format
            array('%s') //where format    
        );
	    $wpdb->update(
            $table_name2, //table
            array(
	            'meta_value' => $user_lastname_update,
	        ),
            array('user_id' => $user_id, 'meta_key' => 'last_name' ), //where
            array('%s'), //data format
            array('%s') //where format    
        );

	    $wpdb->update(
            $table_name4, //table
            array(
	            'display_name' => $user_firstname_update.' '.$user_lastname_update,
	        ),
            array('ID' => $user_id), //where
            array('%s'), //data format
            array('%s') //where format    
        );

		ob_clean();
        echo 'success';

	}


    wp_die();

} 
