function dykfunction_verify_user() {
	
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_users";
    $table_name2 = $wpdb->prefix . "usermeta";
    $table_name3 = $wpdb->prefix . "dyk_verification_details";  
    $table_name4 = $wpdb->prefix . "users";
    $table_name5 = $wpdb->prefix . "dyk_settings";    
    
    // FROM INPUT
    $action_verify = $_POST['datanya'][0];
    $user_id 	   = $_POST['datanya'][1];
    $status_verification = $_POST['datanya'][2];

    // get email settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name5.' where type="email_on" ORDER BY id ASC');
    $email_on 		  = $query_settings[0]->data;

    $check = $wpdb->get_results('SELECT id, user_verification from '.$table_name.' where user_id="'.$user_id.'"');
	if($check!=null && $action_verify=='single'){

	    // ACTION Update TO DB
	    $wpdb->update(
            $table_name, //table
            array(
	            'user_verification' => $status_verification,
	        ),
            array('user_id' => $user_id), //where
            array('%s'), //data format
            array('%s') //where format    
        );

        // ACTION Update TO DB
	   

	    if($email_on=='1'){
	    	$user_data = get_userdata($user_id);
	    	$user_email = ($user_data && isset($user_data->user_email)) ? $user_data->user_email : '';

	        if($check[0]->user_verification=='2' && $status_verification=='1'){

				$message = '<p>Akun anda dengan email '.$user_email.' berhasil kami verifikasi.<br>Selamat menggunakan layanan kami.</p>';
