function sanitize_text_field2( $str ) {
    $filtered = wp_check_invalid_utf8( $str );
    $filtered = preg_replace('/<[^>]*>/', '', $filtered); // hapus semua tag HTML
    $filtered = trim( $filtered );
    return $filtered;
}


function dykfunction_update_profile() {
	
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_users";
    $table_name2 = $wpdb->prefix . "usermeta";
    $table_name3 = $wpdb->prefix . "users";

    $id_login = wp_get_current_user()->ID;
    
    // FROM INPUT
    $user_id 		= wp_strip_all_tags($_POST['datanya'][0]);
    $first_name 	= wp_strip_all_tags($_POST['datanya'][1]);
    $last_name 		= wp_strip_all_tags($_POST['datanya'][2]);
    $user_bio 		= wp_strip_all_tags($_POST['datanya'][3]);
    $user_alamat 	= wp_strip_all_tags($_POST['datanya'][4]);
    $user_provinsi 	= wp_strip_all_tags($_POST['datanya'][5]);
    $user_kabkota 	= wp_strip_all_tags($_POST['datanya'][6]);
    $user_kecamatan 	= wp_strip_all_tags($_POST['datanya'][7]);
    $user_provinsi_id 	= wp_strip_all_tags($_POST['datanya'][8]);
    $user_kabkota_id 	= wp_strip_all_tags($_POST['datanya'][9]);
    $user_kecamatan_id 	= wp_strip_all_tags($_POST['datanya'][10]);
    $user_sapaan 		= wp_strip_all_tags($_POST['datanya'][11]);

    if($last_name==''){
    	$full_name = $first_name;
    }else{
    	$full_name = $first_name.' '.$last_name;
    }

    $fullname = str_replace('\\', '', $full_name);

    if($id_login==$user_id){

		    // ACTION Update TO DB
		    $wpdb->update(
	            $table_name, //table
	            array(
		            'user_bio' 			=> $user_bio,
		            'user_provinsi' 	=> $user_provinsi,
		            'user_kabkota' 		=> $user_kabkota,
		            'user_kecamatan' 	=> $user_kecamatan,
		            'user_provinsi_id' 	=> $user_provinsi_id,
		            'user_kabkota_id' 	=> $user_kabkota_id,
		            'user_kecamatan_id' => $user_kecamatan_id,
		            'user_alamat' 		=> $user_alamat,
		            'user_sapaan' 		=> $user_sapaan
		        ),
	            array('user_id' => $user_id), //where
	            array('%s'), //data format
	            array('%s') //where format    
	        );

	        // ACTION Update TO DB
		    $wpdb->update(
	            $table_name2, //table
	            array(
		            'meta_value' => str_replace('\\', '', $first_name),
		        ),
	            array('user_id' => $user_id, 'meta_key' => 'first_name' ), //where
	            array('%s'), //data format
	            array('%s') //where format    
	        );
		    $wpdb->update(
	            $table_name2, //table
	            array(
		            'meta_value' => str_replace('\\', '', $last_name),
		        ),
	            array('user_id' => $user_id, 'meta_key' => 'last_name' ), //where
	            array('%s'), //data format
	            array('%s') //where format    
	        );
		    $wpdb->update(
	            $table_name3, //table
	            array(
		            'display_name' => str_replace('\\', '', $full_name),
		        ),
	            array('ID' => $user_id), //where
	            array('%s'), //data format
	            array('%s') //where format    
	        );
			
			ob_clean();
			echo 'success';

    }else{
    	ob_clean();
    	echo 'Not allowed.';
    }


    wp_die();

} 
add_action( 'wp_ajax_dykfunction_update_profile', 'dykfunction_update_profile' );
add_action( 'wp_ajax_nopriv_dykfunction_update_profile', 'dykfunction_update_profile' );




