function generate_kode_unik($min, $max){
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";
    $table_name2 = $wpdb->prefix . "dyk_donate";

    // Ambil kode unik yang sudah dipakai dalam 2 hari terakhir
    $used_codes = $wpdb->get_col("
        SELECT DISTINCT unique_number 
        FROM {$table_name2}
        WHERE created_at >= DATE_SUB(NOW(), INTERVAL 2 DAY)
          AND unique_number IS NOT NULL
          AND unique_number != ''
    ");

    if(!is_array($used_codes)){
        $used_codes = [];
    }

    // Hitung total kemungkinan kode
    $total_range = ($max - $min) + 1;

    // Jika semua kemungkinan sudah dipakai ➜ fallback random
    if(count($used_codes) >= $total_range){
        return rand($min, $max);
    }

    // Jika belum habis ➜ generate sampai dapat kode yang belum dipakai
    $attempt = 0;
    do {
        $kode_unik = rand($min, $max);
        $attempt++;

        // backup safety (tapi ini jarang sekali terjadi)
        if($attempt > 2000){
            return rand($min, $max); // fallback ekstra
        }

    } while(in_array($kode_unik, $used_codes));

    return $kode_unik;

}

