function dykfunction_update_duitku_settings() {
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";

    $id_login = wp_get_current_user()->ID;

    if (!empty($id_login)) {
        $duitku_mode             = isset($_POST['datanya'][0]) ? sanitize_text_field($_POST['datanya'][0]) : '0';
        $duitku_merchant         = isset($_POST['datanya'][1]) ? sanitize_text_field($_POST['datanya'][1]) : '';
        $duitku_apikey           = isset($_POST['datanya'][2]) ? dyk_encrypt_secret(sanitize_text_field($_POST['datanya'][2])) : '';
        $duitku_merchant_sandbox = isset($_POST['datanya'][3]) ? sanitize_text_field($_POST['datanya'][3]) : '';
        $duitku_apikey_sandbox   = isset($_POST['datanya'][4]) ? dyk_encrypt_secret(sanitize_text_field($_POST['datanya'][4])) : '';
        $duitku_expiry_period    = isset($_POST['datanya'][5]) ? sanitize_text_field($_POST['datanya'][5]) : '1440';
        $duitku_qris_type        = isset($_POST['datanya'][6]) ? sanitize_text_field($_POST['datanya'][6]) : 'SP';

        $settings = [
            'duitku_mode'             => $duitku_mode,
            'duitku_merchant'         => $duitku_merchant,
            'duitku_apikey'           => $duitku_apikey,
            'duitku_merchant_sandbox' => $duitku_merchant_sandbox,
            'duitku_apikey_sandbox'   => $duitku_apikey_sandbox,
            'duitku_expiry_period'    => $duitku_expiry_period,
            'duitku_qris_type'        => $duitku_qris_type
        ];

        foreach ($settings as $key => $val) {
            $exists = $wpdb->get_var($wpdb->prepare("SELECT id FROM {$table_name} WHERE type = %s", $key));
            if ($exists) {
                $wpdb->update($table_name, ['data' => $val], ['type' => $key]);
            } else {
                $wpdb->insert($table_name, ['type' => $key, 'data' => $val]);
            }
        }

        ob_clean();
        echo 'success';
    } else {
        ob_clean();
        echo 'Not allowed.';
    }

    wp_die();
}
add_action( 'wp_ajax_dykfunction_update_duitku_settings', 'dykfunction_update_duitku_settings' );
add_action( 'wp_ajax_nopriv_dykfunction_update_duitku_settings', 'dykfunction_update_duitku_settings' );


