// Load Data Donatur Only
function dykfunction_load_data_donatur() {
	
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";
    $table_name2 = $wpdb->prefix . "dyk_love";
    $table_name3 = $wpdb->prefix . "dyk_campaign";
    
    $id = isset($_POST['datanya'][0]) ? sanitize_text_field($_POST['datanya'][0]) : '';
    $campaign_id = isset($_POST['datanya'][1]) ? sanitize_text_field($_POST['datanya'][1]) : '';
    $load_count = isset($_POST['datanya'][2]) ? intval($_POST['datanya'][2]) : 2;
    $anonim_text = isset($_POST['datanya'][3]) ? sanitize_text_field($_POST['datanya'][3]) : 'Orang Baik';
    $fullanonim = isset($_POST['datanya'][4]) ? sanitize_text_field($_POST['datanya'][4]) : '';
    $act = isset($_POST['datanya'][5]) ? sanitize_text_field($_POST['datanya'][5]) : '';
    
    if ($load_count < 2) {
        $load_count = 2;
    }
    $start = 5 + ($load_count - 2) * 10;
    $limit = 10;

    $campaign_row = $wpdb->get_row($wpdb->prepare("SELECT * FROM $table_name3 WHERE campaign_id = %s", $campaign_id));
    $general_status = $campaign_row->general_status ?? '';
    $allocation_title = $campaign_row->allocation_title ?? '';
    $allocation_others_title = $campaign_row->allocation_others_title ?? '';

    if($general_status=='1'){
        if($allocation_title=='1' || $allocation_title=='0'){
            $allocation_title = 'Donasi';
        }elseif($allocation_title=='2'){
            $allocation_title = 'Zakat';
        }elseif($allocation_title=='3'){
            $allocation_title = 'Qurban';
        }elseif($allocation_title=='4'){
            $allocation_title = 'Infaq';
        }elseif($allocation_title=='5'){
            $allocation_title = 'Wakaf';
        }else{
            $allocation_title = $allocation_others_title ?: 'Donasi';
        }
    }else{
        $allocation_title = 'Donasi';
    }

    if($campaign_id!=''){
  		
  		if($act=='terbesar'){
  			$donation_paid = $wpdb->get_results($wpdb->prepare("SELECT * FROM $table_name WHERE campaign_id = %s AND status = '1' ORDER BY nominal DESC LIMIT %d, %d", $campaign_id, $start, $limit));
  		}else{
  			$donation_paid = $wpdb->get_results($wpdb->prepare("SELECT * FROM $table_name WHERE campaign_id = %s AND status = '1' ORDER BY id DESC LIMIT %d, %d", $campaign_id, $start, $limit));
  		}
		
		$the_data = '';
		if (!empty($donation_paid) && is_array($donation_paid)) {
			foreach ($donation_paid as $value) {
				$donatur_name = $value->name;
				if($value->anonim=='1'){
					$donatur_name = $anonim_text;
				}
				$donatur_name = wp_strip_all_tags($donatur_name);

				// time
				$readtime = new donasiyuk_readtime();
				$fix_time = $readtime->time_donation($value->created_at);

				// nominal
				$nominal = 'Rp '.number_format($value->nominal,0,",",".");

	        	$the_data .= '
		        <div class="donation_inner_box" style="background:rgb(250, 252, 255);">
		            <div class="donation_name">'.$donatur_name.'<span class="donation_time"><span class="dashicons dashicons-clock"></span>'.$fix_time.'</span>
		            </div>
		            <div class="donation_total">Ber'.strtolower($allocation_title).' sebesar <b>'.$nominal.'</b></div>    	
		        </div>
		        ';
			}
		}

		echo $the_data;

  	}

    wp_die();

} 
add_action( 'wp_ajax_dykfunction_load_data_donatur', 'dykfunction_load_data_donatur' );
add_action( 'wp_ajax_nopriv_dykfunction_load_data_donatur', 'dykfunction_load_data_donatur' );



// Load Data Donatur and Comment
function dykfunction_load_list_donatur() {
	
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";
    $table_name2 = $wpdb->prefix . "dyk_love";
    $table_name3 = $wpdb->prefix . "dyk_campaign";

    $id = isset($_POST['datanya'][0]) ? sanitize_text_field($_POST['datanya'][0]) : '';
    $campaign_id = isset($_POST['datanya'][1]) ? sanitize_text_field($_POST['datanya'][1]) : '';
    $load_count = isset($_POST['datanya'][2]) ? intval($_POST['datanya'][2]) : 2;
    $anonim_text = isset($_POST['datanya'][3]) ? sanitize_text_field($_POST['datanya'][3]) : 'Orang Baik';
    $fullanonim = isset($_POST['datanya'][4]) ? sanitize_text_field($_POST['datanya'][4]) : '';
    
    if ($load_count < 2) {
        $load_count = 2;
    }
    $start = 5 + ($load_count - 2) * 10;
    $limit = 10;

    // Campaign Settings
    if($campaign_id=='all'){
    	$value = $wpdb->get_row("SELECT * FROM $table_name3 LIMIT 1");
    	$donation_paid = $wpdb->get_results($wpdb->prepare("SELECT * FROM $table_name WHERE status='1' ORDER BY id DESC LIMIT %d, %d", $start, $limit));
    }else{
    	$value = $wpdb->get_row($wpdb->prepare("SELECT * FROM $table_name3 WHERE campaign_id = %s", $campaign_id));
    	$donation_paid = $wpdb->get_results($wpdb->prepare("SELECT * FROM $table_name WHERE campaign_id = %s AND status='1' ORDER BY id DESC LIMIT %d, %d", $campaign_id, $start, $limit));
    }

	$the_data = '';

	if (!empty($donation_paid) && is_array($donation_paid)) {
		foreach ($donation_paid as $data) {

			$readtime = new donasiyuk_readtime();
			$donation_time = $readtime->time_donation($data->created_at);

			$general_status = $value->general_status ?? '';
		    $allocation_title = $value->allocation_title ?? '';
		    $allocation_others_title = $value->allocation_others_title ?? '';

		    if($general_status=='1'){
		        if($allocation_title=='1' || $allocation_title=='0'){
		            $allocation_title = 'Donasi';
		        }elseif($allocation_title=='2'){
		            $allocation_title = 'Zakat';
		        }elseif($allocation_title=='3'){
		            $allocation_title = 'Qurban';
		        }elseif($allocation_title=='4'){
		            $allocation_title = 'Infaq';
		        }elseif($allocation_title=='5'){
		            $allocation_title = 'Wakaf';
		        }else{
		            $allocation_title = $allocation_others_title ?: 'Donasi';
		        }
		    }else{
		        $allocation_title = 'Donasi';
		    }

		    $donatur_name = $data->name;
			if($data->anonim=='1'){
				$donatur_name = $anonim_text;
			}
			$donatur_name = wp_strip_all_tags($donatur_name);

			$the_data .= '
			        <div class="donation_inner_box" style="background:#ffffff;">
			            <div class="donation_name">'.$donatur_name.'<span class="donation_time"><span class="dashicons dashicons-clock"></span>'.$donation_time.'</span>
			            </div>
			            <div class="donation_total" style="color: #23374d;font-weight:normal;">'.$allocation_title.' <b>Rp '.number_format($data->nominal,0,",",".").'</b></div>
			            <div class="donation_comment">'.str_replace('\\', '', $data->comment).'</div>
			        </div>
			';
		}
	}

	echo $the_data;

    wp_die();

} 
add_action( 'wp_ajax_dykfunction_load_list_donatur', 'dykfunction_load_list_donatur' );
add_action( 'wp_ajax_nopriv_dykfunction_load_list_donatur', 'dykfunction_load_list_donatur' );




// LOAD FUNDRAISER
function dykfunction_load_fundraiser() {
	
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";
    $table_name2 = $wpdb->prefix . "dyk_aff_code";
    $table_name3 = $wpdb->prefix . "dyk_aff_submit";
    $table_name4 = $wpdb->prefix . "users";
    $table_name5 = $wpdb->prefix . "dyk_settings";
    
    $id = isset($_POST['datanya'][0]) ? sanitize_text_field($_POST['datanya'][0]) : '';
    $campaign_id = isset($_POST['datanya'][1]) ? sanitize_text_field($_POST['datanya'][1]) : '';
    $load_count = isset($_POST['datanya'][2]) ? intval($_POST['datanya'][2]) : 2;
    $anonim_text = isset($_POST['datanya'][3]) ? sanitize_text_field($_POST['datanya'][3]) : 'Orang Baik';
    $fullanonim = isset($_POST['datanya'][4]) ? sanitize_text_field($_POST['datanya'][4]) : '';
    
    if ($load_count < 2) {
        $load_count = 2;
    }
    $start = 5 + ($load_count - 2) * 10;
    $limit = 10;

    // Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name5.' where type="theme_color" ORDER BY id ASC');
    $general_theme_color = (!empty($query_settings) && isset($query_settings[0]->data)) ? json_decode($query_settings[0]->data, true) : [];

    // set the color
    $theme_color 		= $general_theme_color['color'][0] ?? '';
	$progressbar_color  = $general_theme_color['color'][1] ?? '';
	$button_color 		= $general_theme_color['color'][2] ?? '';

	if(empty($button_color)){
		$button_color = '#dc2f6a';
	}

	$the_data = '';
    if($campaign_id!=''){
  		
    	$get_fundraiser = $wpdb->get_results($wpdb->prepare("SELECT a.campaign_id, c.user_id as fundraiser_id, count(a.id) as jumlah_donatur, sum(b.nominal) as total
	FROM $table_name3  a 
	LEFT JOIN $table_name2 c on c.id = a.affcode_id 
	LEFT JOIN $table_name b on b.id = a.donate_id 
	where a.campaign_id=%s and b.status = '1'
	GROUP BY fundraiser_id ORDER BY total DESC limit %d,%d", $campaign_id, $start, $limit));

		if (!empty($get_fundraiser) && is_array($get_fundraiser)) {
			foreach ($get_fundraiser as $value) {
		    	$user_info = get_userdata($value->fundraiser_id);
			    $fullname = ($user_info) ? ($user_info->first_name.' '.$user_info->last_name) : 'Fundraiser';

	        	$the_data .= '
		       	<div class="donation_inner_box" style="background:rgb(250, 252, 255);line-height:1.6;">
		            <div class="donation_name" style="color:'.$button_color.'">'.esc_html($fullname).'</div>
		            <div class="donation_comment" style="margin:0;">Berhasil mengajak '.$value->jumlah_donatur.' orang untuk berdonasi.<br></div>
		            <div class="donation_name">Rp&nbsp;'.number_format($value->total,0,",",".").'</div>
		        </div>
		        ';
			}
		}

		echo $the_data;

  	}

    wp_die();

} 
add_action( 'wp_ajax_dykfunction_load_fundraiser', 'dykfunction_load_fundraiser' );
add_action( 'wp_ajax_nopriv_dykfunction_load_fundraiser', 'dykfunction_load_fundraiser' );



// LOAD DOA DONATUR
function dykfunction_load_doa_donatur() {
	
    global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";
    $table_name2 = $wpdb->prefix . "dyk_love";
    
    $id = isset($_POST['datanya'][0]) ? sanitize_text_field($_POST['datanya'][0]) : '';
    $campaign_id = isset($_POST['datanya'][1]) ? sanitize_text_field($_POST['datanya'][1]) : '';
    $load_count = isset($_POST['datanya'][2]) ? intval($_POST['datanya'][2]) : 2;
    $anonim_text = isset($_POST['datanya'][3]) ? sanitize_text_field($_POST['datanya'][3]) : 'Orang Baik';
    $fullanonim = isset($_POST['datanya'][4]) ? sanitize_text_field($_POST['datanya'][4]) : '';
    
    if ($load_count < 2) {
        $load_count = 2;
    }
    $start = 5 + ($load_count - 2) * 10;
    $limit = 10;

    if($campaign_id!=''){
  		
  		$donation_paid = $wpdb->get_results($wpdb->prepare("SELECT * FROM $table_name where campaign_id=%s and status='1' and comment!='' ORDER BY id DESC limit %d,%d", $campaign_id, $start, $limit));

		$the_data = '';
		if (!empty($donation_paid) && is_array($donation_paid)) {
			foreach ($donation_paid as $value) {
				$donatur_name = $value->name;
				if($value->anonim=='1'){
					$donatur_name = !empty($anonim_text) ? $anonim_text : 'Orang Baik';
				}
				$donatur_name = wp_strip_all_tags($donatur_name);

				// time
				$readtime = new donasiyuk_readtime();
				$fix_time = $readtime->time_donation($value->created_at);

				$id_login = get_current_user_id();

				$a = donasiyuk_getIP();
			    $b = donasiyuk_getOS();
			    $c = donasiyuk_getBrowser();
			    $d = donasiyuk_getMobDesktop();
				if($id_login!=0){
					$row = $wpdb->get_results($wpdb->prepare("SELECT * from $table_name2 where user_id=%d and donate_id=%d", $id_login, $value->id));
			    	$is_loved = !empty($row);
				}else{
					$row = $wpdb->get_results($wpdb->prepare("SELECT * from $table_name2 where ip=%s and os=%s and browser=%s and mobdesktop=%s and donate_id=%d", $a, $b, $c, $d, $value->id));
			    	$is_loved = !empty($row);
				}

				$total_love = $wpdb->get_var($wpdb->prepare("SELECT SUM(love) FROM $table_name2 where donate_id=%d", $value->id));
				$love = (int) $total_love;
				$heart_color = $is_loved ? '#ef4444' : '#6b7280';
				$comment = wp_strip_all_tags(str_replace('\\', '', $value->comment));
				$clean_comment_json = htmlspecialchars(json_encode($comment), ENT_QUOTES, 'UTF-8');

	        	$the_data .= '
				<div class="dyk-doa-card" id="doa_card_'.$value->id.'">
					<div class="dyk-doa-card-header">
						<div class="dyk-doa-user">
							<div class="dyk-doa-avatar">
								<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="#9ca3af"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/></svg>
							</div>
							<div class="dyk-doa-user-meta">
								<div class="dyk-doa-name">'.esc_html($donatur_name).'</div>
								<div class="dyk-doa-time">'.esc_html($fix_time).'</div>
							</div>
						</div>
						<div class="dyk-doa-more" onclick="dykShareDoa(this, '.$clean_comment_json.');" title="Opsi">
							<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><circle cx="5" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="12" r="2"/></svg>
						</div>
					</div>
					<div class="dyk-doa-text">'.nl2br(esc_html($comment)).'</div>
					<div class="dyk-doa-stats" id="stats_love_'.$value->id.'">
						<strong>'.number_format($love, 0, ',', '.').' orang</strong> mengaminkan doa ini
					</div>
					<div class="dyk-doa-divider"></div>
					<div class="dyk-doa-actions">
						<button type="button" class="dyk-doa-btn dyk-btn-amin donation_love '.($is_loved ? 'active loved' : '').'" id="love_'.$value->id.'" data-donateid="'.$value->id.'" data-campaignid="'.$value->campaign_id.'" data-count="'.$love.'" title="Aamiin-kan doa ini">
							<svg class="dyk-heart-icon" xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="'.$heart_color.'" stroke="'.$heart_color.'" stroke-width="1.8"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path></svg>
							<span>Aamiin</span>
							<div class="plus1">+1</div>
						</button>
						<button type="button" class="dyk-doa-btn dyk-btn-share" onclick="dykShareDoa(this, '.$clean_comment_json.');" title="Bagikan doa">
							<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="18" cy="5" r="3"></circle><circle cx="6" cy="12" r="3"></circle><circle cx="18" cy="19" r="3"></circle><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"></line><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"></line></svg>
							<span>Bagikan</span>
						</button>
					</div>
				</div>
		        ';
			}
		}

		echo $the_data;

  	}

    wp_die();

} 
add_action( 'wp_ajax_dykfunction_load_doa_donatur', 'dykfunction_load_doa_donatur' );
add_action( 'wp_ajax_nopriv_dykfunction_load_doa_donatur', 'dykfunction_load_doa_donatur' );



function dykfunction_update_password() {
    global $wpdb;
    $table_name = $wpdb->prefix . "users";

    $id_login = wp_get_current_user()->ID;
    
    // FROM INPUT
    $user_id 	= $_POST['datanya'][0];
    $user_pass_new 	= $_POST['datanya'][1];

    if($id_login==$user_id){
 
	    $hash = wp_hash_password( $user_pass_new );
	    $wpdb->update(
	        $table_name,
	        array(
	            'user_pass'           => $hash
	        ),
	        array( 'ID' => $user_id )
	    );
	 		
	 	clean_user_cache( $user_id );

	 	ob_clean();
	 	echo 'success';
	}

	wp_die();

}
add_action( 'wp_ajax_dykfunction_update_password', 'dykfunction_update_password' );
add_action( 'wp_ajax_nopriv_dykfunction_update_password', 'dykfunction_update_password' ); 




function dykfunction_update_instruction() {
    global $wpdb;
    
    // FROM INPUT
    $newContent = $_POST['datanya'][0];
    $newContent = str_replace('\\', '', $newContent);
    $newContent = json_decode($newContent);
    $newContent = json_encode($newContent);

    // $data = json_encode($json);
    $filePath = plugin_dir_url( __FILE__ )."library/instructions.json";


    $result = file_put_contents($filePath, $newContent);

	// Prepare the response
	if ($result !== false) {
		ob_clean();
		echo 'success';
	} else {
		echo $newContent;
  	}
	
	wp_die();

}
add_action( 'wp_ajax_dykfunction_update_instruction', 'dykfunction_update_instruction' );
add_action( 'wp_ajax_nopriv_dykfunction_update_instruction', 'dykfunction_update_instruction' ); 


