                    $info_referral = '<p style="font-size:10px;color:#91a2b0;margin-bottom: 0;" title="referral"><img src="'.plugin_dir_url( __FILE__ ).'admin/icons/group.png" style="width: 10px;margin-left:1px;margin-right: 4px;margin-top: -1px;">'.esc_html($referral_name).'</p>';
                }

                $donasi_payment_info = $info_invoice.$info_referral.$info_payment_confirmed;
            }


            // Title Campaign
            $campaign_slug = isset($row->slug) ? $row->slug : '';
            $campaign_title = isset($row->title) ? $row->title : '';
            $title_campaign = '<a href="'.esc_url($campaign_url.$campaign_slug).'" title="Show Program" target="_blank">'.dyk_handling_character($campaign_title).'</a>';

            // Date
            $datenya = new DateTime($row->created_at);
            $date_donasi = '<span class="date_donasi">'.$datenya->format('d').'&nbsp;'.$datenya->format('M').',&nbsp;'.$datenya->format('Y').'&nbsp;-&nbsp;'.$datenya->format('H').':'.$datenya->format('i').'</span><br><span style="font-size:10px;color:#91a2b0;">'.$a.'<span>';

            // Payment Status
            if($role=='donatur'){
                if($success_by_campaigner=='1'){
                    $status = ($row->status=='1') ? 'received' : 'waiting';
                    $checked = ($row->status=='1') ? 'checked' : '';
                    $the_status = ($row->status=='1') ? 'Success' : 'Waiting';
                    $payment_status = '<div title="Update Payment" id="payment_'.$row->id.'" class="custom-control custom-switch set_payment '.$status.'"><input type="checkbox" class="custom-control-input set_payment_status" id="customSwitchSuccess_'.$row->id.'" '.$checked.' data-id="'.$row->id.'" data-invoiceid="'.esc_attr($row->invoice_id ?? '').'"><label class="custom-control-label" for="customSwitchSuccess_'.$row->id.'" style="font-size: 11px;"><span>'.$the_status.'</span></label></div>';
                }else{
                    $payment_status = ($row->status=='1') ? '<span class="active-status p_received">Success</span>' : '<span class="active-status p_waiting">Waiting</span>';
                }
            }else{
                if($success_by_cs=='0' && $role=='cs'){
                    if($row->status=='1'){
                        $payment_status = '<span class="active-status p_received" style="padding: 5px 12px;font-size:10px;display:block;text-align:center;">Success</span>';
                    }else{
                        $payment_status = '<span class="active-status p_waiting" style="padding: 5px 12px;font-size:10px;background:#E1345E;display:block;text-align:center;">Waiting</span>';
                    }
                }else{
                    $status = ($row->status=='1') ? 'received' : 'waiting';
                    $checked = ($row->status=='1') ? 'checked' : '';
                    $the_status = ($row->status=='1') ? 'Success' : 'Waiting';
                    $payment_status = '<div title="Update Payment" id="payment_'.$row->id.'" class="custom-control custom-switch set_payment '.$status.'"><input type="checkbox" class="custom-control-input set_payment_status" id="customSwitchSuccess_'.$row->id.'" '.$checked.' data-id="'.$row->id.'" data-invoiceid="'.esc_attr($row->invoice_id ?? '').'"><label class="custom-control-label" for="customSwitchSuccess_'.$row->id.'" style="font-size: 11px;"><span>'.$the_status.'</span></label></div>';
                }
            }

            // Action
            $button_action = '<div class="btn-group m-0" role="group" aria-label="Basic example"><button type="button" class="btn btn-outline-light detail_donasi" data-id="'.$row->id.'" title="Show Detail" style="border-top-right-radius:0;border-bottom-right-radius:0;padding:3px 7px;"><i class="mr-1" data-lucide="file-text" style="margin: 0 !important;color:#7680FF"></i></button><button type="button" class="btn btn-outline-light del_donasi" data-id="'.$row->id.'" title="Delete" style="padding:3px 7px;"><i class="mr-1" data-lucide="trash-2" style="margin: 0 !important;color:#EF4D56"></i></button></div>';

            $status_blocked_ip = check_blocked_ip_status2($row->ip ?? '');
            $info_blocked = ($status_blocked_ip=='blocked') ? 'Spammer' : '';

            $row_item = [
                'no'             => '<span data-id="'.$row->id.'">'.$no.'</span>',
                'picture'        => $pp,
                'name'           => '<span class="'.$status_blocked_ip.'" title="'.$info_blocked.'">'.$donatur_name.'<span>'.$datane2,
                'total_donate'   => $nominal_donasi.$donasi_payment_info,
                'program'        => $title_campaign,
                'payment_status' => $payment_status.$img_confirmation,
                'date'           => $date_donasi,
            ];

            if($role=='donatur'){
                if($wa_column_setting=='1'){
                    $row_item['whatsapp'] = $whatsapp;
                }
            }else{
                $row_item['whatsapp'] = $whatsapp;
            }

            if($role!='donatur'){
                $row_item['cs'] = $cs_name;
                $row_item['followup'] = $button_followupnya;
            }

            if($role!='donatur' && $role!='cs'){
                $row_item['action'] = $button_action;
            }

            $data_rows[] = $row_item;
            $no++;
        }
    }

    while (ob_get_level() > 0) {
        ob_end_clean();
    }

    $response = [
        'draw'                    => intval($draw),
        'recordsTotal'            => intval($jumlah_total ?? 0),
        'recordsFiltered'         => intval($jumlah_total ?? 0),
        'totalDonasi'             => (string)($totalDonasi ?? '0'),
        'totalDonasiCS'           => (string)($totalDonasi_cs ?? '0'),
        'jumlahDonasi'            => (string)($jumlahDonasi ?? '0'),
        'jumlahDonasiCS'          => (string)($jumlahDonasi_cs ?? '0'),
        'jumlahDonasiTerkumpul'   => (string)($jumlahDonasiTerkumpul ?? '0'),
        'jumlahDonasiTerkumpulCS' => (string)($jumlahDonasiTerkumpul_cs ?? '0'),
        'konversi'                => (string)($konversi ?? '0 %'),
        'konversiCS'              => (string)($konversi_cs ?? '0 %'),
        'data'                    => $data_rows,
    ];

    wp_send_json($response);

}

