function get_referral_name_by_user_id($aff_user_id){

	global $wpdb;
	$table_name7 = $wpdb->prefix . "dyk_aff_submit";
    $table_name8 = $wpdb->prefix . "dyk_aff_code";

    // $row3 = $wpdb->get_results("SELECT b.user_id as aff_user_id from $table_name7 a 
    // left JOIN $table_name8 b ON b.id = a.affcode_id where a.donate_id='$donate_id' ");

    if($aff_user_id!=null){
    	$user_info_cs = get_userdata($aff_user_id);
    	if($user_info_cs->last_name==''){
	    	$referral_name = $user_info_cs->first_name;
	    }else{
	    	$referral_name = $user_info_cs->first_name.'&nbsp;'.$user_info_cs->last_name;
	    }
    }else{
    	$referral_name = '';
    }

    return $referral_name;

}


function dyk_get_data_trash(){

	set_time_donasiaja();

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_campaign";
    $table_name2 = $wpdb->prefix . "dyk_category";
    $table_name3 = $wpdb->prefix . "dyk_campaign_update";
    $table_name4 = $wpdb->prefix . "dyk_donate";
    $table_name5 = $wpdb->prefix . "dyk_settings";
    $table_name6 = $wpdb->prefix . "dyk_users";
    $table_name7 = $wpdb->prefix . "users";
    $table_name8 = $wpdb->prefix . "dyk_payment_log";
    $table_name9 = $wpdb->prefix . "dyk_donate_trash";

    $startlist 	  = $_POST['start'];
    $length 	  = $_POST['length'];
    $draw 		  = $_POST['draw'];
    $c_id 		  = $_POST['c_id'];
    $date_filter  = $_POST['date_filter'];
    $date_range   = $_POST['date_range'];
    $search_value = $_POST['search']['value'];

    // Currency
    $query_currency = $wpdb->get_results('SELECT data from '.$table_name5.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;
    $show_currency = donasiyuk_currency($currency);
    $show_currency2 = donasiyuk_currency2($currency);

    $lang = get_data_lang($currency);
    $langArray = require_once(ROOTDIR_DYK . 'library/locale/'.$lang.'.php');

    // Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name5.' where type="form_setting" or type="btn_followup" or type="text_f1" or type="text_f2" or type="text_f3" or type="text_f4" or type="text_f5" or type="text_received" or type="text_received_status" or type="wanotif_on_dashboard" or type="success_by_cs"  ORDER BY id ASC');
    $form_setting = $query_settings[0]->data;
    $btn_followup = $query_settings[1]->data;
    $text_f1 = $query_settings[2]->data;
    $text_f2 = $query_settings[3]->data;
    $text_f3 = $query_settings[4]->data;
    $text_f4 = $query_settings[5]->data;
    $text_f5 = $query_settings[6]->data;
    $text_received = $query_settings[7]->data;
    $text_received_status = $query_settings[8]->data;
    $wanotif_on_dashboard = $query_settings[9]->data;
    $success_by_cs = $query_settings[10]->data;

    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];
    $id_login = wp_get_current_user()->ID;


    if($c_id=='all'){
    	$c_id = null;
    }

    $limit = '';
    if($length==-1){
		$limit = '';
	}else{
		$limit = "LIMIT $startlist,$length";
	}


    $filternya = "";
    if($date_filter=='today' || $date_filter=='yesterday' || $date_filter=='7lastdays' || $date_filter=='30lastdays' || $date_filter=='thismonth' || $date_filter=='lastmonth' || $date_filter=='thisyear' || $date_filter=='lastyear' || $date_filter=='last2years' || $date_filter=='last3years' || $date_filter=='daterange' || $date_filter=='all'){
    
        // Date
        $today = date('Y-m-d');
        $yesterday = date("Y-m-d", strtotime("-1 day"));
        $one_week_ago = date("Y-m-d", strtotime("-7 day"));
        $one_month_ago = date("Y-m-d", strtotime("-30 day"));
        $three_months_ago = date("Y-m-d", strtotime("-90 day"));
        $thismonth = date("Y-m-01");
        $thisyear = date("Y-01-01");
        
        $month = date('m');
        $year = date('Y');
        if($month==1){
        	$monthnya = 12;
        	$yearnya = $year-1;
        }else{
        	$monthnya = $month-1;
        	$yearnya = $year;
        }
		$lastmonth_firstrange = date($yearnya."-".$monthnya."-01");
		$lastmonth_lastrange = date($yearnya."-".$monthnya."-31");

		if($date_range!=''){
			$date_range = explode('_',$date_range);
			$date_range_first = date($date_range[0]);
			$date_range_last = date($date_range[1]);
		}else{
			$date_range_first = $today;
			$date_range_last = $today;
		}

        // last year
		$lastyear_yearnya = $year-1;
		$lastyear_firstrange = date($lastyear_yearnya."-01-01");
		$lastyear_lastrange = date($lastyear_yearnya."-12-31");

		// 2 last year
		$twolastyear_yearnya = $year-2;
		$twolastyear_firstrange = date($twolastyear_yearnya."-01-01");
		$twolastyear_lastrange = date(($twolastyear_yearnya+1)."-12-31");

		// 3 last year
		$threelastyear_yearnya = $year-3;
		$threelastyear_firstrange = date($threelastyear_yearnya."-01-01");
		$threelastyear_lastrange = date(($threelastyear_yearnya+2)."-12-31");
		

        if($date_filter=='today'){
            $filternya = "and a.created_at BETWEEN '$today 00:00' AND '$today 23:59'";
        }elseif($date_filter=='yesterday'){
            $filternya = "and a.created_at BETWEEN '$yesterday 00:00' AND '$yesterday 23:59'";
        }elseif($date_filter=='7lastdays'){
            $filternya = "and a.created_at BETWEEN '$one_week_ago 00:00' AND '$today 23:59'";
        }elseif($date_filter=='30lastdays'){
            $filternya = "and a.created_at BETWEEN '$one_month_ago 00:00' AND '$today 23:59'";
        }elseif($date_filter=='3months'){
            $filternya = "and a.created_at BETWEEN '$three_months_ago 00:00' AND '$today 23:59'";
        }elseif($date_filter=='thismonth'){
            $filternya = "and a.created_at BETWEEN '$thismonth 00:00' AND '$today 23:59'";
        }elseif($date_filter=='lastmonth'){
            $filternya = "and a.created_at BETWEEN '$lastmonth_firstrange 00:00' AND '$lastmonth_lastrange 23:59'";
        }elseif($date_filter=='thisyear'){
            $filternya = "and a.created_at BETWEEN '$thisyear 00:00' AND '$today 23:59'";
        }elseif($date_filter=='lastyear'){
            $filternya = "and a.created_at BETWEEN '$lastyear_firstrange 00:00' AND '$lastyear_lastrange 23:59'";
        }elseif($date_filter=='last2years'){
            $filternya = "and a.created_at BETWEEN '$twolastyear_firstrange 00:00' AND '$twolastyear_lastrange 23:59'";
        }elseif($date_filter=='last3years'){
            $filternya = "and a.created_at BETWEEN '$threelastyear_firstrange 00:00' AND '$threelastyear_lastrange 23:59'";
        }elseif($date_filter=='daterange'){
            $filternya = "and a.created_at BETWEEN '$date_range_first 00:00' AND '$date_range_last 23:59'";
        }else{
            $filternya = "";
        }

        // and a.created_at BETWEEN '2022-03-28 00:00' AND '2022-04-27 23:59'
    }

    $search_filter = '';
    if($search_value!=''){
    	$search_value2 = '';
    	if(strtolower($search_value)=='waiting'){
    		$search_value2 = '0';
    	}
    	if(strtolower($search_value)=='success'){
    		$search_value2 = '1';
    	}

    	if($search_value2=='1' || $search_value2=='0'){
    		$search_filter = "and (name like '%$search_value%' or whatsapp like '%$search_value%' or email like '%$search_value%' or comment like '%$search_value%' or nominal like '%$search_value%' or invoice_id like '%$search_value%' or process_by like '%$search_value%' or status like '%$search_value2%') ";
    	}else{
    		$search_filter = "and (name like '%$search_value%' or whatsapp like '%$search_value%' or email like '%$search_value%' or comment like '%$search_value%' or nominal like '%$search_value%' or invoice_id like '%$search_value%' or process_by like '%$search_value%') ";
    	}
    	
    }

    $data_donasi = $wpdb->get_results("
        SELECT a.*, d.user_randid, d.user_pp_img, c.title, c.campaign_id, c.slug, c.publish_status from $table_name9 a 
        LEFT JOIN $table_name7 b on a.user_id = b.id
        LEFT JOIN $table_name c on a.campaign_id = c.campaign_id 
        LEFT JOIN $table_name6 d on b.id = d.user_id
        WHERE a.donate_id != ''
        $search_filter $filternya
        ORDER BY a.id DESC $limit");

    $jumlah_total = $wpdb->get_results("
        SELECT count(a.donate_id) as idnya from $table_name9 a 
        LEFT JOIN $table_name7 b on a.user_id = b.id
        LEFT JOIN $table_name c on a.campaign_id = c.campaign_id 
        WHERE a.donate_id != '' $search_filter $filternya ORDER BY a.id DESC")[0]->idnya;


	$no = 1 + intval($startlist ?? 0);
	$data_rows = [];

	if (!empty($data_donasi) && is_array($data_donasi)) {
		foreach ($data_donasi as $row) {

			  		if($row->publish_status=='1'){
                        $campaign_url = get_site_url().'/campaign/';
                    }else{
                        $campaign_url = get_site_url().'/preview/';
                    }
                    

                    $button_followupnya = '<div class="followup-btn-group" style="display:inline-flex;align-items:center;gap:3px;flex-wrap:nowrap;white-space:nowrap;">';
                    for ($i = 1; $i <= $btn_followup; $i++){
                        $var = 'f'.$i;
                        if($row->$var=='1'){$$var = 'sent';}else{$$var = '';}
                        $button_followupnya .= '<button type="button" data-id="'.$row->id.'" data-followup="'.$i.'" class="btn btn-primary btn-followup '.$$var.' followup'.$i.'" title="Followup '.$i.'">'.$wa_icon_svg.'<span>'.$i.'</span></button>';
                    }
                    $button_followupnya .= '</div>';

                    $user_info = get_userdata($row->user_id);
                    if($user_info!=null){
                        $fullname = $user_info->first_name.' '.$user_info->last_name;
                    }

                    $time_donate_deleted = date('Y-m-d H:i:s',strtotime('+0 hour',strtotime($row->deleted_at)));

                    $readtime = new humanReadtime();
                    $a = $readtime->dyk_human_time($time_donate_deleted);

                    // GET DATA CS
				    $user_info_cs = get_userdata($row->cs_id);
				    if($user_info_cs!=null){
				    	if($user_info_cs->last_name==''){
					    	$cs_name = '<span id='."'".'cs_'.$row->id."'".'>'.$user_info_cs->first_name.'</span>';
					    }else{
					    	$cs_name = '<span id='."'".'cs_'.$row->id."'".'>'.$user_info_cs->first_name.'&nbsp;'.$user_info_cs->last_name.'</span>';
					    }
				    }else{
				    	$cs_name = '<span id='."'".'cs_'.$row->id."'".'>-</span>';
				    }

                    // Profile Picture
                    if($row->user_id!='0') {

                    	if($row->user_pp_img=='') {
                    		$pp = '<a id='."'".'link_pp_'.$row->id."'".' href='."'".get_site_url().'/profile/'.$row->user_randid."'".'  target='."'".'_blank'."'".'><img alt='."''".' id='."'".'pp_'.$row->id."'".' src='."'".plugin_dir_url( __FILE__ ).'assets/images/pp.svg'."'".' class='."'".'rounded-circle thumb-md'."'".' style='."'".'border: 1px solid #dde4ec;height: 38px;width: 38px;margin-top: -4px;max-width: 38px'."'".'></a>';
                    	}else{
                    		$pp ='<a id='."'".'link_pp_'.$row->id."'".' href='."'".get_site_url().'/profile/'.$row->user_randid."'".' target='."'".'_blank'."'".'><img alt='."''".' id='."'".'pp_'.$row->id."'".' src='."'".$row->user_pp_img."'".' class='."'".'rounded-circle thumb-md'."'".' style='."'".'border: 1px solid #dde4ec;height: 38px;width: 38px;margin-top: -4px;max-width: 38px'."'".'></a>';
                    	}
                    }else{
                    	if($row->user_pp_img=='') {
                    		$pp = '<img alt='."''".' id='."'".'pp_'.$row->id."'".' src='."'".plugin_dir_url( __FILE__ ).'assets/images/pp.svg'."'".' class='."'".'rounded-circle thumb-md'."'".' style='."'".'border: 1px solid #dde4ec;height: 38px;width: 38px;margin-top: -4px;max-width: 38px'."'".'>';
                    	}else{
                    		$pp ='<img alt='."''".' id='."'".'pp_'.$row->id."'".' src='."'".$row->user_pp_img.'" class='."'".'rounded-circle thumb-md'."'".' style='."'".'border: 1px solid #dde4ec;height: 38px;width: 38px;margin-top: -4px;max-width: 38px'."'".'>';
                    	}
                    }


                    // Donatur Name
                    if($row->user_id!='0'){
                    	$donatur_name = '<span id='."'".'name_'.$row->id."'".'><a href='."'".get_site_url().'/profile/'.$row->user_randid."'".' target='."'".'_blank'."'".'>'.dyk_handling_character($row->name).'</a></span>';
                    }else{
                    	$donatur_name = '<span id='."'".'name_'.$row->id."'".'>'.dyk_handling_character($row->name).'</span>';
                    }

                    // Whatsapp
                    $whatsapp = '<span id='."'".'whatsapp_'.$row->id."'".'>'.dyk_handling_character($row->whatsapp).'</span>';
                    
                    // Nominal Donasi
                    if($role=='donatur'){
                    	$nominal_donasi = '<span id='."'".'nominal_'.$row->id."'".'>'.$show_currency2.number_format_currency($row->nominal).'</span>';
	                }else{
	                	if($row->payment_code=='ovo'){
	                		$margin_left = 'margin-left:-6px;';
	                	}elseif($row->payment_code=='doku'){
	                		$margin_left = 'margin-left:-10px;';
	                	}elseif($row->payment_code=='dana' || $row->payment_code=='bca' || $row->payment_code=='bni' || $row->payment_code=='qris' || $row->payment_code=='gopay'){
	                		$margin_left = 'margin-left:-3px;';
	                	}elseif($row->payment_code=='my_touchngo' || $row->payment_code=='my_affin_bank' || $row->payment_code=='my_alliance_bank' || $row->payment_code=='my_am_bank' || $row->payment_code=='my_bank_rakyat' || $row->payment_code=='my_cimb' || $row->payment_code=='my_hong_leong_bank' || $row->payment_code=='my_maybank2u' || $row->payment_code=='my_ocbc_bank' || $row->payment_code=='my_standard_chartered'){
