						$image_icon_bank = strtolower($row->payment_code);
						if($image_icon_bank=='cimb'){
							$image_icon_bank = 'cimb_niaga';
						}

	                	$nominal_donasi = '<div class='."'img_payment_code'".' '.$show_icon_bank.'><img src='."'".plugin_dir_url( __FILE__ ).'assets/images/bank/'.$image_icon_bank.'.png'."'".' style='."'".'width:35px;'.$margin_left.'margin-right: 4px;margin-top: -1px;'."'".'></div><span id='."'".'nominal_'.$row->id."'".'>'.$show_currency2.number_format_currency($row->nominal).'</span>';
	                }

                    $get_log = $wpdb->get_results("SELECT * FROM $table_name8 where id_donate='$row->id' ");
				    if($get_log!=null){
				    	if(strtolower($get_log[0]->message)=='success'){
				    		$style_inv_color = '';
				    		$title_payment_gateway = "title='Show Detail'";
				    	}else{
				    		$style_inv_color = 'color:#EF4D56 !important;';
				    		$title_payment_gateway = "title='Payment Gateway Error'";
				    	}
				    }else{
				    	$style_inv_color = '';
				    	$title_payment_gateway = "title='Show Detail'";
				    }

                    $donasi_payment_info = '';
                    $img_confirmation = '';
                    if($role!='donatur'){

                    	// image confirmation
	                    if($row->img_confirmation_url!=''){
	                    	$status_img = '';
	                    	if($row->img_confirmation_status=='1'){
	                    		$status_img = 'status_check';
