					    	}else{
					    		$datane2 .= '<li  href='."'".'javascript:;'."'".' data-id='."'".$row->id."'".' class='."'".'detail_donasi'."'".' style='."'".'font-size:10px;margin-bottom:2px;background: #eaf0f7;border-radius: 3px;padding-left: 10px;padding-top: 2px;padding-bottom: 2px;width: 50px;cursor:pointer;'."'".' title='."'".$value['type']."'".'><img src='."'".plugin_dir_url( __FILE__ ) .'assets/images/qurban/'.$value['type'].'.png'."'".' style='."'".'width:11px;margin-right:3px;margin-top:-2px;'."'".'> x '.$value['jumlah'].'</li>';
					    	}
					    	$count_qurban++;
					    	
					    }
					    $datane2 = $datane2.'</ul>';
					    if($count_qurban==0){
					    	$datane2 = '';
					    }

		                // info invoice
	                    $info_invoice = '<br><a href='."'".'javascript:;'."'".' class='."'".'detail_donasi'."'".' data-id='."'".$row->id."'".'><i class='."'".'dashicons dashicons-format-aside'."'".' style='."'".$style_inv_color."'".'></i><span style='."'".$style_inv_color."padding-top:2px;'".' '.$title_payment_gateway.'>'.$row->invoice_id.'</span></a>';

	                    	$info_payment_confirmed = '';
	                        if($row->process_by=='moota'){
	                        	$info_payment_confirmed = '<p style='."'".'font-size:10px;color:#91a2b0;margin-bottom: 0;'."'".'><img src='."'".plugin_dir_url( __FILE__ ).'admin/icons/moota.png'."'".' style='."'".'width: 10px;margin-left:1px;margin-right: 4px;margin-top: 0px;'."'".'>Moota</p>';
	                        }elseif($row->process_by=='ipaymu'){
	                        	$info_payment_confirmed = '<p style='."'".'font-size:10px;color:#91a2b0;margin-bottom: 0;'."'".'><img src='."'".plugin_dir_url( __FILE__ ).'admin/icons/ipaymu.png'."'".' style='."'".'width: 10px;margin-left:1px;margin-right: 4px;margin-top: -1px;'."'".'>iPaymu</p>';
	                        }elseif($row->process_by=='tripay'){
	                        	$info_payment_confirmed = '<p style='."'".'font-size:10px;color:#91a2b0;margin-bottom: 0;'."'".'><img src='."'".plugin_dir_url( __FILE__ ).'admin/icons/tripay.png'."'".' style='."'".'width: 10px;margin-left:1px;margin-right: 4px;margin-top: -1px;'."'".'>Tripay</p>';
	                        }elseif($row->process_by=='midtrans'){
	                        	$info_payment_confirmed = '<p style='."'".'font-size:10px;color:#91a2b0;margin-bottom: 0;'."'".'><img src='."'".plugin_dir_url( __FILE__ ).'admin/icons/midtrans.png'."'".' style='."'".'width: 10px;margin-left:1px;margin-right: 4px;margin-top: -1px;'."'".'>Midtrans</p>';
	                        }elseif($row->process_by=='xendit'){
	                        	$info_payment_confirmed = '<p style='."'".'font-size:10px;color:#91a2b0;margin-bottom: 0;'."'".'><img src='."'".plugin_dir_url( __FILE__ ).'admin/icons/xendit.png'."'".' style='."'".'width: 10px;margin-left:1px;margin-right: 4px;margin-top: -1px;'."'".'>Xendit</p>';
	                        }elseif($row->process_by=='flip'){
	                        	$info_payment_confirmed = '<p style='."'".'font-size:10px;color:#91a2b0;margin-bottom: 0;'."'".'><img src='."'".plugin_dir_url( __FILE__ ).'admin/icons/flip.png'."'".' style='."'".'width: 10px;margin-left:1px;margin-right: 4px;margin-top: -1px;'."'".'>Flip</p>';
	                        }elseif($row->process_by=='remitcepat'){
	                        	$info_payment_confirmed = '<p style='."'".'font-size:10px;color:#91a2b0;margin-bottom: 0;'."'".'><img src='."'".plugin_dir_url( __FILE__ ).'admin/icons/remitcepat.png'."'".' style='."'".'width: 10px;margin-left:1px;margin-right: 4px;margin-top: -1px;'."'".'>Remitcepat</p>';
	                        }else{ }

	                    $donasi_payment_info = $info_invoice.$info_payment_confirmed;

                    }


                    // Title Campaign
                    if($row->title==''){
                    	$title_campaign = '<span style=color:#EF4F57>Not Found</span>';
                    	$button_restore = 'disabled';
                    	$button_restore_color = '#888';
                    	$button_restore_title = 'Restore Disabled';
                    }else{
                    	$title_campaign = '<a href='."'".$campaign_url.$row->slug."'".' title='."Show&nbsp;Program".' target='."'".'_blank'."'".'>'.dyk_handling_character($row->title).'</a>';
                    	$button_restore = '';
                    	$button_restore_color = '#2DDAB5';
                    	$button_restore_title = 'Restore Data';
                    }

                    // Date
                    $datenya = new DateTime($row->deleted_at);
                    $date_deleted = '<span class=date_donasi>'.$datenya->format('d').'&nbsp;'.$datenya->format('M').',&nbsp;'.$datenya->format('Y').'&nbsp;-&nbsp;'.$datenya->format('H').':'.$datenya->format('i').'</span><br><span style='."'".'font-size:10px;color:#91a2b0;'."'".'>'.$a.'<span>';

                    // Payment Status
                	if($row->status=='1'){
                        $payment_status = '<span class='."'".'active-status p_received'."'".'>Success</span>';
                    }else{
                        $payment_status = '<span class='."'".'active-status p_waiting'."'".'>Waiting</span>';
                    }

                

                    $button_action = '<div class="btn-group mb-4" role="group" aria-label="Basic example"><button '.$button_restore.' type="button" class="btn btn-outline-light restore_data" data-action="ontrash" data-id="'.$row->id.'" title="'.$button_restore_title.'" style="border-top-right-radius:0;border-bottom-right-radius:0;"><i class="mr-2" data-lucide="rotate-ccw" style="margin: 0 4px 0 2px !important;color:'.$button_restore_color.';"></i></button><button type="button" class="btn btn-outline-light del_donasi" data-id="'.$row->id.'" title="Delete Permanently"><i class="mr-2" data-lucide="trash-2" style="margin: 0 4px 0 2px !important;color:#EF4D56"></i></button></div>';

                    $row_item = [
                        'no'             => '<span data-id="'.$row->id.'">'.$no.'</span>',
                        'picture'        => $pp,
                        'name'           => str_replace('\\', '', $donatur_name).$datane2,
                        'whatsapp'       => $whatsapp,
                        'total_donate'   => $nominal_donasi.$donasi_payment_info,
                        'program'        => $title_campaign,
                        'payment_status' => $payment_status.$img_confirmation,
                        'date'           => $date_deleted,
                        'cs'             => str_replace('\\', '', $row->who_del_name ?? ''),
                    ];

                    if($role!='donatur' && $role!='cs'){
                        $row_item['action'] = $button_action;
                    }

                    $data_rows[] = $row_item;
                    $no++;

				}
            }

            while (ob_get_level() > 0) {
                ob_end_clean();
            }

            $response = [
                'draw'            => intval($draw ?? 1),
                'recordsTotal'    => intval($jumlah_total ?? 0),
                'recordsFiltered' => intval($jumlah_total ?? 0),
                'data'            => $data_rows ?? [],
            ];

            wp_send_json($response);

}

