function dyk_get_data_ip(){

	set_time_donasiaja();

	global $wpdb;
    $table_name5 = $wpdb->prefix . "dyk_settings";
    $table_name9 = $wpdb->prefix . "dyk_blocked_ip";

    $startlist 	  = isset($_POST['start']) ? intval($_POST['start']) : 0;
    $length 	  = isset($_POST['length']) ? intval($_POST['length']) : 10;
    $draw 		  = isset($_POST['draw']) ? intval($_POST['draw']) : 1;

    $c_id 		  = isset($_POST['c_id']) ? sanitize_text_field($_POST['c_id']) : '';
    $date_filter  = isset($_POST['date_filter']) ? sanitize_text_field($_POST['date_filter']) : '';
    $date_range   = isset($_POST['date_range']) ? sanitize_text_field($_POST['date_range']) : '';
    $search_value = isset($_POST['search']['value']) ? sanitize_text_field($_POST['search']['value']) : '';
    $status_raw   = isset($_POST['status']) ? sanitize_text_field($_POST['status']) : '';

    $status = ($status_raw == 'blocked') ? 1 : 0;

    $query_currency = $wpdb->get_results('SELECT data from '.$table_name5.' where type="currency"  ORDER BY id ASC');
    $currency = (!empty($query_currency) && isset($query_currency[0]->data)) ? $query_currency[0]->data : 'IDR';
    $show_currency = donasiyuk_currency($currency);
    $show_currency2 = donasiyuk_currency2($currency);

    $current_user_id = get_current_user_id();
    $cap = get_user_meta( $current_user_id, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = is_array($cap) ? array_keys($cap) : [];
    $role = $roles[0] ?? 'administrator';

    $limit = '';
    if($length > 0){
		$limit = "LIMIT $startlist,$length";
	}

    $search_filter = '';
    if($search_value!=''){
    	$search_esc = '%' . $wpdb->esc_like($search_value) . '%';
    	$search_filter = $wpdb->prepare("and (ip like %s or note like %s) ", $search_esc, $search_esc);
    }

    $data_ip = $wpdb->get_results($wpdb->prepare("
        SELECT a.* from $table_name9 a 
        WHERE a.id != ''
        AND status = %d
        $search_filter
        ORDER BY a.id DESC $limit", $status));

    $jumlah_total = (int) $wpdb->get_var($wpdb->prepare("
        SELECT count(a.id) from $table_name9 a 
        WHERE a.id != '' 
        AND status = %d 
        $search_filter", $status));

	$no = 1 + $startlist;
	$data_rows = [];

	if (!empty($data_ip) && is_array($data_ip)) {
		foreach ($data_ip as $row) {
			$user_info = get_userdata($row->created_by);
			if(!empty($user_info)){
				$fullname = ($user_info->first_name ?? '') . ' ' . ($user_info->last_name ?? '');
			}else{
				$fullname = '-';
			}

			$button_action = '<div class="btn-group mb-2" role="group" aria-label="Basic example" style="margin-top:-5px;"><button type="button" class="btn btn-outline-light edit_ip" data-action="ontrash" data-id="'.intval($row->id).'" title="Edit" style="border-top-right-radius:0;border-bottom-right-radius:0;"><i class="mr-2" data-lucide="pencil" style="margin: 0 4px 0 2px !important;color:#2DDAB5;"></i></button><button type="button" class="btn btn-outline-light del_ip" data-id="'.intval($row->id).'" title="Delete Permanently"><i class="mr-2" data-lucide="trash-2" style="margin: 0 4px 0 2px !important;color:#EF4D56"></i></button></div>';

			$readtime = new humanReadtime();
			$a = $readtime->dyk_human_time($row->created_at);

			$datenya = new DateTime($row->created_at);
			$blocked_time = '<span class=date_donasi>'.$datenya->format('d').'&nbsp;'.$datenya->format('M').',&nbsp;'.$datenya->format('Y').'&nbsp;-&nbsp;'.$datenya->format('H').':'.$datenya->format('i').'</span><br><span style="font-size:10px;color:#91a2b0;">'.$a.'</span>';

			$row_item = [
				'no'         => '<span data-id="'.intval($row->id).'">'.$no.'</span>',
				'ip'         => esc_html($row->ip ?? ''),
				'note'       => esc_html($row->note ?? ''),
				'date'       => $blocked_time,
				'created_by' => esc_html(stripslashes($fullname)),
			];

			if($role!='donatur' && $role!='cs'){
				$row_item['action'] = $button_action;
			}

			$data_rows[] = $row_item;
			$no++;
		}
	}

	while (ob_get_level() > 0) {
		ob_end_clean();
	}

	wp_send_json([
		'draw'            => $draw,
		'recordsTotal'    => $jumlah_total,
		'recordsFiltered' => $jumlah_total,
		'data'            => $data_rows,
	]);

}

add_action( 'wp_ajax_dja_get_data_ip', 'dyk_get_data_ip' );
add_action( 'wp_ajax_dyk_get_data_ip', 'dyk_get_data_ip' );
add_action( 'wp_ajax_nopriv_dja_get_data_ip', 'dyk_get_data_ip' );
