function dyk_get_group_list(){

	set_time_donasiaja();

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_group_list";
    $table_name2 = $wpdb->prefix . "dyk_group_data";

    $startlist 	  = isset($_POST['start']) ? intval($_POST['start']) : 0;
    $length 	  = isset($_POST['length']) ? intval($_POST['length']) : 10;
    $draw 		  = isset($_POST['draw']) ? intval($_POST['draw']) : 1;
    $search_value = isset($_POST['search']['value']) ? sanitize_text_field($_POST['search']['value']) : '';

    $limit = '';
    if ($length > 0) {
        $limit = "LIMIT $startlist,$length";
    }

	$search_filter = '';
    if ($search_value !== '') {
    	$search_filter = $wpdb->prepare("WHERE group_name LIKE %s", '%' . $wpdb->esc_like($search_value) . '%');
    }

    $data_group = $wpdb->get_results("SELECT * from $table_name $search_filter ORDER BY id DESC $limit");
    $jumlah_total = (int) $wpdb->get_var("SELECT COUNT(id) FROM $table_name $search_filter");

	$no = 1 + $startlist;
	$data_rows = [];

	if (!empty($data_group) && is_array($data_group)) {
		foreach ($data_group as $row) {
			$count_data = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(id) FROM $table_name2 WHERE group_id = %d", $row->id));
			$link = admin_url("admin.php?page=donasiyuk_dashboard&action=group&id=" . intval($row->id));
			$group_name_clean = stripslashes($row->group_name ?? '');

			$button_action = '<div class="btn-group" role="group"><a href="' . esc_url($link) . '"><button type="button" class="btn btn-outline-light group_detail" data-id="' . intval($row->id) . '" title="Data Detail" style="border-top-right-radius:0;border-bottom-right-radius:0;"><i class="mr-2" data-lucide="file-text" style="margin: 0 4px 0 2px !important;color:#7680FF"></i></button></a><button type="button" class="btn btn-outline-light del_data_group_all" data-id="' . intval($row->id) . '" data-gname="' . esc_attr($group_name_clean) . '" title="Delete"><i class="mr-2" data-lucide="trash-2" style="margin: 0 4px 0 2px !important;color:#EF4D56"></i></button></div>';

			$data_rows[] = [
				'no'     => '<span data-id="' . intval($row->id) . '">' . $no . '</span>',
				'name'   => '<a href="' . esc_url($link) . '">' . esc_html($group_name_clean) . '</a>',
				'data'   => (string) $count_data,
				'action' => $button_action,
			];
			$no++;
		}
	}

	while (ob_get_level() > 0) {
		ob_end_clean();
	}

	wp_send_json([
		'draw'            => $draw,
		'recordsTotal'    => $jumlah_total,
		'recordsFiltered' => $jumlah_total,
		'data'            => $data_rows,
	]);

}

