    $startlist 	  = isset($_POST['start']) ? intval($_POST['start']) : 0;
    $length 	  = isset($_POST['length']) ? intval($_POST['length']) : 10;
    $draw 		  = isset($_POST['draw']) ? intval($_POST['draw']) : 1;
    $group_id 	  = isset($_POST['group_id']) ? intval($_POST['group_id']) : 0;
    $search_value = isset($_POST['search']['value']) ? sanitize_text_field($_POST['search']['value']) : '';

    $limit = '';
    if ($length > 0) {
        $limit = "LIMIT $startlist,$length";
    }

	$search_filter = '';
    if ($search_value !== '') {
    	$search_esc = '%' . $wpdb->esc_like($search_value) . '%';
    	$search_filter = $wpdb->prepare("AND (name LIKE %s OR whatsapp LIKE %s OR sapaan LIKE %s)", $search_esc, $search_esc, $search_esc);
    }

    $data_group = $wpdb->get_results($wpdb->prepare("SELECT * from $table_name2 WHERE group_id = %d $search_filter ORDER BY id DESC $limit", $group_id));
    $jumlah_total = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(id) FROM $table_name2 WHERE group_id = %d $search_filter", $group_id));

	$no = 1 + $startlist;
	$data_rows = [];

	if (!empty($data_group) && is_array($data_group)) {
		foreach ($data_group as $row) {
			$name_clean = stripslashes($row->name ?? '');
			$wa_clean = stripslashes($row->whatsapp ?? '');
			$sapaan_clean = stripslashes($row->sapaan ?? '');

			$button_action = '<div class="btn-group" role="group"><button type="button" class="btn btn-outline-light edit_data" data-id="' . intval($row->id) . '" data-gid="' . intval($row->group_id) . '" title="Edit Data" style="border-top-right-radius:0;border-bottom-right-radius:0;"><i class="mr-2" data-lucide="pencil" style="margin: 0 4px 0 2px !important;color:#7680FF"></i></button><button type="button" class="btn btn-outline-light del_data" data-id="' . intval($row->id) . '" data-name="' . esc_attr($name_clean) . '" data-whatsapp="' . esc_attr($wa_clean) . '" data-sapaan="' . esc_attr($sapaan_clean) . '" title="Delete"><i class="mr-2" data-lucide="trash-2" style="margin: 0 4px 0 2px !important;color:#EF4D56"></i></button></div>';

			$data_rows[] = [
				'no'       => '<span data-id="' . intval($row->id) . '">' . $no . '</span>',
				'name'     => esc_html($name_clean),
				'whatsapp' => esc_html($wa_clean),
				'sapaan'   => esc_html($sapaan_clean),
				'action'   => $button_action,
			];
			$no++;
		}
	}

	while (ob_get_level() > 0) {
		ob_end_clean();
	}

	wp_send_json([
		'draw'            => $draw,
		'recordsTotal'    => $jumlah_total,
		'recordsFiltered' => $jumlah_total,
		'data'            => $data_rows,
	]);

}

