function dyk_get_campaigns(){

	set_time_donasiaja();

	global $wpdb;

    $table_name = $wpdb->prefix . "dyk_campaign";
    $table_name2 = $wpdb->prefix . "dyk_category";
    $table_name3 = $wpdb->prefix . "dyk_campaign_update";
    $table_name4 = $wpdb->prefix . "dyk_donate";
    $table_name5 = $wpdb->prefix . "dyk_settings";
    $table_name6 = $wpdb->prefix . "dyk_users";
    $table_name7 = $wpdb->prefix . "dyk_payment_list";
    $table_name8 = $wpdb->prefix . "users";

    $table_name9 = $wpdb->prefix . "dyk_group_list";
    $table_name10 = $wpdb->prefix . "dyk_group_data";

    $startlist 	  = isset($_POST['start']) ? intval($_POST['start']) : 0;
    $length 	  = isset($_POST['length']) ? intval($_POST['length']) : 10;
    $draw 		  = isset($_POST['draw']) ? intval($_POST['draw']) : 1;
    $group_id 	  = isset($_POST['group_id']) ? intval($_POST['group_id']) : 0;
    $search_value = isset($_POST['search']['value']) ? sanitize_text_field($_POST['search']['value']) : '';

    $limit = '';
    if($length > 0){
		$limit = "LIMIT $startlist,$length";
	}

	$current_user_id = get_current_user_id();
	$cap = get_user_meta( $current_user_id, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = is_array($cap) ? array_keys($cap) : [];
    $role = $roles[0] ?? 'administrator';
    $id_login = $current_user_id;

    $search_esc = '%' . $wpdb->esc_like($search_value) . '%';

    if($role=='donatur'){
    	$search_filter = '';
	    if($search_value!=''){
	    	$search_filter = $wpdb->prepare("and (title like %s or slug like %s)", $search_esc, $search_esc);
	    }

        $rows = $wpdb->get_results($wpdb->prepare("SELECT * from $table_name where user_id=%d $search_filter ORDER BY id DESC $limit", $id_login));
        $rows_all = $wpdb->get_results($wpdb->prepare("SELECT * from $table_name where user_id=%d $search_filter ORDER BY id DESC", $id_login));

        $nominal_donasi_terkumpul = 0;
        $jumlah_donasi_terkumpul = 0;
        if (!empty($rows)) {
            foreach ($rows as $value) {
                $total_donasi = $wpdb->get_results($wpdb->prepare("SELECT SUM(nominal) as total, COUNT(id) as jumlah FROM $table_name4 where campaign_id=%s and status='1' ", $value->campaign_id));
                $nominal_donasi_terkumpul += isset($total_donasi[0]->total) ? floatval($total_donasi[0]->total) : 0;
                $jumlah_donasi_terkumpul += isset($total_donasi[0]->jumlah) ? intval($total_donasi[0]->jumlah) : 0;
            }
        }

        $jumlah_donasi_semua = 0;
        if (!empty($rows)) {
            foreach ($rows as $value) {
                $total_donasi = $wpdb->get_results($wpdb->prepare("SELECT SUM(nominal) as total, COUNT(id) as jumlah FROM $table_name4 where campaign_id=%s ", $value->campaign_id));
                $jumlah_donasi_semua += isset($total_donasi[0]->jumlah) ? intval($total_donasi[0]->jumlah) : 0;
            }
        }

        if($jumlah_donasi_semua>=1){
            $konversi = $jumlah_donasi_terkumpul/$jumlah_donasi_semua;
        }else{
            $konversi = 0;
        }

    }else{

    	$search_filter = '';
	    if($search_value!=''){
	    	$search_filter = $wpdb->prepare("where (title like %s or slug like %s)", $search_esc, $search_esc);
	    }

        $rows = $wpdb->get_results("SELECT * from $table_name $search_filter ORDER BY id DESC $limit");
        $rows_all = $wpdb->get_results("SELECT * from $table_name $search_filter ORDER BY id DESC");

        $total_donasi = $wpdb->get_results("SELECT SUM(nominal) as total, COUNT(id) as jumlah FROM $table_name4 where status='1' ");
        $nominal_donasi_terkumpul = isset($total_donasi[0]->total) ? floatval($total_donasi[0]->total) : 0;
        $jumlah_donasi_terkumpul = isset($total_donasi[0]->jumlah) ? intval($total_donasi[0]->jumlah) : 0;

        $total_donasi_semua = $wpdb->get_results("SELECT COUNT(id) as jumlah FROM $table_name4 ");
        $jumlah_donasi_semua = isset($total_donasi_semua[0]->jumlah) ? intval($total_donasi_semua[0]->jumlah) : 0;

        if($jumlah_donasi_semua>=1){
            $konversi = $jumlah_donasi_terkumpul/$jumlah_donasi_semua;
        }else{
            $konversi = 0;
        }

    }

    $jumlah_donasi_waiting = $jumlah_donasi_semua-$jumlah_donasi_terkumpul;

    $konversi = $konversi*100;
    $konversi = number_format($konversi,1,",",".").' %';

 	// category
    $row2 = $wpdb->get_results('SELECT * from '.$table_name2.' '); 

    // GET CAMPAIGN ACTIVE
    $active_campaign = 0;

    if (!empty($rows_all) && is_array($rows_all)) {
        foreach ($rows_all as $row) {
            $date_now = date('Y-m-d');
            $datetime1 = new DateTime($date_now);

            // Check if end_date is a valid date string
            if (!empty($row->end_date)) {
                $datetime2 = new DateTime($row->end_date);
            } else {
                $datetime2 = new DateTime('9999-12-31');
            }

            $hasil = $datetime1->diff($datetime2);

            if ($hasil->invert == true && $row->publish_status == 1) {
                // Ended
            } else {
                if ($row->publish_status == 1) {
                    $active_campaign++;
                }
            }
        }
    }

    $query_settings2 = $wpdb->get_results('SELECT type, data from '.$table_name5.' where type="page_donate" or type="currency"');
    $settings_map = [];
    if (!empty($query_settings2) && is_array($query_settings2)) {
        foreach ($query_settings2 as $s) {
            $settings_map[$s->type] = $s->data;
        }
    }
    $page_donate  = $settings_map['page_donate'] ?? '';
    $currency     = $settings_map['currency'] ?? 'IDR';
    
    $show_currency = donasiyuk_currency($currency);
    $show_currency2 = donasiyuk_currency2($currency);

	$no = 1+$startlist;
	$jumlah_total = is_array($rows_all) ? count($rows_all) : 0;
	$data_rows = [];

	if (!empty($rows) && is_array($rows)) {
		foreach ($rows as $row) {

			$info_updatenya = $wpdb->get_results($wpdb->prepare('SELECT COUNT(id) as jumlah from '.$table_name3.' where campaign_id=%s', $row->campaign_id));
            $jumlah_info_update = isset($info_updatenya[0]->jumlah) ? intval($info_updatenya[0]->jumlah) : 0;

            // GET TOTAL DONASI
            $total_donasi = $wpdb->get_results($wpdb->prepare("SELECT SUM(nominal) as total, COUNT(id) as jumlah FROM $table_name4 where campaign_id=%s and status='1' ", $row->campaign_id));
            if(empty($total_donasi)){
                $total_terkumpul = 0;
                $jumlah_donasi = 0;
            }else{
                $total_terkumpul = floatval($total_donasi[0]->total ?? 0);
                $jumlah_donasi = intval($total_donasi[0]->jumlah ?? 0);
            }

            // Persen
            $row_target = floatval($row->target ?? 0);
            if($row_target <= 0){
                $persen = '100%';
            }else{
                $persen_num = ($total_terkumpul / $row_target) * 100;
                $persen = number_format($persen_num, 0, ",", ".") . '%';
            }

            // Nama Campaigner
            $args2 = array( 'blog_id' => 0, 'search' => $row->user_id, 'search_columns' => array( 'ID' ) );
            $get_name = get_users( $args2 );

            if(empty($get_name)){
                $campaigner_name = '-';
            }else{
                $nama_user = str_replace("'", "", $get_name[0]->display_name);
                $campaigner_name = $nama_user;
            }

            // Publish Status
            if($row->publish_status==0){
                $pub_status = 'Draft';
            }elseif($row->publish_status==1){
                $pub_status = 'Published';
            }elseif($row->publish_status==2){
                $pub_status = 'Pending Review';
            }elseif($row->publish_status==3){
                $pub_status = 'Archived';
            }elseif($row->publish_status==4){
                $pub_status = 'Unlisted';
            }else{
                $pub_status = '';
            }
            
            $date_now = date('Y-m-d');
            $datetime1 = new DateTime($date_now);

            if (!empty($row->end_date) && is_string($row->end_date)) {
                $datetime2 = new DateTime($row->end_date);
            } else {
                $datetime2 = new DateTime($date_now);
            }

            $hasil = $datetime1->diff($datetime2);
            
            $year = $hasil->y;
            $month = $hasil->m;
            $day = $hasil->d;

            if (!empty($row->end_date) && is_string($row->end_date)) {
                $datenya = date("F j, Y", strtotime($row->end_date));
            } else {
                $datenya = '';
            }

            $datenya = str_replace(' ', '&nbsp;', $datenya);

			if($year!=0){
			    if($hasil->invert==true){
			        $sisa_waktu = $datenya."<br><span style='font-size:9px;color: #f05860;'>(&nbsp;".$year."&nbsp;tahun,&nbsp;" .$month."&nbsp;bulan,&nbsp;" .$day."&nbsp;lalu&nbsp;)</span>";
			    }else{
			        $sisa_waktu = $datenya."<br><span style='font-size:9px;'>(&nbsp;".$year."&nbsp;tahun,&nbsp;" .$month."&nbsp;bulan,&nbsp;" .$day."&nbsp;lagi&nbsp;)</span>";
			    }
			}else{
			    if($month!=0){
			        if($hasil->invert==true){
			            $sisa_waktu = $datenya."<br><span style='font-size:9px;color: #f05860;'>(&nbsp;".$month."&nbsp;bulan,&nbsp;" .$day."&nbsp;hari&nbsp;lalu&nbsp;)</span>";
			        }else{
			            $sisa_waktu = $datenya."<br><span style='font-size:9px;'>(&nbsp;".$month."&nbsp;bulan,&nbsp;" .$day."&nbsp;hari&nbsp;lagi&nbsp;)</span>";
			        }
			    }else{
			        if($day==0 && $hasil->days==0){
			            $sisa_waktu = $datenya."<br><span style='font-size:9px;'>(&nbsp;hari&nbsp;ini&nbsp;)</span>";
			        }else{
			            if($hasil->invert==true){
			                $sisa_waktu = $datenya."<br><span style='font-size:9px;font-style:italic;color:#f05860;'>(&nbsp;sudah&nbsp;berakhir&nbsp;)</span>";
			            }else{
			                $sisa_waktu = $datenya."<br><span style='font-size:9px;'>(&nbsp;".$day."&nbsp;hari&nbsp;lagi&nbsp;)</span>";
			            }
			        }
			    }
			}

			if(empty($row->end_date)){
				$sisa_waktu = "<span>&nbsp;<i data-lucide='infinity'></i>&nbsp;</span><br>&nbsp;";
			}

			if($hasil->invert==true && $row->publish_status==1){
			    $act_status = "<span class='active-status' style='background:#F05860;'>Ended</span>";
			}else{
			    if($row->publish_status==1){
			        $act_status = "<span class='active-status'>Active</span>";
