			if ($role == 'administrator') {
			    $button_edit = "<div class='box-button button-hide'><div class='btn-group mb-2 mt-2' role='group' aria-label='Basic example'><a href='javascript:;'><button type='button' class='btn btn-outline-light no-border edit-campaigner' data-rowid='{$row->id}' data-act='edit' data-campaignid='{$row->campaign_id}'>Edit</button></a></div></div>";
