			$campaign_title = "<span class='campaign-title'><a href='" . admin_url('admin.php?page=donasiyuk_data_campaign&action=edit&id=') . $row->campaign_id . "'>" . esc_html(wp_strip_all_tags($row->title)) . "</a></span><div style='padding-top:10px;padding-bottom:5px;'>" . $act_status . " " . $category_name . "</div>";

			$campaign_button = "<div class='box-button button-hide'><div class='btn-group mb-2 mt-2' role='group' aria-label='Basic example'>"; 
			if($role != 'cs') { 
			    $campaign_button .= "<a href='" . admin_url('admin.php?page=donasiyuk_data_campaign&action=edit&id=') . $row->campaign_id . "'><button type='button' class='btn btn-outline-light btn_act no-border' data-act='edit' data-link='" . admin_url('admin.php?page=donasiyuk_data_campaign&action=edit&id=') . $row->campaign_id . "'>Edit</button></a><button type='button' class='btn btn-outline-light btn_act no-border' data-act='clone' data-cid='" . esc_attr($row->campaign_id) . "'>Clone</button>"; 
			} 
			if($row->publish_status == 1 || $row->publish_status == 4) { 
