			} else { 
			    $campaign_button .= "<a href='" . get_site_url() . "/preview/" . esc_attr($row->slug) . "' target='_blank'><button type='button' class='btn btn-outline-light btn_act no-border' data-act='preview1' data-link='" . get_site_url() . "/preview/" . esc_attr($row->slug) . "'>Preview</button></a>"; 
			} 
			$campaign_button .= "<a href='" . get_site_url() . "/campaign/" . esc_attr($row->slug) . "/" . esc_attr($page_donate) . "' target='_blank'><button type='button' class='btn btn-outline-light btn_act no-border' data-act='form1' data-link='" . get_site_url() . "/campaign/" . esc_attr($row->slug) . "/" . esc_attr($page_donate) . "' data-status='" . esc_attr($row->publish_status) . "'>Form</button></a>"; 
			if($role != 'cs') { 
			    $campaign_button .= "<a href='" . admin_url('admin.php?page=donasiyuk_data_campaign&action=cs_statisctic&id=') . $row->campaign_id . "&date=all&range=0'><button type='button' class='btn btn-outline-light btn_act no-border' data-act='statistic' data-link='" . admin_url('admin.php?page=donasiyuk_data_campaign&action=cs_statisctic&id=') . $row->campaign_id . "&date=all&range=0' data-status='" . esc_attr($row->publish_status) . "'>CS</button></a>"; 
			} 
			$campaign_button .= "</div></div>";

			$campaign_options = "<div class='float-right d-flex justify-content-between'>";
			if ($role == 'administrator') { 
			    $campaign_options .= "<div class='btn-group ml-1 option_campaign'><button type='button' class='btn btn-sm btn-outline-primary waves-light waves-effect dropdown-toggle' data-toggle='dropdown' aria-expanded='true'>Shortcode<i class='ml-1' data-lucide='chevron-down'></i></button><div class='dropdown-menu dropdown-menu-left' style='margin-left:-60px;margin-top:5px;'>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=full_card]' title='Copy Shortcode'>Card Campaign</a>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=full_list]' title='Copy Shortcode'>List Campaign</a>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=short_form]' title='Copy Shortcode'>Short Form 1</a>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=short_form title_image=true]' title='Copy Shortcode'>Short Form 2</a>";
			    $campaign_options .= "<div class='dropdown-divider'></div>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=" . get_langArray('shortcode_1') . "]' title='Copy Shortcode'>" . get_langArray('campaign_op1') . "</a>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=" . get_langArray('shortcode_2') . "]' title='Copy Shortcode'>" . get_langArray('campaign_op2') . "</a>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=" . get_langArray('shortcode_3') . "]' title='Copy Shortcode'>" . get_langArray('campaign_op3') . "</a>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=info]' title='Copy Shortcode'>Info Campaign</a>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=info_update]' title='Copy Shortcode'>Info Update</a>";
			    $campaign_options .= "<a class='dropdown-item copy_shortcode' href='javascript:;' data-shortcode='[donasiyuk_campaign id=" . esc_attr($row->campaign_id) . " show=" . get_langArray('shortcode_4') . "]' title='Copy Shortcode'>" . get_langArray('campaign_op4') . "</a>";
			    $campaign_options .= "</div></div>";
			}
			$campaign_options .= "<div class='btn-group ml-1 option_campaign'><button type='button' class='btn btn-sm btn-outline-primary waves-light waves-effect dropdown-toggle' data-toggle='dropdown' aria-expanded='true'>Option<i class='ml-1' data-lucide='chevron-down'></i></button><div class='dropdown-menu dropdown-menu-left'  style='margin-left:-80px;margin-top:5px;'>";
			if ($role != 'cs') { 
			    $campaign_options .= "<a class='dropdown-item btn_act no-border' data-act='edit' data-link='" . admin_url('admin.php?page=donasiyuk_data_campaign&action=edit&id=') . $row->campaign_id . "' href='javascript:;'>" . get_langArray('campaign_title4') . "</a>";
			    $campaign_options .= "<a class='dropdown-item btn_act' data-act='info' data-link='" . admin_url('admin.php?page=donasiyuk_data_campaign&action=info_update&id=') . $row->campaign_id . "' href='javascript:;'>Add Info Update (" . $jumlah_info_update . ")</a>";
			}
			$campaign_options .= "<a class='dropdown-item btn_act' data-act='info' data-link='" . admin_url('admin.php?page=donasiyuk_dashboard&id=') . $row->campaign_id . "' href='javascript:;'>" . get_langArray('campaign_op5') . "</a>";
			if ($role == 'donatur') { 
			    if ($row->publish_status != 1 && $role != 'cs') { 
			        $campaign_options .= "<div class='dropdown-divider'></div><a class='dropdown-item btn_act delete_campaign' href='javascript:;' data-act='del' data-id='" . intval($row->id) . "' data-campaignid='" . esc_attr($row->campaign_id) . "'>Delete</a>";
			    }
			} else { 
			    if ($role != 'cs') { 
			        $campaign_options .= "<div class='dropdown-divider'></div><a class='dropdown-item btn_act delete_data_donasi' href='javascript:;' data-act='del_data' data-id='" . intval($row->id) . "' data-campaignid='" . esc_attr($row->campaign_id) . "'>Delete Data</a>";
			        $campaign_options .= "<a class='dropdown-item btn_act delete_campaign' href='javascript:;' data-act='del' data-id='" . intval($row->id) . "' data-campaignid='" . esc_attr($row->campaign_id) . "'>Delete All</a>";
			    }
			}
			$campaign_options .= "</div></div></div>";

			$data_rows[] = [
				'no'         => '<span data-id="' . intval($row->id) . '">' . $no . '</span>',
				'cover'      => $cover,
				'campaign'   => $campaign_title . $campaign_button,
				'target'     => $show_currency2 . $targetnya,
				'terkumpul'  => $show_currency2 . number_format_currency($total_terkumpul),
				'end_date'   => $sisa_waktu,
				'campaigner' => '<span class="campaigner">' . esc_html($campaigner_name) . '</span>' . $button_edit,
				'action'     => $campaign_options,
			];

            $no++;
        }
    }

	while (ob_get_level() > 0) {
		ob_end_clean();
	}

	wp_send_json([
		'draw'                  => $draw,
		'recordsTotal'          => $jumlah_total,
		'recordsFiltered'       => $jumlah_total,
		'nominalDonasiTerkumpul' => $show_currency2 . number_format_currency($nominal_donasi_terkumpul),
		'jumlahDonasiSemua'     => number_format_currency($jumlah_donasi_semua),
		'jumlahDonasiTerkumpul' => number_format_currency($jumlah_donasi_terkumpul),
		'jumlahDonasiWaiting'   => number_format_currency($jumlah_donasi_waiting),
		'activeCampaign'        => $active_campaign,
		'data'                  => $data_rows,
	]);

}

