function dyk_get_data_fundraising(){

	global $wpdb;
	donasiyuk_global_vars();
    $table_name = $wpdb->prefix . "dyk_campaign";
    $table_name2 = $wpdb->prefix . "dyk_category";
    $table_name3 = $wpdb->prefix . "dyk_campaign_update";
    $table_name4 = $wpdb->prefix . "dyk_donate";
    $table_name5 = $wpdb->prefix . "dyk_settings";
    $table_name6 = $wpdb->prefix . "dyk_users";
    $table_name7 = $wpdb->prefix . "dyk_payment_list";
    $table_name8 = $wpdb->prefix . "dyk_aff_code";
    $table_name9 = $wpdb->prefix . "dyk_aff_submit";
    $table_name10 = $wpdb->prefix . "dyk_aff_click";
    $table_name11 = $wpdb->prefix . "dyk_aff_payout";
    $table_name12 = $wpdb->prefix . "users";


    $startlist 	  = $_POST['start'];
    $length 	  = $_POST['length'];
    $draw 		  = $_POST['draw'];
    $c_id 		  = $_POST['c_id'];
    $date_filter  = $_POST['date_filter'];
    $date_range   = $_POST['date_range'];
    $search_value = $_POST['search']['value'];
    $set_as_user  = !empty($_POST['as_user']);

    $limit = '';
    if($length==-1){
		$limit = '';
	}else{
		$limit = "LIMIT $startlist,$length";
	}

	// $search_filter = '';
    if($search_value!=''){

    	if($set_as_user==true) {

    		$data_campaignnya = $wpdb->get_results('SELECT id from '.$table_name.' where title like "%'.$search_value.'%"');
    		if($data_campaignnya!=null){
    			$s_id = $data_campaignnya[0]->id;
    		}else{
    			$s_id = 0;
    		}

    	}else{

	    	$search_user = false;
	    	$search_campaign = false;

			$data_usernya = $wpdb->get_results('SELECT ID from '.$table_name12.' where display_name like "%'.$search_value.'%"');
			if($data_usernya!=null){
				$id_user_search = $data_usernya[0]->ID;
				$search_user = true;
			}else{
				$data_campaignnya = $wpdb->get_results('SELECT id from '.$table_name.' where title like "%'.$search_value.'%"');
	    		if($data_campaignnya!=null){
	    			$s_id = $data_campaignnya[0]->id;
	    		}else{
	    			$s_id = 0;
	    		}
	    		$search_campaign = true;
			}


    	}
    	
    	
    }
    

    // ROLE
    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0];

    $id_login = wp_get_current_user()->ID;

    $akses = 1;
    if($role=='donatur'){
        $usernya = $wpdb->get_results('SELECT * from '.$table_name6.' where user_id="'.$id_login.'"')[0];

        if($usernya->user_verification=='1'){
            $akses = 1;
        }else{
            $akses = 0;
        }
    }

    if($set_as_user=='1'){
        $as_user = true;
    }else{
        $as_user = false;
    }

    if(isset($_GET['ref'])){
        if($_GET['ref']!=""){
            $show_referral = true;
        }else{
            $show_referral = false;
        }
    }else{
        $show_referral = false;
    }

    // category
    $row2 = $wpdb->get_results('SELECT * from '.$table_name2.' ');     

    // Settings
    $query_settings = $wpdb->get_results('SELECT data from '.$table_name5.' where type="form_setting" or type="app_name" or type="page_donate" or type="fundraiser_on"  or type="fundraiser_commission_on" or type="min_payout_setting" or type="min_payout"ORDER BY id ASC');
    $form_setting   = $query_settings[0]->data;
    $app_name       = $query_settings[1]->data;
    $page_donate    = $query_settings[2]->data;
    $fundraiser_on  = $query_settings[3]->data;
    $fundraiser_commission_on    = $query_settings[4]->data;
    $min_payout_setting = $query_settings[5]->data;
    $min_payout      = $query_settings[6]->data;

    // Currency
    $query_currency = $wpdb->get_results('SELECT data from '.$table_name5.' where type="currency"  ORDER BY id ASC');
    $currency = $query_currency[0]->data;
    $lang = get_data_lang($currency);
    $langArray = require_once(ROOTDIR_DYK . 'library/locale/'.$lang.'.php');
    
    $show_currency = donasiyuk_currency($currency);
    $show_currency2 = donasiyuk_currency2($currency);


    // ************************************
    if($role=='administrator'){

        if($as_user==true) {

        	if($search_value!=''){

        		$rows_aff = $wpdb->get_results("SELECT a.id, a.campaign_id, a.aff_code, a.user_id as fundraiser_id, c.user_randid, c.user_pp_img from $table_name8 a 
	            left JOIN $table_name6 c ON a.user_id = c.user_id
	            left JOIN $table_name d ON a.campaign_id = d.campaign_id
	            where a.user_id=$id_login and d.id=$s_id
	            ORDER BY a.id DESC $limit");

	            $jumlah_total = $wpdb->get_results("
	                SELECT count(a.id) as idnya from $table_name8 a 
	            left JOIN $table_name6 c ON a.user_id = c.user_id
	            left JOIN $table_name d ON a.campaign_id = d.campaign_id
