                    $the_campaign = "<a href='".admin_url("admin.php?page=donasiyuk_data_fundraising").$ref2."' target='_self'><img src='".esc_url($image_url_campaign)."' alt='' class='thumb-cover' style='width:45px;margin-bottom:5px;height:auto;'></a><a href='".admin_url("admin.php?page=donasiyuk_data_fundraising").$ref2."&as=user' target='_self' style='display:flex;margin-top:-32px;margin-left:57px;'>".esc_html($title_campaign)."</a>";
                    $the_link = "<a href='".admin_url("admin.php?page=donasiyuk_data_fundraising").$ref2."' target='_self'>";
                }else{
                	$the_campaign = "<a href='".admin_url("admin.php?page=donasiyuk_data_fundraising").$ref2."' target='_self'><img src='".esc_url($image_url_campaign)."' alt='' class='thumb-cover' style='width:45px;margin-bottom:5px;height:auto;'></a><a href='".admin_url("admin.php?page=donasiyuk_data_fundraising").$ref2."' target='_self' style='display:flex;margin-top:-32px;margin-left:57px;'>".esc_html($title_campaign)."</a>";
                	$the_link = "<a href='".admin_url("admin.php?page=donasiyuk_data_fundraising").$ref2."' target='_self'>";
                }
                
            }

            if(empty($row->fundraiser_id)){
                $fundraiser = "No Name";
            }else{
                $user_info2 = get_userdata($row->fundraiser_id);
                if(!empty($user_info2)){
                    $fundraiser = "<a href='".get_site_url()."/profile/".esc_attr($row->user_randid ?? '')."' target='_blank'>".esc_html(($user_info2->first_name ?? '')." ".($user_info2->last_name ?? ''))."</a>";
                }else{
                    $fundraiser = "No Name";
                }
            }

            $count_click = $wpdb->get_results($wpdb->prepare("SELECT COUNT(id) as total_click FROM $table_name10 where affcode_id=%d", $row->id));
            $total_click = isset($count_click[0]->total_click) ? intval($count_click[0]->total_click) : 0;

            $count_submit = $wpdb->get_results($wpdb->prepare("SELECT COUNT(id) as total_submit FROM $table_name9 where affcode_id=%d", $row->id));
            $total_submit = isset($count_submit[0]->total_submit) ? intval($count_submit[0]->total_submit) : 0;

            $count_submit2 = $wpdb->get_results($wpdb->prepare("SELECT COUNT(a.id) as total_submit, b.status, SUM(b.nominal) as total_donate, SUM(a.nominal_commission) as nominal_commission FROM $table_name9 a 
                left JOIN $table_name4 b ON b.id = a.donate_id
                where a.affcode_id=%d and b.status='1'", $row->id));

            $count_submit3 = $wpdb->get_results($wpdb->prepare("SELECT SUM(a.nominal_commission) as nominal_commission FROM $table_name9 a 
                left JOIN $table_name4 b ON b.id = a.donate_id
                where a.affcode_id=%d and b.status='1' and a.payout_status='0'", $row->id));

            $count_submit4 = $wpdb->get_results($wpdb->prepare("SELECT SUM(a.nominal_commission) as nominal_commission FROM $table_name9 a 
                left JOIN $table_name4 b ON b.id = a.donate_id
                where a.affcode_id=%d and b.status='1' and a.payout_status='1'", $row->id));

            $count_submit5 = $wpdb->get_results($wpdb->prepare("SELECT SUM(a.nominal_commission) as nominal_commission FROM $table_name9 a 
                left JOIN $table_name4 b ON b.id = a.donate_id
                where a.affcode_id=%d and b.status='1' and a.payout_status='2'", $row->id));

            $total_submit2 = isset($count_submit2[0]->total_submit) ? intval($count_submit2[0]->total_submit) : 0;
            $total_donate = isset($count_submit2[0]->total_donate) ? floatval($count_submit2[0]->total_donate) : 0;
            $total_nominal_commission = isset($count_submit2[0]->nominal_commission) ? floatval($count_submit2[0]->nominal_commission) : 0;

            $total_belum_dicairkan = isset($count_submit3[0]->nominal_commission) ? floatval($count_submit3[0]->nominal_commission) : 0;
            $total_sudah_dicairkan = isset($count_submit4[0]->nominal_commission) ? floatval($count_submit4[0]->nominal_commission) : 0;
            $total_on_process = isset($count_submit5[0]->nominal_commission) ? floatval($count_submit5[0]->nominal_commission) : 0;
           
            $copy_link_button = "<button type='button' class='btn btn-outline-primary waves-effect waves-light btn-sm copy_link_aff' title='Copy' data-link='".get_site_url()."/campaign/".esc_attr($slug_campaign).$ref."'>Copy&nbsp;Link</button>";

            if($fundraiser_commission_on=='1'){
            	$data_rows[] = [
			      "no"                => "<span data-id='campaign__".intval($row->id)."'>".$no."</span>",
			      "fundraiser"        => $fundraiser,
			      "campaign"          => $the_campaign,
			      "view"              => $the_link.$total_click."&nbsp;&nbsp;:&nbsp;&nbsp;".$total_submit."&nbsp;&nbsp;:&nbsp;&nbsp;".$total_submit2."</a>",
			      "total_fundraising" => $show_currency2.number_format_currency($total_donate),
			      "komisi"            => $show_currency2.number_format_currency($total_nominal_commission),
			      "belum_cair"        => $show_currency2.number_format_currency($total_belum_dicairkan),
			      "proses_cair"       => $show_currency2.number_format_currency($total_on_process),
			      "sudah_cair"        => $show_currency2.number_format_currency($total_sudah_dicairkan),
			  	  "action"            => $copy_link_button
            	];
            }else{
            	$data_rows[] = [
			      "no"                => "<span data-id='campaign__".intval($row->id)."'>".$no."</span>",
			      "fundraiser"        => $fundraiser,
			      "campaign"          => $the_campaign,
			      "view"              => $the_link.$total_click."&nbsp;&nbsp;:&nbsp;&nbsp;".$total_submit."&nbsp;&nbsp;:&nbsp;&nbsp;".$total_submit2."</a>",
			      "total_fundraising" => $show_currency2.number_format_currency($total_donate),
			  	  "action"            => $copy_link_button
            	];
            }

            $no++;
		}
	}

	while (ob_get_level() > 0) {
		ob_end_clean();
	}

	wp_send_json([
		'draw'               => $draw,
		'recordsTotal'       => $jumlah_total,
		'recordsFiltered'    => $jumlah_total,
		'totalFundraising'   => $totalFundraising,
		'komisiFundraising'  => $komisiFundraising,
		'komisiCair'         => $komisiCair,
		'komisiProsesCair'   => $komisiProsesCair,
		'komisiBelumCair'    => $komisiBelumCair,
		'successFundraising' => $successFundraising,
		'linkFundraising'    => $linkFundraising,
		'data'               => $data_rows,
	]);

}

