function dyk_get_data_fundraising_on_process(){

	global $wpdb;
	donasiyuk_global_vars();
    $table_name = $wpdb->prefix . "dyk_campaign";
    $table_name2 = $wpdb->prefix . "dyk_category";
    $table_name3 = $wpdb->prefix . "dyk_campaign_update";
    $table_name4 = $wpdb->prefix . "dyk_donate";
    $table_name5 = $wpdb->prefix . "dyk_settings";
    $table_name6 = $wpdb->prefix . "dyk_users";
    $table_name7 = $wpdb->prefix . "dyk_payment_list";
    $table_name8 = $wpdb->prefix . "dyk_aff_code";
    $table_name9 = $wpdb->prefix . "dyk_aff_submit";
    $table_name10 = $wpdb->prefix . "dyk_aff_click";
    $table_name11 = $wpdb->prefix . "dyk_aff_payout";

    $startlist 	  = isset($_POST['start']) ? intval($_POST['start']) : 0;
    $length 	  = isset($_POST['length']) ? intval($_POST['length']) : 10;
    $draw 		  = isset($_POST['draw']) ? intval($_POST['draw']) : 1;
    $c_id 		  = isset($_POST['c_id']) ? sanitize_text_field($_POST['c_id']) : '';
    $date_filter  = isset($_POST['date_filter']) ? sanitize_text_field($_POST['date_filter']) : '';
    $date_range   = isset($_POST['date_range']) ? sanitize_text_field($_POST['date_range']) : '';
    $search_value = isset($_POST['search']['value']) ? sanitize_text_field($_POST['search']['value']) : '';
    $set_as_user  = isset($_POST['as_user']) ? sanitize_text_field($_POST['as_user']) : '';
    $statusnya 	  = isset($_POST['statusnya']) ? intval($_POST['statusnya']) : 0;

    $limit = '';
    if($length > 0){
		$limit = "LIMIT $startlist,$length";
	}

	$search_filter = '';
    if($search_value!=''){
    	$search_esc = '%' . $wpdb->esc_like($search_value) . '%';
    	$search_filter = $wpdb->prepare("and (payout_number like %s or nominal_payout like %s or bank_name like %s or bank_no like %s or bank_an like %s) ", $search_esc, $search_esc, $search_esc, $search_esc, $search_esc);
    }

    $current_user_id = get_current_user_id();
    $cap = get_user_meta( $current_user_id, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = is_array($cap) ? array_keys($cap) : [];
    $role = $roles[0] ?? 'administrator';
    $id_login = $current_user_id;

    $as_user = ($set_as_user == '1');

    $raw_settings = $wpdb->get_results('SELECT type, data from '.$table_name5.' where type="form_setting" or type="app_name" or type="page_donate" or type="fundraiser_on" or type="fundraiser_commission_on" or type="min_payout_setting" or type="min_payout" or type="currency"');
    $settings_map = [];
    if (!empty($raw_settings) && is_array($raw_settings)) {
        foreach ($raw_settings as $s) {
            $settings_map[$s->type] = $s->data;
        }
    }
    $fundraiser_commission_on = $settings_map['fundraiser_commission_on'] ?? '';
    $currency                 = $settings_map['currency'] ?? 'IDR';

    $show_currency = donasiyuk_currency($currency);
    $show_currency2 = donasiyuk_currency2($currency);

    $data_rows = [];
    $jumlah_total = 0;

    if($fundraiser_commission_on=='1'){

        if($role=='administrator'){
            if($as_user==true) {
                $list_pencairan = $wpdb->get_results($wpdb->prepare("SELECT a.* from $table_name11 a 
                where a.user_id=%d and a.status=%d $search_filter
                ORDER BY a.id DESC $limit", $id_login, $statusnya));
                $jumlah_total = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(a.id) from $table_name11 a where a.user_id=%d and a.status=%d $search_filter", $id_login, $statusnya));
            }else{
                $list_pencairan = $wpdb->get_results($wpdb->prepare("SELECT a.* from $table_name11 a 
                where a.status=%d $search_filter
                ORDER BY a.id DESC $limit", $statusnya));
                $jumlah_total = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(a.id) from $table_name11 a where a.status=%d $search_filter", $statusnya));
            }
        }else{
            $list_pencairan = $wpdb->get_results($wpdb->prepare("SELECT a.* from $table_name11 a 
                where a.user_id=%d and a.status=%d $search_filter
                ORDER BY a.id DESC $limit", $id_login, $statusnya));
            $jumlah_total = (int) $wpdb->get_var($wpdb->prepare("SELECT COUNT(a.id) from $table_name11 a where a.user_id=%d and a.status=%d $search_filter", $id_login, $statusnya));
        }

        $no = 1 + $startlist;

        if (!empty($list_pencairan) && is_array($list_pencairan)) {
	        foreach ($list_pencairan as $row) {

	            $user_info = get_userdata($row->user_id);
	            $fundraiser = ($user_info ? ($user_info->first_name . '&nbsp;' . $user_info->last_name) : 'No Name');

	            if($row->status=='1'){
	                $statusnya_badge = "<span style='background:#DAF6F0;color: #22d969;padding: 5px 10px;font-size: 11px;border-radius: 2px;'>Paid</span>";
	            }else{
	                $statusnya_badge = "<span style='background:#FFEDC1;color: #ee9f09;padding: 5px 10px;font-size: 11px;border-radius: 2px;'>On&nbsp;Process</span>";
	            }

	            if(!empty($row->image)){
	                $imagenya = "<img src='".esc_url($row->image)."' class='img-ss' alt='' data-action='zoom'>";
	            }else{
	                $imagenya = "<img src='' class='img-ss' alt='' data-action='zoom'>";
	            }

	            $fundraiser = stripslashes($fundraiser);
	            $bank_name = stripslashes($row->bank_name ?? '');
	            $bank_an = stripslashes($row->bank_an ?? '');
	            $bank_no = stripslashes($row->bank_no ?? '');
	           
	            if($role=='donatur' || $as_user==true){
	            	$data_rows[] = [
				      "no"            => "<span data-id='payout_".intval($row->id)."'>".$no."</span>",
				      "date"          => date("Y-m-d H:i", strtotime($row->created_at)),
				      "payout_number" => esc_html($row->payout_number ?? ''),
				      "fundraiser"    => $fundraiser,
				      "nominal"       => $show_currency2 . number_format_currency($row->nominal_payout ?? 0),
				      "bank_account"  => esc_html($bank_name . ' - ' . $bank_no . ' - ' . $bank_an),
				      "status"        => "<span class='status_".intval($row->id)."'>".$statusnya_badge."</span>",
				      "ss_payment"    => "<span class='image-ss'>".$imagenya."</span>"
	            	];
	            }else{
	            	if($role=='administrator'){
	                    $action_button = "<div class='btn-group ml-1 option_campaign'><button type='button' class='btn btn-sm btn-outline-primary waves-light waves-effect dropdown-toggle' data-toggle='dropdown' aria-expanded='true'>Option<i class='ml-1' data-lucide='chevron-down'></i></button><div class='dropdown-menu dropdown-menu-left' style='position:absolute;transform:translate3d(-130.633px, 32.7167px, 0px);top:0px;left:46px;will-change:transform;' x-placement='bottom-end'><a class='dropdown-item edit_status' data-status='".esc_attr($row->status)."' data-idnya='".intval($row->id)."' href='javascript:;'>Edit Status</a><a class='dropdown-item no-border add_ss' data-idnya='".intval($row->id)."' href='javascript:;'>Add SS Payment</a><div class='dropdown-divider'></div><a href='javascript:;' class='dropdown-item btn_act no-border delete_payout delete_pencairan' data-idnya='".intval($row->id)."'>Delete</a></div></div>";

	                    $data_rows[] = [
					      "no"            => "<span data-id='payout_".intval($row->id)."'>".$no."</span>",
					      "date"          => date("Y-m-d H:i", strtotime($row->created_at)),
					      "payout_number" => esc_html($row->payout_number ?? ''),
					      "fundraiser"    => $fundraiser,
					      "nominal"       => $show_currency2 . number_format_currency($row->nominal_payout ?? 0),
					      "bank_account"  => esc_html($bank_name . ' - ' . $bank_no . ' - ' . $bank_an),
					      "status"        => "<span class='status_".intval($row->id)."'>".$statusnya_badge."</span>",
					      "ss_payment"    => "<span class='image-ss'>".$imagenya."</span>",
					  	  "action"        => $action_button
	                    ];
	            	}else{
	                    $data_rows[] = [
					      "no"            => "<span data-id='payout_".intval($row->id)."'>".$no."</span>",
					      "date"          => date("Y-m-d H:i", strtotime($row->created_at)),
					      "payout_number" => esc_html($row->payout_number ?? ''),
					      "fundraiser"    => $fundraiser,
					      "nominal"       => $show_currency2 . number_format_currency($row->nominal_payout ?? 0),
					      "bank_account"  => esc_html($bank_name . ' - ' . $bank_no . ' - ' . $bank_an),
					      "status"        => "<span class='status_".intval($row->id)."'>".$statusnya_badge."</span>",
					      "ss_payment"    => "<span class='image-ss'>".$imagenya."</span>"
	                    ];
	            	}
	            }

                $no++;
			}
		}
	}

	while (ob_get_level() > 0) {
		ob_end_clean();
	}

	wp_send_json([
		'draw'            => $draw,
		'recordsTotal'    => $jumlah_total,
		'recordsFiltered' => $jumlah_total,
		'data'            => $data_rows,
	]);

}

