function dyk_get_data_analytics(){

	set_time_donasiaja();

	global $wpdb;
    $table_name  = $wpdb->prefix . "dyk_campaign";
    $table_name2 = $wpdb->prefix . "dyk_category";
    $table_name3 = $wpdb->prefix . "dyk_campaign_update";
    $table_name4 = $wpdb->prefix . "dyk_donate";
    $table_name5 = $wpdb->prefix . "dyk_settings";
    $table_name6 = $wpdb->prefix . "dyk_users";
    $table_name7 = $wpdb->prefix . "users";
    $table_name8 = $wpdb->prefix . "dyk_payment_log";

    $startlist 	  = $_POST['start'];
    $length 	  = $_POST['length'];
    $draw 		  = $_POST['draw'];
    $c_id 		  = $_POST['c_id'];
    $date_filter  = $_POST['date_filter'];
    $date_range   = $_POST['date_range'];
    $search_value = $_POST['search']['value'];

    // Settings
    $raw_settings = $wpdb->get_results('SELECT type, data from '.$table_name5.' where type="form_setting" or type="btn_followup" or type="text_f1" or type="text_f2" or type="text_f3" or type="text_f4" or type="text_f5" or type="text_received" or type="text_received_status" or type="currency" or type="wanotif_on_dashboard" ORDER BY id ASC');
    $settings_map = [];
    if (!empty($raw_settings) && is_array($raw_settings)) {
        foreach ($raw_settings as $s) {
            $settings_map[$s->type] = $s->data;
        }
    }
    $form_setting = $settings_map['form_setting'] ?? '';
    $btn_followup = $settings_map['btn_followup'] ?? '';
    $text_f1 = $settings_map['text_f1'] ?? '';
    $text_f2 = $settings_map['text_f2'] ?? '';
    $text_f3 = $settings_map['text_f3'] ?? '';
    $text_f4 = $settings_map['text_f4'] ?? '';
    $text_f5 = $settings_map['text_f5'] ?? '';
    $text_received = $settings_map['text_received'] ?? '';
    $text_received_status = $settings_map['text_received_status'] ?? '';
    $currency = $settings_map['currency'] ?? 'IDR';
    $wanotif_on_dashboard = $settings_map['wanotif_on_dashboard'] ?? '';

    $show_currency = donasiyuk_currency($currency);

    $cap = get_user_meta( wp_get_current_user()->ID, $wpdb->get_blog_prefix() . 'capabilities', true );
    $roles = array_keys((array)$cap);
    $role = $roles[0] ?? 'administrator';
    $id_login = wp_get_current_user()->ID;


    if($c_id=='all'){
    	$c_id = null;
    }

    $limit = '';
    if($length==-1){
		$limit = '';
	}else{
		$limit = "LIMIT $startlist,$length";
	}


    $filternya = "";
    $filternya_graph = "";
    if($date_filter=='today' || $date_filter=='yesterday' || $date_filter=='7lastdays' || $date_filter=='30lastdays' || $date_filter=='thismonth' || $date_filter=='lastmonth' || $date_filter=='thisyear' || $date_filter=='lastyear' || $date_filter=='last2years' || $date_filter=='last3years' || $date_filter=='daterange' || $date_filter=='all'){
    
        // Date
        $today = date('Y-m-d');
        $yesterday = date("Y-m-d", strtotime("-1 day"));
        $one_week_ago = date("Y-m-d", strtotime("-7 day"));
        $one_month_ago = date("Y-m-d", strtotime("-30 day"));
        $three_months_ago = date("Y-m-d", strtotime("-90 day"));
        $thismonth = date("Y-m-01");
        $thisyear = date("Y-01-01");
        
        $month = date('m');
        $year = date('Y');
        if($month==1){
        	$monthnya = 12;
        	$yearnya = $year-1;
        }else{
        	$monthnya = $month-1;
        	$yearnya = $year;
        }
		$lastmonth_firstrange = date($yearnya."-".$monthnya."-01");
		$lastmonth_lastrange = date($yearnya."-".$monthnya."-31");

		if($date_range!=''){
			$date_range = explode('_',$date_range);
			$date_range_first = date($date_range[0]);
			$date_range_last = date($date_range[1]);
		}else{
			$date_range_first = $today;
			$date_range_last = $today;
		}

		// last year
		$lastyear_yearnya = $year-1;
		$lastyear_firstrange = date($lastyear_yearnya."-01-01");
		$lastyear_lastrange = date($lastyear_yearnya."-12-31");

		// 2 last year
		$twolastyear_yearnya = $year-2;
		$twolastyear_firstrange = date($twolastyear_yearnya."-01-01");
		$twolastyear_lastrange = date(($twolastyear_yearnya+1)."-12-31");

		// 3 last year
		$threelastyear_yearnya = $year-3;
		$threelastyear_firstrange = date($threelastyear_yearnya."-01-01");
		$threelastyear_lastrange = date(($threelastyear_yearnya+2)."-12-31");
		

        if($date_filter=='today'){
            $filternya_graph = "and created_at BETWEEN '$today 00:00' AND '$today 23:59'";
            $filternya 		 = "and a.created_at BETWEEN '$today 00:00' AND '$today 23:59'";
        }elseif($date_filter=='yesterday'){
            $filternya_graph = "and created_at BETWEEN '$yesterday 00:00' AND '$yesterday 23:59'";
            $filternya 		 = "and a.created_at BETWEEN '$yesterday 00:00' AND '$yesterday 23:59'";
        }elseif($date_filter=='7lastdays'){
            $filternya_graph = "and created_at BETWEEN '$one_week_ago 00:00' AND '$today 23:59'";
            $filternya = "and a.created_at BETWEEN '$one_week_ago 00:00' AND '$today 23:59'";
        }elseif($date_filter=='30lastdays'){
            $filternya_graph = "and created_at BETWEEN '$one_month_ago 00:00' AND '$today 23:59'";
            $filternya = "and a.created_at BETWEEN '$one_month_ago 00:00' AND '$today 23:59'";
        }elseif($date_filter=='3months'){
            $filternya_graph = "and created_at BETWEEN '$three_months_ago 00:00' AND '$today 23:59'";
            $filternya = "and a.created_at BETWEEN '$three_months_ago 00:00' AND '$today 23:59'";
        }elseif($date_filter=='thismonth'){
            $filternya_graph = "and created_at BETWEEN '$thismonth 00:00' AND '$today 23:59'";
