		'jumlahDonasi'           => $jumlahDonasi,
		'jumlahDonasiTerkumpul'  => $jumlahDonasiTerkumpul,
		'jumlahSuccess'          => number_format((float)($jumlah_donasi_terkumpul ?? 0), 0, ",", "."),
		'totalSuccessNominal'    => $show_currency . $totalDonasi,
		'jumlahWaiting'          => number_format((float)($jumlah_donasi_terkumpul_waiting ?? 0), 0, ",", "."),
		'totalWaitingNominal'    => $show_currency . $totalDonasiWaiting,
		'konversi'               => $konversi,
		'jumlahDesktop'          => $persen_desktop,
		'jumlahMobile'           => $persen_mobile,
		'averageDonationAmount'  => $show_currency . $average_donation_amount,
		'averagePaymentDuration' => $average_payment_duration,
		'dataUtm'                => $result ?? ['jumlah' => 0, 'data' => []],
		'dataGraphicTitle'       => $dataGraphicTitle,
		'dataGraphicSuccess'     => $dataGraphicSuccess,
		'dataGraphicWaiting'     => $dataGraphicWaiting,
		'data'                   => [],
	];

	wp_send_json($response);

}

