function get_aff_stat($type, $id_usernya){

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";
    $table_name2 = $wpdb->prefix . "dyk_aff_code";
    $table_name3 = $wpdb->prefix . "dyk_aff_click";
    $table_name4 = $wpdb->prefix . "dyk_aff_submit";

    if($type=='view'){
    	$total_click_and_view = (int) $wpdb->get_var(
		  $wpdb->prepare(
		    "SELECT COUNT(b.id)
		     FROM {$table_name2} a
		     LEFT JOIN {$table_name3} b ON a.id = b.affcode_id
		     WHERE a.user_id = %d",
		    $id_usernya
		  )
		);
		return $total_click_and_view;
    }
    
    if($type=='submit'){
		$total_click_and_submit = (int) $wpdb->get_var(
		  $wpdb->prepare(
		    "SELECT COUNT(b.id)
		     FROM {$table_name2} a
		     LEFT JOIN {$table_name4} b ON a.id = b.affcode_id
		     WHERE a.user_id = %d",
		    $id_usernya
		  )
		);
		return $total_click_and_submit;
	}

	if($type=='paid'){
		$total_click_submit_and_success = (int) $wpdb->get_var(
		  $wpdb->prepare(
		    "SELECT COUNT(b.id)
		     FROM {$table_name2} a
		     LEFT JOIN {$table_name4} b ON a.id = b.affcode_id
		     LEFT JOIN {$table_name} c ON b.donate_id = c.id
		     WHERE a.user_id = %d
	         AND c.status = %d",
		    $id_usernya,
		    1
		  )
		);
		return $total_click_submit_and_success;
	}

}


function get_payment_expired($invoice_id){

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";

	$donate = $wpdb->get_results('SELECT * from '.$table_name.' where invoice_id="'.$invoice_id.'" ');

	$pg = $donate[0]->payment_gateway;
	$pc = $donate[0]->payment_code;

	if($pg=='flip'){

		// Virtual Account	All Banks	24 Hours
		// Retail Store	Alfamart	24 Hours
		// Bank Transfer	All Banks	24 Hours

		// QRIS		1 Hour
		// E-Wallet	ShopeePay	1 Hour
		// E-Wallet	OVO	5 minutes
		// E-Wallet	LinkAja	5 minutes
		// E-Wallet	DANA	30 minutes
		// Card Payment	Credit Card	1 Hour

		$payment_date = $donate[0]->created_at;
		
		if($pc=='qris' || $pc=='shopeepay'){
			$time_plus = strtotime('+1 hour',strtotime($payment_date));
			$additional_info = ' (hanya 1 jam)';
		}elseif($pc=='ovo' || $pc=='linkaja'){
			$time_plus = strtotime('+5 minutes',strtotime($payment_date));
			$additional_info = ' (hanya 5 menit)';
		}elseif($pc=='dana'){
			$time_plus = strtotime('+30 minutes',strtotime($payment_date));
			$additional_info = ' (hanya 30 menit)';
		}else{
			$time_plus = strtotime('+24 hour',strtotime($payment_date));
			$additional_info = ' (24 jam)';
		}
	    
	    return date('d',$time_plus).' '.date('M',$time_plus).' '.date('Y',$time_plus).' - '.date('H:i',$time_plus).$additional_info;

	}else{
		$payment_date = $donate[0]->created_at;
	    $time_plus_24 = strtotime('+24 hour',strtotime($payment_date));
	    return date('d',$time_plus_24).' '.date('M',$time_plus_24).' '.date('Y',$time_plus_24).' - '.date('H:i',$time_plus_24).' (24 jam)';
	}

	

}



function get_payment_method($invoice_id){

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_donate";
    $table_name2 = $wpdb->prefix . "dyk_payment_log";

	$donate = $wpdb->get_results('SELECT * from '.$table_name.' where invoice_id="'.$invoice_id.'" ');
	if (empty($donate) || !isset($donate[0])) {
		return '';
	}

    $bank_code = $donate[0]->payment_code ?? '';
    $payment_account = $donate[0]->payment_account ?? '';
	$payment_number = $donate[0]->payment_number ?? '';
	$total = $donate[0]->nominal ?? 0;

    $data_field = array();
    $data_field[ '{payment_account}' ] = $payment_account;
    $data_field[ '{payment_number}' ] = $payment_number;
    $data_field[ '{nominal}' ] = $total;
    $data_field[ '<b>' ] = '*';
    $data_field[ '</b>' ] = '*';

	$file_path = plugin_dir_path( __FILE__ ) . "library/instructions.json";
	$array = [];
	if (file_exists($file_path)) {
		$json_str = file_get_contents($file_path);
		$array = json_decode($json_str, true);
	}
	if (!is_array($array)) {
		$array = [];
	}
	
	$method = '';
	$i = 0;
	$pg = $donate[0]->payment_gateway ?? '';
	$pm = $donate[0]->payment_method ?? '';

	foreach ($array as $arr_item) {
		if (!is_array($arr_item)) continue;
		$item_pg = $arr_item['pg'] ?? '';
		$item_payment = $arr_item['payment'] ?? '';

		if (!empty($pg)) {
			if ($item_pg !== 'general') {
				if ($item_pg === $pg && $item_payment === $bank_code) {
					foreach ($arr_item as $key => $val) {
						if (!in_array($key, ['pg', 'method', 'payment', 'steps'], true)) {
							$i++;
						}
					}
				}
			} else {
				if ($item_payment === $bank_code && $pm !== 'va') {
					foreach ($arr_item as $key => $val) {
						if (!in_array($key, ['pg', 'method', 'payment', 'steps'], true)) {
							$i++;
						}
					}
				}
			}
		} else {
			if ($item_pg === 'general' && $item_payment === $bank_code) {
				foreach ($arr_item as $key => $val) {
					if (!in_array($key, ['pg', 'method', 'payment', 'steps'], true)) {
						$i++;
					}
				}
			}
		}
	}

	if($i>=1){
		$method .= '*Instruksi Pembayaran :*';
	}

	if($pg=='flip' && $pm=='transfer'){
		return $method . '
✅ *Flip*
- Klik link flip di bawah
- Flip : '.$payment_number.'
- Lalu lanjutkan pembayaran hingga selesai
';
	}
	if($pg=='flip' && $pm=='instant'){
		return $method . '
✅ *Flip*
- Klik link flip di bawah
- Flip : '.$payment_number.'
- Lalu lanjutkan pembayaran hingga selesai
';
	}

	if($pg=='tripay'){
		$id_donate = $donate[0]->id;
		$payment_log = $wpdb->get_results('SELECT * from '.$table_name2.' where id_donate="'.$id_donate.'"');
		if(!empty($payment_log) && isset($payment_log[0]->log)){
			$hasil = $payment_log[0]->log;
			$data_log = json_decode($hasil);
			
			if (isset($data_log->data->instructions) && is_array($data_log->data->instructions)) {
				$tripay_instructions = $data_log->data->instructions;

				foreach ( $tripay_instructions as $value ) {
					$title = $value->title ?? '';
					$method .= '
✅ *'.$title.'*
';
					if (isset($value->steps) && is_array($value->steps)) {
						foreach ( $value->steps as $value2 ) {
							$value2 = str_replace(['<b>', '</b>'], '*', $value2);
							$method .= '- '.$value2.'
';
						}
					}
				}
			}
		}
	}else{
		foreach ($array as $arr_item) {
			if (!is_array($arr_item)) continue;
			$item_pg = $arr_item['pg'] ?? '';
			$item_payment = $arr_item['payment'] ?? '';

			if(!empty($pg)){ // ada code payment gateway
				
				// pakai yang selain general
				if($item_pg!='general'){
					if($item_pg==$pg && $item_payment==$bank_code){
						foreach ($arr_item as $key => $val) {
							if(in_array($key, ['pg', 'method', 'payment'], true)){
								// nothing
							}elseif($key=='steps' && is_array($val)){
								foreach ($val as $v) {
									$v = strtr($v, $data_field);
									$method .= '- '.$v.'
';
								}
							}else{
								$method .= '
✅ *'.$val.'*
';
							}
						}
					}
				}else{
					// pakai yang selain general kecuali VA
					if($item_payment==$bank_code && $pm!='va'){
						foreach ($arr_item as $key => $val) {
							if(in_array($key, ['pg', 'method', 'payment'], true)){
								// nothing
							}elseif($key=='steps' && is_array($val)){
								foreach ($val as $v) {
									$v = strtr($v, $data_field);
									$method .= '- '.$v.'
';
								}
							}else{
								$method .= '
✅ *'.$val.'*
';
							}
						}
					}
				}
				
			}else{
				// pakai yang general
				if($item_pg=='general' && $item_payment==$bank_code){
					foreach ($arr_item as $key => $val) {
						if(in_array($key, ['pg', 'method', 'payment'], true)){
							// nothing
						}elseif($key=='steps' && is_array($val)){
							foreach ($val as $v) {
								$v = strtr($v, $data_field);
								$method .= '- '.$v.'
';
							}
						}else{
							$method .= '
✅ *'.$val.'*
';
						}
					}
				}
			}
		}
	}
	
	return $method;
}


