function dyk_whatsapp_format($text){
	$set_div1 = str_replace('<br></div><div>','%0A',$text);
	$set_div2 = str_replace('</div><div>','%0A',$set_div1);
    $set_nbsp = str_replace('&nbsp;','',$set_div2);
	$set_b_1 = str_replace('<b>','*',$set_nbsp);
	$set_b_2 = str_replace('</b>','*',$set_b_1);
	$set_i_1 = str_replace('<i>','_',$set_b_2);
	$set_i_2 = str_replace('</i>','_',$set_i_1);
	$set_s_1 = str_replace('<strike>','~',$set_i_2);
	$set_s_2 = str_replace('</strike>','~',$set_s_1);
	$set_enter = str_replace('<br>','%0A',$set_s_2);
	return urlencode($set_enter);
}


function d_randomString($length) {
    $keys = array_merge(range(0,9), range('a', 'z'));

    $key = "";
    for($i=0; $i < $length; $i++) {
        $key .= $keys[mt_rand(0, count($keys) - 1)];
    }
    return $key;
}


function d_randomBigString($length) {
    $keys = array_merge(range(0,9), range('A', 'Z'));

    $key = "";
    for($i=0; $i < $length; $i++) {
        $key .= $keys[mt_rand(0, count($keys) - 1)];
    }
    return $key;
}



function d_formatUri( $string, $separator = '-' )
{
    // $accents_regex = '~&([a-z]{1,2})(?:acute|cedil|circ|grave|lig|orn|ring|slash|th|tilde|uml);~i';
    // $special_cases = array( '&' => 'and', "'" => '');
    // $string = mb_strtolower( trim( $string ), 'UTF-8' );
    // $string = str_replace( array_keys($special_cases), array_values( $special_cases), $string );
    // $string = preg_replace( $accents_regex, '$1', htmlentities( $string, ENT_QUOTES, 'UTF-8' ) );
    // $string = preg_replace("/[^a-z0-9]/u", "$separator", $string);
    // $string = preg_replace("/[$separator]+/u", "$separator", $string);
    // return $string;

    // Remove non-alphanumeric characters
    $string = preg_replace('/[^a-zA-Z0-9]/', $separator, $string);
    // Remove multiple occurrences of the separator
    $string = preg_replace('/' . preg_quote($separator, '/') . '{2,}/', $separator, $string);
    // Trim the separator from the beginning and end of the string
    $string = trim($string, $separator);
    // Convert the string to lowercase
    $string = strtolower($string);
    return $string;
}



function djaPhoneFormat($nohp, $currency) {

	global $wpdb;
    $table_name = $wpdb->prefix . "dyk_settings";

	// $query_currency = $wpdb->get_results('SELECT data from '.$table_name.' where type="currency"  ORDER BY id ASC');
    // $currency = $query_currency[0]->data;

	$nohp = str_replace(" ","",$nohp);
	$nohp = str_replace("(","",$nohp);
	$nohp = str_replace(")","",$nohp);
	$nohp = str_replace(".","",$nohp);
 
     // cek apakah no hp mengandung karakter + dan 0-9
    if(!preg_match('/[^+0-9]/',trim($nohp))){
        // cek apakah no hp karakter 1-3 adalah +62
        if(substr(trim($nohp), 0, 3)=='+62'){
            $hp = substr(trim($nohp), 1);
        }
        // cek apakah no hp karakter 1 adalah 0
        elseif(substr(trim($nohp), 0, 1)=='0'){
        	if($currency=='MYR'){
        		$hp = '60'.substr(trim($nohp), 1);
        	}else{
        		$hp = '62'.substr(trim($nohp), 1);
        	}
            
        }else{
            $hp = $nohp;
        }
    }
     return $hp;
}


