				// notify pembayaran dengan iPaymu
				// {
				// 	"trx_id":121212,
				//     "sid": "C0E6D95C-05D3-4039-9105-333333",
				//     "status":"berhasil",
				//     "via":"Metode pembayaran",
				//     "no_rekening_deposit":jika pembeli memilih opsi pembayaran Transfer Bank (non-member iPaymu)
				// }

				if($_REQUEST['status'] == 'berhasil') {

					$payment_trx_id = $_REQUEST['trx_id'];

					// RACE-CONDITION-FIX (C1): Atomic claim — UPDATE only fires side-effects
					// if it actually transitioned the row from status=0 to status=1. iPaymu
					// retries aggressively on non-2xx, so without this guard two retries can
					// both pass the SELECT check and double-fire WA + email + metapixel.
					$claimed = $wpdb->query( $wpdb->prepare(
						"UPDATE {$table_name2}
						   SET status = 1,
						       payment_at = %s,
						       process_by = 'ipaymu'
						 WHERE payment_trx_id = %s
						   AND status = 0",
						date('Y-m-d H:i:s'),
						$payment_trx_id
					) );

					if ( $claimed > 0 ) {

						$check_payment = $wpdb->get_results( $wpdb->prepare(
							'SELECT * FROM ' . $table_name2 . ' WHERE payment_trx_id = %s',
							$payment_trx_id
						) );
						if ( $check_payment ) {
							$row = $check_payment[0];
						}


				        // GENERAL Settings
					    $query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="currency" or type="wanotif_url" or type="wanotif_apikey" or type="wanotif_message2" or type="wanotif_on" or type="email_on" or type="email_success_message" or type="wanotif_apikey_cs" ORDER BY id ASC');
					    $currency 		  = $query_settings[0]->data;
					    $wanotif_url 	  = $query_settings[1]->data;
					    $wanotif_apikey   = $query_settings[2]->data;
					    $wanotif_message2 = $query_settings[3]->data;
					    $wanotif_on 	  = $query_settings[4]->data;
					    $email_on 	  	  = $query_settings[5]->data;
					    $email_success_message = $query_settings[6]->data;
					    $wanotif_apikey_cs = $query_settings[7]->data;

						// GET DATA DONASI (extra fields from JOIN: title/slug/notification_status/wanotif_message2)
					    $row_join = $wpdb->get_results( $wpdb->prepare(
					    	'SELECT b.title, b.slug, b.notification_status, b.wanotif_message2
					    	   FROM ' . $table_name2 . ' a
					    	   LEFT JOIN ' . $table_name3 . ' b ON b.campaign_id = a.campaign_id
					    	  WHERE a.id = %d',
					    	$row->id
					    ) );
					    if ( $row_join ) {
					    	$row->title               = $row_join[0]->title;
					    	$row->slug                = $row_join[0]->slug;
					    	$row->notification_status = $row_join[0]->notification_status;
					    	$row->wanotif_message2    = $row_join[0]->wanotif_message2;
					    }

				        if (isset($row->wanotif_message2)){
				        	if($row->notification_status == '1') {
				        		$wanotif_message2 = $row->wanotif_message2;
				        	}
				        }
					    
					    $data_field = array();
					    $data_field[ '{name}' ] 	= $row->name;
					    $data_field[ '{sapaan}' ] 	= $row->sapaan;
					    $data_field[ '{salam}' ] 	= $row->sapaan;
					    $data_field[ '{whatsapp}' ] = $row->whatsapp;
					    $data_field[ '{email}' ] 	= $row->email;
					    $data_field[ '{comment}' ] 	= $row->comment;
					    $data_field[ '{payment_number}' ] 	= $row->payment_number;
					    $data_field[ '{payment_code}' ] 	= paymentCode($row->payment_code);
					    $data_field[ '{payment_account}' ] 	= $row->payment_account;
					    $data_field[ '{campaign_title}' ] 	= $row->title;
					    $data_field[ '{campaign_url}' ] 	= get_site_url().'/campaign/'.$row->slug;
					    $data_field[ '{invoice_id}' ] 		= $row->invoice_id;
					    $data_field[ '{date}' ] 			= $datenya = date("j F Y - h:i",strtotime($row->created_at));
					    $data_field[ '{link_ekuitansi}' ] 	= get_site_url().'/ekuitansi/'.$row->invoice_id;
					    $data_field[ '{link_sertifikat}' ] 	= get_site_url().'/sertifikat/'.$row->invoice_id;
					    
					    if($currency=='IDR'){
					    	$data_field[ '{total}' ] 	= 'Rp '.number_format_currency($row->nominal);
					    }elseif($currency=='MYR'){
					    	$data_field[ '{total}' ] 	= 'RM '.number_format_currency($row->nominal);
					    }else{
					    	$data_field[ '{total}' ] 	= $row->nominal;
					    }

					    // device id diambil dari cs id table donate
						if($row->cs_id!=null){
			                $data_cs = json_decode($wanotif_apikey_cs, true);

			            	foreach ($data_cs['data'] as $key => $value) {
			                	if($row->cs_id==$value[0]){
			                		$wanotif_apikey_cs = $value[1];
			                		if($wanotif_apikey_cs!=''){
										$wanotif_apikey = $wanotif_apikey_cs;
									}
									break;
			                	}
