// Run the function on admin_init
function donasiyuk_remove_profile_menu() {
	global $wpdb, $pagenow;
	$user = wp_get_current_user();
	if ( ! $user || ! $user->ID ) {
		return;
	}
	$roles = (array) $user->roles;
	$role = ! empty( $roles ) ? $roles[0] : '';

	if ( $role === 'cs' || $role === 'donatur' ) {
		remove_submenu_page( 'upload.php', 'media-new.php' );
		remove_menu_page( 'upload.php' );

		remove_submenu_page( 'users.php', 'profile.php' );
		remove_menu_page( 'profile.php' );

		remove_submenu_page( 'index.php', 'index.php' );
		remove_menu_page( 'index.php' );

		// Server-side redirect for donatur to prevent browser JS redirect flicker
		if ( $role === 'donatur' && ( ! defined( 'DOING_AJAX' ) || ! DOING_AJAX ) && ( ! function_exists( 'wp_doing_ajax' ) || ! wp_doing_ajax() ) ) {
			if ( $pagenow === 'index.php' && ! isset( $_GET['page'] ) ) {
				wp_safe_redirect( admin_url( 'admin.php?page=donasiyuk_dashboard' ) );
				exit;
			}
			if ( $pagenow === 'profile.php' ) {
				wp_safe_redirect( admin_url( 'admin.php?page=donasiyuk_myprofile' ) );
				exit;
			}
		}
	}
}
add_action('admin_init', 'donasiyuk_remove_profile_menu');



