function set_time_donasiaja(){
	
	global $wpdb;
	$table_name = $wpdb->prefix . 'dyk_settings';

	$query_settings = $wpdb->get_results('SELECT data from '.$table_name.' where type="currency" ORDER BY id ASC');
	$currency 	= $query_settings[0]->data;

	if($currency=='IDR'){
		date_default_timezone_set('Asia/Jakarta');
	}elseif($currency=='MYR'){
		date_default_timezone_set('Asia/Kuala_Lumpur');
	}elseif(wp_timezone_string()=='Asia/Jakarta'){
		date_default_timezone_set('Asia/Jakarta');
	}elseif(wp_timezone_string()=='Asia/Kuala_Lumpur'){
		date_default_timezone_set('Asia/Kuala_Lumpur');
	}elseif(wp_timezone_string()=='+07:00'){
		date_default_timezone_set('Asia/Jakarta');
	}else{
		date_default_timezone_set('Asia/Jakarta');
	}

}


function donasiyuk_global_vars() {

	set_time_donasiaja();

	global $wpdb;
	global $donasiyuk_vars;

	// DonasiYuk fork: license hardcoded to ULTIMATE/valid/10 tahun ke depan.
	// Tidak ada DB lookup, tidak ada server call ke member.donasiaja.id.
	// Semua gate license (32 UI + 9 page-level) otomatis resolved.
	$donasiyuk_vars = array(
		'expired'           => false,
		'date_expired'      => strtotime( '+10 years' ),
		'plugin_name'       => 'DonasiYuk',
