    // jika bukan Donatur
    if($role!='donatur'){

    	$user_on_review = $wpdb->get_results('SELECT id from '.$table_name.' where user_verification="2"');

    	if($user_on_review!=null){
    		$jumlah_on_review = '('.count($user_on_review).')';
    	}else{
    		$jumlah_on_review = '';
    	}

    	if($role=='administrator' || $role=='cs'){
    		if($fundraiser_on=='1'){
    			if($plugin_license=='ULTIMATE') {
					add_submenu_page('donasiyuk_dashboard', //parent slug
					'Fundraising | DonasiYuk', //page title
					'<i data-lucide="share-2" class="dyk-submenu-icon"></i> Fundraising', //menu title
					'read', //capability
					'donasiyuk_data_fundraising', //menu slug
					'donasiyuk_data_fundraising'); //function
				}
			}
		}
        
   		if($role!='cs'){
		add_submenu_page('donasiyuk_dashboard', //parent slug
		'Shortcode | DonasiYuk', //page title
		'<i data-lucide="code" class="dyk-submenu-icon"></i> Shortcode', //menu title
		'read', //capability
		'donasiyuk_data_shortcodes', //menu slug
		'donasiyuk_data_shortcodes'); //function
		}

		if($role=='administrator'){
		add_submenu_page('donasiyuk_dashboard', //parent slug
		'Anggota | DonasiYuk', //page title
		'<i data-lucide="users" class="dyk-submenu-icon"></i> Anggota '.$jumlah_on_review.'', //menu title
		'read', //capability
		'donasiyuk_data_members', //menu slug
		'donasiyuk_data_members'); //function
		}

	}

	if($role!='donatur'){
		add_submenu_page('donasiyuk_dashboard', //parent slug
		'Donasi Saya | DonasiYuk', //page title
		'<i data-lucide="wallet" class="dyk-submenu-icon"></i> Donasi Saya', //menu title
		'read', //capability
		'donasiyuk_mydonate', //menu slug
		'donasiyuk_mydonate'); //function

		add_submenu_page('donasiyuk_dashboard', //parent slug
		'Profil Saya | DonasiYuk', //page title
		'<i data-lucide="user" class="dyk-submenu-icon"></i> Profil Saya', //menu title
		'read', //capability
		'donasiyuk_myprofile', //menu slug
		'donasiyuk_myprofile'); //function
	}

	// jika bukan Donatur
    if($role=='administrator'){

		add_submenu_page('donasiyuk_dashboard', //parent slug
		'Pengaturan | DonasiYuk', //page title
		'<i data-lucide="settings" class="dyk-submenu-icon"></i> Pengaturan', //menu title
		'read', //capability
		'donasiyuk_settings', //menu slug
		'donasiyuk_settings'); //function

	}
	

}
